// Content for Bounce (node g39, ages 12–15, Chapter 4) — NEW v2 build to GDD 39 (mechanic-embodying), the
// resilience + stress + teen-mental-health node (Thread C · Feelings & Life Skills). "Bounce back, the real
// way." 84 researched, India-grounded scenarios across the what-resilience → reframe-setback → bounce-toolkit
// → exam-pressure → support-friend → reach-out arc, each encoded as one of the shared v2 play actions (branch /
// strike-rewrite / role-play / reflect / sort / build / match) — no binary "tap the right card". Lead
// mechanics: branch (choose the move that actually helps ×19), strike-rewrite (bust the resilience myth ×17),
// role-play (say the brave words ×12). Teaches: real resilience (not toughing-it-out or toxic positivity),
// reframing a real setback, a coping toolkit that's REAL not a poster, exam/performance pressure, being there
// for a struggling friend, and when + how to reach out. WELLBEING-SAFE: no toxic positivity, no pain-based
// coping; persistent distress and any dark thoughts route FIRMLY to a trusted adult, **Tele-MANAS 14416**, or
// **Childline 1098 / 112** (crisis-routing first, never therapy). Builds on g38 (Mind Matters); prereq g21.
// Rendered by the shared engine (components/games/v2-engine.tsx). gameId "bounce". DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // — What resilience really is —
  {"id":"bn-001","cat":"what-resilience","type":"strike-rewrite","hook":"\"Resilient people just don't feel bad when things go wrong.\"","myth":{"un":"Being resilient means not feeling bad when things go wrong.","re":"Resilience is feeling the hurt and then finding a way through, not skipping it.","why":"You can't bounce back from something you won't let yourself feel."},"relearn":"Resilience is moving through hard feelings, not avoiding them.","persona":"Veer","source":"resilience concept"},
  {"id":"bn-002","cat":"what-resilience","type":"strike-rewrite","hook":"\"Just think positive and you'll be fine.\"","myth":{"un":"You just have to think positive and you'll be fine.","re":"Forcing 'positive' ignores real feelings; honest coping works better.","why":"Toxic positivity buries problems instead of solving them."},"relearn":"Honest coping beats forced positivity; it's okay to not be okay.","persona":"any","source":"anti-toxic-positivity"},
  {"id":"bn-003","cat":"what-resilience","type":"strike-rewrite","hook":"\"Bouncing back should be instant.\"","myth":{"un":"If you're strong, you bounce back instantly.","re":"Recovery takes time; bouncing back is a process, not a switch.","why":"Healing on a timer isn't how people actually work."},"relearn":"Bouncing back takes time; it's a process, not a switch.","persona":"Riya","source":"resilience concept"},
  {"id":"bn-004","cat":"what-resilience","type":"strike-rewrite","hook":"\"Some people are just born resilient and others aren't.\"","myth":{"un":"Resilience is something you're born with or not.","re":"Resilience is a skill anyone can build with practice and support.","why":"It grows; it isn't fixed."},"relearn":"Resilience is a skill you can build, not a fixed trait.","persona":"any","source":"resilience is learnable"},
  {"id":"bn-005","cat":"what-resilience","type":"strike-rewrite","hook":"\"Needing other people means you're not really resilient.\"","myth":{"un":"Truly resilient people don't need anyone.","re":"Leaning on caring people is one of the biggest sources of resilience.","why":"At least one supportive relationship is a top protective factor."},"relearn":"Leaning on others is a core part of resilience, not a weakness.","persona":"Veer","source":"supportive relationships (evidence)"},
  {"id":"bn-006","cat":"what-resilience","type":"reflect","hook":"Lensy: think of a hard thing you got through before. You bounced once, you can again. Feel that?","prompt":"What do you think?","options":["Yes","I have done hard things","I'm stronger than I feel"],"affirm":"Past bounce-backs are real proof of what you can do.","relearn":"Remembering past recoveries is evidence you can cope again.","persona":"any","source":"self-efficacy"},
  {"id":"bn-007","cat":"what-resilience","type":"reflect","hook":"Lensy: 'coping that's real, not a poster' means honest, doable, yours. Like that?","prompt":"What do you think?","options":["Yes","Real over slogans","That helps"],"affirm":"Real coping fits your actual life, not a motivational poster.","relearn":"Real resilience is honest and doable, not a slogan.","persona":"Veer","source":"authenticity"},
  {"id":"bn-008","cat":"what-resilience","type":"reflect","hook":"Lensy: setbacks are part of every worthwhile life, not a sign you've failed at life. Agree?","prompt":"What do you think?","options":["Yes","Everyone has them","Less alone now"],"affirm":"Setbacks are universal; they're a comma, not a full stop.","relearn":"Setbacks are a normal part of life, not proof you've failed.","persona":"any","source":"normalising"},
  {"id":"bn-009","cat":"what-resilience","type":"sort","hook":"Sort: real resilience, or toxic positivity?","items":[{"id":"a","text":"\"This is hard, and I'll get through it\""},{"id":"b","text":"\"Just be happy, ignore it\""},{"id":"c","text":"\"I'll feel this, then make a plan\""},{"id":"d","text":"\"Good vibes only, no sad stuff\""},{"id":"e","text":"\"I can ask for help with this\""},{"id":"f","text":"\"Real strength means feeling nothing\""}],"bins":[{"id":"real","label":"Real resilience","valence":"pos"},{"id":"toxic","label":"Toxic positivity","valence":"neg"}],"key":{"a":"real","b":"toxic","c":"real","d":"toxic","e":"real","f":"toxic"},"relearn":"Real resilience allows hard feelings; toxic positivity bans them.","persona":"any","source":"anti-toxic-positivity"},
  {"id":"bn-010","cat":"what-resilience","type":"sort","hook":"Sort: builds resilience, or chips at it?","items":[{"id":"a","text":"A caring person to talk to"},{"id":"b","text":"Bottling everything up"},{"id":"c","text":"Reframing a failure as learning"},{"id":"d","text":"Harsh self-blame"},{"id":"e","text":"Resting when you need it"},{"id":"f","text":"Telling yourself you're hopeless"}],"bins":[{"id":"builds","label":"Builds it","valence":"pos"},{"id":"chips","label":"Chips at it","valence":"neg"}],"key":{"a":"builds","b":"chips","c":"builds","d":"chips","e":"builds","f":"chips"},"relearn":"Support, reframing and rest build resilience; bottling and self-blame erode it.","persona":"any","source":"resilience factors"},
  {"id":"bn-011","cat":"what-resilience","type":"sort","hook":"Sort: a setback you can grow from, or proof you're worthless?","items":[{"id":"a","text":"A failed test"},{"id":"b","text":"\"So I'm worthless\""},{"id":"c","text":"A rejection"},{"id":"d","text":"\"I'll never be good enough\""},{"id":"e","text":"A missed goal"},{"id":"f","text":"\"Everyone is better than me\""}],"bins":[{"id":"grow","label":"Setback to grow from","valence":"pos"},{"id":"false","label":"False, harsh story","valence":"neg"}],"key":{"a":"grow","b":"false","c":"grow","d":"false","e":"grow","f":"false"},"relearn":"A setback is a setback; 'I'm worthless' is a false story.","persona":"Riya","source":"cognitive"},
  {"id":"bn-012","cat":"what-resilience","type":"match","hook":"Match the resilience ingredient to what it gives you.","pairs":[{"left":"Growth mindset","right":"Keep trying after a flop"},{"left":"A caring person","right":"You're not alone"},{"left":"Small steps","right":"A way forward"},{"left":"Self-compassion","right":"A break from self-blame"},{"left":"Honest feelings","right":"Space to actually heal"}],"relearn":"Resilience is built from mindset, support, steps, kindness and honesty.","persona":"any","source":"resilience factors"},
  // — Reframe the setback —
  {"id":"bn-013","cat":"reframe-setback","type":"strike-rewrite","hook":"\"Failing means I'm a failure.\"","myth":{"un":"If I fail at something, I am a failure.","re":"Failing at a thing is an event, not your identity.","why":"What you do isn't all of who you are."},"relearn":"Failing at something doesn't make you 'a failure'.","persona":"Veer","source":"growth mindset"},
  {"id":"bn-014","cat":"reframe-setback","type":"strike-rewrite","hook":"\"If I can't do it, that's final.\"","myth":{"un":"I can't do it, full stop.","re":"You can't do it yet, with practice that can change.","why":"'Yet' keeps the door open."},"relearn":"Add 'yet': 'I can't do it yet' keeps growth possible.","persona":"any","source":"growth mindset ('not yet')"},
  {"id":"bn-015","cat":"reframe-setback","type":"strike-rewrite","hook":"\"A mistake is wasted, there's nothing good in it.\"","myth":{"un":"A mistake is just a waste.","re":"A mistake is data, it shows you what to try differently.","why":"Most learning is built on mistakes."},"relearn":"A mistake is useful data for next time, not a waste.","persona":"any","source":"failure as learning"},
  {"id":"bn-016","cat":"reframe-setback","type":"strike-rewrite","hook":"\"Everyone saw me fail; I can never recover from the shame.\"","myth":{"un":"People saw me fail, so I'll never live it down.","re":"People forget far faster than you fear; this will pass.","why":"Others are mostly focused on themselves."},"relearn":"Public stumbles fade fast; you will live it down.","persona":"Riya","source":"spotlight effect"},
  {"id":"bn-017","cat":"reframe-setback","type":"strike-rewrite","hook":"\"One bad result ruins my whole future.\"","myth":{"un":"One bad result ruins my entire future.","re":"One result is one moment; there are many paths forward.","why":"Lives rarely turn on a single score."},"relearn":"One bad result doesn't decide your whole future.","persona":"Veer","source":"exam pressure / reframe"},
  {"id":"bn-018","cat":"reframe-setback","type":"strike-rewrite","hook":"\"If I reframe it, I'm just pretending it doesn't hurt.\"","myth":{"un":"Reframing means pretending it doesn't hurt.","re":"Reframing holds both: it hurts, and there's a way forward.","why":"You can be honest and hopeful at once."},"relearn":"Reframing isn't denial; it holds the hurt and the hope together.","persona":"any","source":"reframing vs denial"},
  {"id":"bn-019","cat":"reframe-setback","type":"branch","hook":"You bombed a test you studied hard for.","options":[{"text":"Let yourself be gutted, then look at what to change","consequence":"You feel it, learn from it, and move on stronger.","outcome":"resilient","best":true},{"text":"Decide you're hopeless and stop trying","consequence":"Feel it, then treat it as data, you're not hopeless."}],"debrief":"Feel the disappointment, then mine it for what to do differently.","relearn":"Feel the setback, then turn it into a lesson.","persona":"Veer","source":"bounce-back"},
  {"id":"bn-020","cat":"reframe-setback","type":"branch","hook":"You didn't make the team or the role you wanted.","options":[{"text":"Grieve it, then look for the next chance or a new path","consequence":"You stay open instead of shutting down.","outcome":"open","best":true},{"text":"Give up on the whole thing","consequence":"A 'no' can redirect you; stay open to the next chance."}],"debrief":"A closed door can point you to a different, good one.","relearn":"A rejection can redirect you; keep looking forward.","persona":"Riya","source":"reframe"},
  {"id":"bn-021","cat":"reframe-setback","type":"branch","hook":"You're stuck replaying a mistake on a loop.","options":[{"text":"Name one lesson, then deliberately shift your focus","consequence":"You break the loop and free up your mind.","outcome":"unstuck","best":true},{"text":"Keep replaying it endlessly","consequence":"Pull one lesson, then redirect; looping just hurts."}],"debrief":"Take the lesson, then choose to put the loop down.","relearn":"Extract the lesson, then deliberately stop the replay.","persona":"any","source":"rumination"},
  {"id":"bn-022","cat":"reframe-setback","type":"branch","hook":"A friend nails what you struggled with, and envy stings.","options":[{"text":"Let it teach you, ask how they did it, run your own race","consequence":"Envy becomes information and motivation.","outcome":"growth","best":true},{"text":"Spiral into 'I'm worse than everyone'","consequence":"Turn envy into a question, not a verdict on you."}],"debrief":"Envy can point to what you want; use it, don't drown in it.","relearn":"Turn envy into curiosity and your own next step.","persona":"Riya","source":"comparison / growth"},
  {"id":"bn-023","cat":"reframe-setback","type":"reflect","hook":"Lensy: what's one setback that, looking back, taught you something useful?","prompt":"Think of one.","options":["A failure that taught me","A loss that grew me","A mistake I learned from"],"affirm":"That's resilience in your own history, proof it works.","relearn":"Past setbacks often became lessons; this one can too.","persona":"any","source":"reframing"},
  {"id":"bn-024","cat":"reframe-setback","type":"reflect","hook":"Lensy: would you judge a friend as harshly for this as you're judging yourself?","prompt":"What do you think?","options":["No","I'd be kinder to them","I'll be kinder to me"],"affirm":"Offer yourself the same grace you'd give a friend.","relearn":"Be as fair to yourself after a setback as you'd be to a friend.","persona":"any","source":"self-compassion"},
  {"id":"bn-025","cat":"reframe-setback","type":"sort","hook":"Sort: a growth-mindset thought, or a fixed one?","items":[{"id":"a","text":"\"I can improve with practice\""},{"id":"b","text":"\"I'm just bad at this, always\""},{"id":"c","text":"\"Mistakes help me learn\""},{"id":"d","text":"\"Smart people never struggle\""},{"id":"e","text":"\"That feedback shows me my next step\""},{"id":"f","text":"\"If it's hard, I'm just not the type\""}],"bins":[{"id":"growth","label":"Growth mindset","valence":"pos"},{"id":"fixed","label":"Fixed mindset","valence":"neg"}],"key":{"a":"growth","b":"fixed","c":"growth","d":"fixed","e":"growth","f":"fixed"},"relearn":"Growth-mindset thoughts keep you trying; fixed ones stop you.","persona":"any","source":"growth mindset"},
  {"id":"bn-026","cat":"reframe-setback","type":"sort","hook":"Sort: helps you bounce, or keeps you down?","items":[{"id":"a","text":"\"What can I learn here?\""},{"id":"b","text":"\"I always ruin everything\""},{"id":"c","text":"\"This is hard but temporary\""},{"id":"d","text":"\"It'll be like this forever\""},{"id":"e","text":"\"One step at a time, I can move\""},{"id":"f","text":"\"There's no point even trying\""}],"bins":[{"id":"bounce","label":"Helps you bounce","valence":"pos"},{"id":"down","label":"Keeps you down","valence":"neg"}],"key":{"a":"bounce","b":"down","c":"bounce","d":"down","e":"bounce","f":"down"},"relearn":"'What can I learn' and 'this is temporary' help you bounce back.","persona":"any","source":"cognitive reframing"},
  // — The bounce-back toolkit —
  {"id":"bn-027","cat":"bounce-toolkit","type":"build","hook":"Build your bounce-back routine after a knock.","prompt":"Order the steps that actually help.","pieces":["let yourself feel it","talk to someone you trust","find one lesson","take one small next step"],"mode":"sequence","key":["let yourself feel it","talk to someone you trust","find one lesson","take one small next step"],"relearn":"Bounce back: feel it, talk it out, find the lesson, take one step.","persona":"any","source":"bounce-back process"},
  {"id":"bn-028","cat":"bounce-toolkit","type":"build","hook":"Build a 'shrink the comeback' plan for a big goal you slipped on.","prompt":"Break it into doable steps.","pieces":["name the goal again","break it into small parts","do the first small part today","celebrate that small win"],"mode":"sequence","key":["name the goal again","break it into small parts","do the first small part today","celebrate that small win"],"relearn":"Comebacks are built from small steps and small wins.","persona":"Veer","source":"SMART goals / small steps"},
  {"id":"bn-029","cat":"bounce-toolkit","type":"build","hook":"Build a calm-the-storm kit for when stress spikes.","prompt":"Pick real, healthy tools.","pieces":["slow breathing","move your body","write it down","reach out to someone"],"mode":"assemble","key":["slow breathing","move your body","write it down","reach out to someone"],"relearn":"Regulate stress with breath, movement, writing, and reaching out.","persona":"any","source":"emotional regulation"},
  {"id":"bn-030","cat":"bounce-toolkit","type":"build","hook":"Build a 'zoom out' perspective check.","prompt":"Order questions that widen the view.","pieces":["will this matter in a year?","what's still okay right now?","what's one thing I can control?","who can help?"],"mode":"sequence","key":["will this matter in a year?","what's still okay right now?","what's one thing I can control?","who can help?"],"relearn":"Zooming out (time, what's okay, control, help) shrinks a setback.","persona":"any","source":"perspective-taking"},
  {"id":"bn-031","cat":"bounce-toolkit","type":"build","hook":"Build a self-compassion line to use after a flop.","prompt":"Assemble a kind, true message to yourself.","pieces":["this is genuinely hard","anyone would struggle with this","I'm allowed to find it tough","I'll get through it"],"mode":"assemble","key":["this is genuinely hard","anyone would struggle with this","I'm allowed to find it tough","I'll get through it"],"relearn":"A self-compassion line steadies you faster than self-attack.","persona":"any","source":"self-compassion"},
  {"id":"bn-032","cat":"bounce-toolkit","type":"branch","hook":"After a hard knock, your instinct is to isolate.","options":[{"text":"Reach out to one trusted person anyway","consequence":"Connection eases the weight; you're not alone.","outcome":"connected","best":true},{"text":"Shut everyone out","consequence":"Isolation deepens it; one caring person helps most."}],"debrief":"One caring connection is the strongest bounce-back tool there is.","relearn":"Reach out instead of isolating after a setback.","persona":"Veer","source":"supportive relationships"},
  {"id":"bn-033","cat":"bounce-toolkit","type":"branch","hook":"Stress is so high you can't think straight before a deadline.","options":[{"text":"Take a short reset, breathe, then start one small piece","consequence":"Your mind clears enough to begin.","outcome":"regulated","best":true},{"text":"Spiral and freeze","consequence":"A short reset and one small step beat freezing."}],"debrief":"Regulate first, then act; a frozen mind can't problem-solve.","relearn":"Calm the body first, then take one small step.","persona":"any","source":"regulate-then-act"},
  {"id":"bn-034","cat":"bounce-toolkit","type":"branch","hook":"You want to give your comeback the best shot.","options":[{"text":"Protect sleep, movement and one caring connection","consequence":"Your basics fuel your resilience.","outcome":"resourced","best":true},{"text":"Skip sleep and grind alone","consequence":"Sleep, movement and connection are resilience fuel."}],"debrief":"Resilience runs on the basics: rest, movement, connection.","relearn":"Sleep, movement and connection power your bounce-back.","persona":"any","source":"resilience basics"},
  {"id":"bn-035","type":"sort","hook":"Sort: a real coping tool, or an empty, avoidant one?","items":[{"id":"a","text":"Talking it through with someone"},{"id":"b","text":"Endless doomscrolling"},{"id":"c","text":"A walk or a workout"},{"id":"d","text":"Pretending you're fine"},{"id":"e","text":"Writing how you feel in a diary"},{"id":"f","text":"Bottling it up till you burst"}],"bins":[{"id":"real","label":"Real coping","valence":"pos"},{"id":"avoid","label":"Empty / avoidant","valence":"neg"}],"key":{"a":"real","b":"avoid","c":"real","d":"avoid","e":"real","f":"avoid"},"relearn":"Real coping connects and moves you; avoidance just numbs the feeling.","persona":"any","source":"coping","cat":"bounce-toolkit"},
  {"id":"bn-036","type":"sort","hook":"Sort: in your control, or not, after a setback?","items":[{"id":"a","text":"My next effort"},{"id":"b","text":"What already happened"},{"id":"c","text":"Asking for help"},{"id":"d","text":"Others' opinions of me"},{"id":"e","text":"How I plan tomorrow"},{"id":"f","text":"The result that's already out"}],"bins":[{"id":"control","label":"In my control","valence":"pos"},{"id":"not","label":"Not in my control","valence":"neutral"}],"key":{"a":"control","b":"not","c":"control","d":"not","e":"control","f":"not"},"relearn":"Spend energy on what you control: your next step and asking for help.","persona":"any","source":"locus of control","cat":"bounce-toolkit"},
  {"id":"bn-037","cat":"bounce-toolkit","type":"reflect","hook":"Lensy: which bounce-back tool will you actually use next time?","prompt":"Pick your go-to.","options":["Talk to someone","Breathe and reset","One small step","Zoom out"],"affirm":"Having a go-to tool ready makes the next knock easier.","relearn":"A ready bounce-back tool helps you recover faster.","persona":"any","source":"coping / readiness"},
  {"id":"bn-038","cat":"bounce-toolkit","type":"reflect","hook":"Lensy: rest is part of bouncing back, not a reward you must earn. Believe it?","prompt":"What do you think?","options":["Yes","Rest helps me recover","I'll allow it"],"affirm":"Rest refuels the resilience tank; it's allowed.","relearn":"Rest is part of recovery, not a reward to earn.","persona":"Veer","source":"rest / recovery"},
  // — Exam & performance pressure —
  {"id":"bn-039","cat":"exam-pressure","type":"branch","hook":"Board exams loom and the pressure feels crushing.","options":[{"text":"Make a realistic plan, protect rest, and ask for support","consequence":"The mountain becomes a set of steps.","outcome":"steady","best":true},{"text":"Panic, skip sleep, and spiral","consequence":"A plan, rest and support steady you better than panic."}],"debrief":"Exam pressure shrinks with a plan, rest and people in your corner.","relearn":"Face exam pressure with a plan, rest and support, not panic.","persona":"Veer","source":"exam stress (India)"},
  {"id":"bn-040","cat":"exam-pressure","type":"branch","hook":"Everyone's comparing marks and predicted ranks; it's spiking your anxiety.","options":[{"text":"Step back from the comparison and focus on your own plan","consequence":"Your anxiety eases and focus returns.","outcome":"grounded","best":true},{"text":"Join the rank-comparison frenzy","consequence":"Comparison fuels anxiety; run your own race."}],"debrief":"Comparing ranks feeds the spiral; your plan is what helps.","relearn":"Step out of rank-comparison; focus on your own progress.","persona":"Riya","source":"comparison / exam stress"},
  {"id":"bn-041","cat":"exam-pressure","type":"branch","hook":"A parent says your whole future rides on this one exam.","options":[{"text":"Hear their worry, but remember one exam isn't your whole life","consequence":"You keep perspective and lower the stakes.","outcome":"perspective","best":true},{"text":"Absorb it as total truth and panic","consequence":"Their worry is real, but one exam isn't your entire future."}],"debrief":"Love can sound like pressure; one exam isn't your whole life.","relearn":"One exam isn't your whole future, whatever the pressure says.","persona":"Veer","source":"exam pressure / family (India)"},
  {"id":"bn-042","cat":"exam-pressure","type":"branch","hook":"You did poorly in a big exam and feel like you've let everyone down.","options":[{"text":"Talk to a trusted adult about next steps and other paths","consequence":"You find there's more than one road forward.","outcome":"supported","best":true},{"text":"Carry it all alone in silence","consequence":"Silence hides the other paths a trusted adult could show you."}],"debrief":"A low result is survivable, and there's always another path.","relearn":"A poor result isn't the end; talk it through and find another path.","persona":"Counsellor","source":"exam stress / help-seeking"},
  {"id":"bn-043","cat":"exam-pressure","type":"branch","hook":"Exam stress is affecting your sleep and appetite for weeks.","options":[{"text":"Tell a trusted adult or call Tele-MANAS (14416) for support","consequence":"You get real help with the stress.","outcome":"supported","best":true},{"text":"Push through alone and hope it passes","consequence":"Weeks of stress affecting sleep and eating deserve support."}],"debrief":"When stress hits sleep and appetite for weeks, reach out for help.","relearn":"Lasting exam stress deserves a trusted adult or Tele-MANAS (14416).","persona":"Counsellor","source":"help-seeking / Tele-MANAS"},
  {"id":"bn-044","cat":"exam-pressure","type":"strike-rewrite","hook":"\"My marks decide my worth as a person.\"","myth":{"un":"My marks decide how much I'm worth.","re":"Marks measure one exam on one day, not your value.","why":"Your worth is not a number on a result sheet."},"relearn":"Marks measure a test, not your worth as a person.","persona":"Riya","source":"exam pressure (India)"},
  {"id":"bn-045","cat":"exam-pressure","type":"strike-rewrite","hook":"\"There's only one acceptable career path, and this exam is it.\"","myth":{"un":"There's only one path, and this exam is the only gate.","re":"There are many paths to a good life and career.","why":"Success has countless routes, not one gate."},"relearn":"There are many paths to a good life, not just one exam.","persona":"Veer","source":"exam pressure / paths"},
  {"id":"bn-046","cat":"exam-pressure","type":"strike-rewrite","hook":"\"Taking breaks while studying is lazy.\"","myth":{"un":"Breaks while studying are just laziness.","re":"Breaks and sleep are what let your brain actually learn.","why":"A rested brain remembers; a fried one doesn't."},"relearn":"Breaks and sleep help you learn; they aren't laziness.","persona":"any","source":"study / rest"},
  {"id":"bn-047","type":"sort","hook":"Sort: helps under exam pressure, or harms?","items":[{"id":"a","text":"A realistic study plan"},{"id":"b","text":"All-night cramming, no sleep"},{"id":"c","text":"Short breaks and rest"},{"id":"d","text":"Comparing ranks constantly"},{"id":"e","text":"Asking a teacher when stuck"},{"id":"f","text":"Skipping meals to study more"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"harms","label":"Harms","valence":"neg"}],"key":{"a":"helps","b":"harms","c":"helps","d":"harms","e":"helps","f":"harms"},"relearn":"Plans, rest and asking help work; no-sleep cramming and skipping meals harm.","persona":"any","source":"exam strategies","cat":"exam-pressure"},
  {"id":"bn-048","type":"sort","hook":"Sort: a true source of your worth, or just exam pressure talking?","items":[{"id":"a","text":"How you treat people"},{"id":"b","text":"Your exam rank"},{"id":"c","text":"Your curiosity and effort"},{"id":"d","text":"A single test score"},{"id":"e","text":"Showing up for friends"},{"id":"f","text":"Beating your seatmate's marks"}],"bins":[{"id":"true","label":"Real worth","valence":"pos"},{"id":"pressure","label":"Pressure talking","valence":"neg"}],"key":{"a":"true","b":"pressure","c":"true","d":"pressure","e":"true","f":"pressure"},"relearn":"Your worth is your character and effort, not a rank or score.","persona":"any","source":"self-worth","cat":"exam-pressure"},
  {"id":"bn-049","cat":"exam-pressure","type":"reflect","hook":"Lensy: imagine it's ten years from now. How much will this one exam matter?","prompt":"What do you think?","options":["Much less","Barely","Good to remember"],"affirm":"Most of what feels huge now softens a lot with time.","relearn":"Most single exams matter far less in the long run.","persona":"any","source":"perspective"},
  {"id":"bn-050","cat":"exam-pressure","type":"reflect","hook":"Lensy: what's one thing you're good at that no exam can measure?","prompt":"Think of one.","options":["Being kind","Making people laugh","Fixing things","Sticking with friends"],"affirm":"Those strengths are real and they matter in life, deeply.","relearn":"You have real strengths no exam can measure.","persona":"any","source":"self-worth"},
  {"id":"bn-051","type":"match","hook":"Match the pressure thought to a steadier truth.","pairs":[{"left":"\"I must be perfect\"","right":"Doing my best is enough"},{"left":"\"One score defines me\"","right":"I'm far more than a score"},{"left":"\"No time to rest\"","right":"Rest helps me perform"},{"left":"\"I'm behind everyone\"","right":"I run my own race"},{"left":"\"One exam decides my life\"","right":"Many paths lie ahead"}],"relearn":"Each pressure thought has a steadier, truer reply.","persona":"any","source":"reframing","cat":"exam-pressure"},
  // — Being there for a friend —
  {"id":"bn-052","cat":"support-friend","type":"role-play","hook":"A friend says they're really struggling lately.","setup":"Open the door, don't fix. Say:","yourLine":[{"text":"\"That sounds really hard. I'm here, do you want to talk?\"","best":true},{"text":"\"Just cheer up, it's not a big deal.\""}],"relearn":"Start with listening and presence, not fixing or dismissing.","persona":"any","source":"peer support / listening"},
  {"id":"bn-053","cat":"support-friend","type":"role-play","hook":"A friend opens up; you don't know how to 'solve' it.","setup":"You don't have to solve it. Say:","yourLine":[{"text":"\"I don't have all the answers, but I'm not going anywhere.\"","best":true},{"text":"\"Here's exactly what you should do...\" (then list fixes)"}],"relearn":"Being present matters more than having the perfect fix.","persona":"any","source":"peer support"},
  {"id":"bn-054","cat":"support-friend","type":"role-play","hook":"A friend brushes off their own pain with a joke.","setup":"Gently let them know it's safe. Say:","yourLine":[{"text":"\"You can be real with me, I won't judge you.\"","best":true},{"text":"\"Haha yeah, anyway...\""}],"relearn":"Letting a friend know it's safe to be real opens the door.","persona":"Veer","source":"peer support"},
  {"id":"bn-055","cat":"support-friend","type":"role-play","hook":"A friend shares something heavy and asks you to tell no one, ever.","setup":"Care honestly about safety. Say:","yourLine":[{"text":"\"I've got you, but if you're in danger I'll help you get an adult, because I care.\"","best":true},{"text":"\"Okay, I promise I'll never tell anyone.\""}],"relearn":"Don't promise secrecy about safety; caring means helping them get help.","persona":"any","source":"safeguarding / secrets"},
  {"id":"bn-056","cat":"support-friend","type":"role-play","hook":"You want to check in on a friend who's gone quiet and withdrawn.","setup":"Reach out simply. Say:","yourLine":[{"text":"\"Hey, I've noticed you've seemed down. I'm here if you want to talk.\"","best":true},{"text":"Say nothing and hope they're fine"}],"relearn":"A simple 'I noticed, I'm here' can mean everything to someone.","persona":"any","source":"peer support / noticing"},
  {"id":"bn-057","cat":"support-friend","type":"role-play","hook":"Helping a friend take the step to tell an adult.","setup":"Offer to go with them. Say:","yourLine":[{"text":"\"Let's tell someone who can help, I'll come with you.\"","best":true},{"text":"\"You should probably tell someone\" (then leave it)"}],"relearn":"Going with a friend to an adult makes help far easier to reach.","persona":"Counsellor","source":"help-routing"},
  {"id":"bn-058","cat":"support-friend","type":"role-play","hook":"You feel out of your depth supporting a friend who's really low.","setup":"Set a kind limit and route up. Say:","yourLine":[{"text":"\"I care about you, and this is bigger than just us, let's get a trusted adult.\"","best":true},{"text":"Carry it all alone and burn out"}],"relearn":"You can care for a friend and still bring in an adult; you're not their therapist.","persona":"any","source":"safeguarding / limits"},
  {"id":"bn-059","cat":"support-friend","type":"role-play","hook":"A friend says something that worries you about their safety.","setup":"Take it seriously, don't keep it secret. Say:","yourLine":[{"text":"\"I'm really glad you told me. Let's talk to someone who can help, right now.\"","best":true},{"text":"\"You're probably just being dramatic.\""}],"relearn":"Take any safety worry seriously and bring in a trusted adult at once.","persona":"Counsellor","source":"safeguarding / escalate"},
  {"id":"bn-060","cat":"support-friend","type":"branch","hook":"Your friend seems okay online but you sense something's really wrong.","options":[{"text":"Check in privately and honestly","consequence":"They feel seen and may finally open up.","outcome":"caring","best":true},{"text":"Assume the happy posts are the full story","consequence":"Posts can hide pain; a private check-in helps."}],"debrief":"Online cheerfulness can mask real struggle; check in for real.","relearn":"Don't take happy posts as proof; check in privately.","persona":"Riya","source":"peer support"},
  {"id":"bn-061","cat":"support-friend","type":"branch","hook":"A friend confides they've been having dark thoughts.","options":[{"text":"Stay calm, take it seriously, and get a trusted adult now","consequence":"You help keep your friend safe.","outcome":"protective","best":true},{"text":"Keep it secret to honour their trust","consequence":"This is a 'tell a trusted adult now' moment, for their safety."}],"debrief":"Dark thoughts are too big to hold alone; bring in a trusted adult immediately.","relearn":"If a friend has dark thoughts, get a trusted adult right away.","persona":"Counsellor","source":"safeguarding / crisis"},
  {"id":"bn-062","cat":"support-friend","type":"branch","hook":"You supported a friend through a hard time and now you feel drained.","options":[{"text":"Look after yourself too, and lean on your own support","consequence":"You refill so you can keep being there.","outcome":"balanced","best":true},{"text":"Ignore your own needs until you crash","consequence":"You matter too; supporters need support."}],"debrief":"Caring for others works only if you also care for yourself.","relearn":"Look after your own wellbeing while supporting a friend.","persona":"any","source":"supporter self-care"},
  {"id":"bn-063","cat":"support-friend","type":"sort","persona":"any","source":"peer support","hook":"Sort: helps a struggling friend, or hurts?","items":[{"id":"a","text":"Listening without judging"},{"id":"b","text":"\"Others have it worse than you\""},{"id":"c","text":"Offering to reach an adult with them"},{"id":"d","text":"Telling the whole class their business"},{"id":"e","text":"Sitting with them, no rush to fix"},{"id":"f","text":"Mocking them to lighten the mood"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"hurts","label":"Hurts","valence":"neg"}],"key":{"a":"helps","b":"hurts","c":"helps","d":"hurts","e":"helps","f":"hurts"},"relearn":"Listen, sit with them, and route to help; don't minimise, gossip, or mock."},
  {"id":"bn-064","cat":"support-friend","type":"sort","persona":"any","source":"what to say","hook":"Sort: a helpful thing to say, or one to avoid?","items":[{"id":"a","text":"\"I'm here for you\""},{"id":"b","text":"\"Just get over it\""},{"id":"c","text":"\"That sounds really tough\""},{"id":"d","text":"\"You're overreacting\""},{"id":"e","text":"\"Take your time, I'm not going anywhere\""},{"id":"f","text":"\"At least it's not worse\""}],"bins":[{"id":"say","label":"Helpful","valence":"pos"},{"id":"avoid","label":"Avoid","valence":"neg"}],"key":{"a":"say","b":"avoid","c":"say","d":"avoid","e":"say","f":"avoid"},"relearn":"Validate and stay present; skip 'get over it', 'overreacting', and 'at least'."},
  {"id":"bn-065","cat":"support-friend","type":"match","persona":"any","source":"peer support","hook":"Match the friend's need to your move.","pairs":[{"left":"They need to be heard","right":"Listen, don't fix"},{"left":"They're in danger","right":"Get a trusted adult now"},{"left":"They feel alone","right":"Keep showing up"},{"left":"They're scared to tell an adult","right":"Offer to go with them"},{"left":"They brush it off as nothing","right":"Gently say it matters"}],"relearn":"Match your support to what your friend actually needs."},
  {"id":"bn-066","cat":"support-friend","type":"match","persona":"any","source":"what to say","hook":"Match the brush-off to a kinder reply.","pairs":[{"left":"\"Cheer up\"","right":"\"I'm here, take your time\""},{"left":"\"It's nothing\"","right":"\"That matters, tell me more\""},{"left":"\"Just be positive\"","right":"\"It's okay to not be okay\""},{"left":"\"You're being dramatic\"","right":"\"I'm really glad you told me\""},{"left":"\"Stop overthinking\"","right":"\"Let's work it out together\""}],"relearn":"Swap brush-offs for presence and validation."},
  {"id":"bn-067","cat":"support-friend","type":"reflect","hook":"Lensy: being the one steady friend can change everything for someone. Worth being?","prompt":"What do you think?","options":["Yes","I want to be that","It matters"],"affirm":"One steady, caring friend is a real protective force in someone's life.","relearn":"Being one steady, caring friend genuinely protects people.","persona":"any","source":"supportive relationships (evidence)"},
  // — When to reach out —
  {"id":"bn-068","cat":"reach-out","type":"branch","hook":"Your own low feelings have lasted weeks and aren't lifting.","options":[{"text":"Tell a trusted adult or call Tele-MANAS (14416)","consequence":"You get real support instead of waiting it out alone.","outcome":"supported","best":true},{"text":"Keep waiting and hoping it passes","consequence":"Weeks of low mood deserve real support; reach out."}],"debrief":"Resilience has limits; lasting low feelings are a sign to get help.","relearn":"If low feelings last for weeks, tell an adult or call Tele-MANAS (14416).","persona":"Counsellor","source":"help-seeking / Tele-MANAS"},
  {"id":"bn-069","cat":"reach-out","type":"branch","hook":"You're having thoughts that scare you, or that you don't want to be here.","options":[{"text":"Tell a trusted adult right now, or call Tele-MANAS 14416 / Childline 1098","consequence":"You reach people trained to help.","outcome":"safe","best":true},{"text":"Keep it hidden","consequence":"These thoughts deserve immediate support; tell someone now."}],"debrief":"If thoughts ever scare you, reach a trusted adult or helpline right away.","relearn":"Scary or dark thoughts mean reach out now; you're not alone.","persona":"Counsellor","source":"crisis / help-seeking"},
  {"id":"bn-070","cat":"reach-out","type":"branch","hook":"You're not sure your problem is 'big enough' to ask for help.","options":[{"text":"Reach out anyway; help isn't only for emergencies","consequence":"You get support early, when it's easiest.","outcome":"supported","best":true},{"text":"Decide you should handle it alone","consequence":"You don't have to be in crisis to deserve support."}],"debrief":"You don't need to be at breaking point to deserve help.","relearn":"You can ask for help any time, not only in a crisis.","persona":"any","source":"help-seeking"},
  {"id":"bn-071","cat":"reach-out","type":"branch","hook":"You told an adult once and felt brushed off.","options":[{"text":"Tell another trusted adult, or try a helpline","consequence":"Someone will take it seriously; keep going.","outcome":"persistent","best":true},{"text":"Give up on getting help","consequence":"If one adult misses it, try another or a helpline."}],"debrief":"If one person doesn't hear you, there are others who will.","relearn":"If brushed off once, tell someone else or call a helpline.","persona":"any","source":"help-seeking / persistence"},
  {"id":"bn-072","cat":"reach-out","type":"role-play","hook":"You're ready to tell someone you're not coping.","setup":"Say it plainly. Say:","yourLine":[{"text":"\"I'm not coping right now, and I need some help.\"","best":true},{"text":"\"I'm fine\" (when you're not)"}],"relearn":"Saying 'I'm not coping, I need help' is brave and it works.","persona":"any","source":"help-seeking"},
  {"id":"bn-073","cat":"reach-out","type":"role-play","hook":"You want to call a helpline but feel nervous.","setup":"Remind yourself what it's for. Say:","yourLine":[{"text":"\"They're trained to listen and help, that's exactly what this is for.\"","best":true},{"text":"\"They'll think I'm being silly.\""}],"relearn":"Helplines like Tele-MANAS (14416) are there for exactly this; calling is okay.","persona":"any","source":"helpline / de-stigmatise"},
  {"id":"bn-074","cat":"reach-out","type":"role-play","hook":"A counsellor asks how you're really doing.","setup":"Be honest. Say:","yourLine":[{"text":"\"Honestly, I've been struggling more than I let on.\"","best":true},{"text":"\"All good\" (when it isn't)"}],"relearn":"Honesty with a counsellor lets them actually help you.","persona":"Counsellor","source":"help-seeking"},
  {"id":"bn-075","cat":"reach-out","type":"role-play","hook":"You're encouraging a friend to reach out for help.","setup":"Normalise it. Say:","yourLine":[{"text":"\"Getting help is smart, not weak, I'll help you find someone.\"","best":true},{"text":"\"Maybe just wait and see.\""}],"relearn":"You can normalise help-seeking and help a friend take the step.","persona":"any","source":"peer / help-routing"},
  {"id":"bn-076","cat":"reach-out","type":"strike-rewrite","hook":"\"Reaching out for mental health help means I'm weak or broken.\"","myth":{"un":"Asking for mental-health help means I'm weak or broken.","re":"Reaching out is one of the strongest, smartest things you can do.","why":"Everyone needs support sometimes; that's human."},"relearn":"Asking for mental-health help is strong, not weak.","persona":"Veer","source":"de-stigmatise"},
  {"id":"bn-077","cat":"reach-out","type":"strike-rewrite","hook":"\"If I just had more willpower, I wouldn't need help.\"","myth":{"un":"Enough willpower means I'd never need help.","re":"Some struggles need support and care, not just willpower.","why":"You can't willpower your way through everything alone."},"relearn":"Some things need support, not just willpower; that's okay.","persona":"any","source":"de-stigmatise"},
  {"id":"bn-078","cat":"reach-out","type":"reflect","hook":"Lensy: name one safe person and one helpline you could reach if things got heavy.","prompt":"Think of them.","options":["A parent + Tele-MANAS 14416","A counsellor + Childline 1098","An adult I trust + a helpline"],"affirm":"Knowing your people and numbers means help is always in reach.","relearn":"Knowing a safe person and a helpline means you're never stuck alone.","persona":"any","source":"safety planning"},
  {"id":"bn-079","cat":"reach-out","type":"reflect","hook":"Lensy: 'it's okay to not be okay' isn't giving up, it's being honest. Sit right with you?","prompt":"What do you think?","options":["Yes","It's honest","That helps"],"affirm":"Honesty about struggling is the first step to feeling better.","relearn":"It's okay to not be okay; saying so is honest and brave.","persona":"any","source":"normalising"},
  {"id":"bn-080","cat":"reach-out","type":"sort","hook":"Sort: a 'reach out now' sign, or an ordinary rough patch?","items":[{"id":"a","text":"Dark thoughts or not wanting to be here"},{"id":"b","text":"A bad day that passes"},{"id":"c","text":"Weeks of not eating or sleeping"},{"id":"d","text":"Feeling nervous before a test"},{"id":"e","text":"No joy in anything for over a month"},{"id":"f","text":"Sad after a fight, okay by morning"}],"bins":[{"id":"now","label":"Reach out now","valence":"tell"},{"id":"ordinary","label":"Ordinary rough patch","valence":"neutral"}],"key":{"a":"now","b":"ordinary","c":"now","d":"ordinary","e":"now","f":"ordinary"},"relearn":"Dark thoughts or weeks of not eating/sleeping mean reach out now.","persona":"Counsellor","source":"safeguarding"},
  {"id":"bn-081","cat":"reach-out","type":"sort","hook":"Sort: who or what can help when it's heavy?","items":[{"id":"a","text":"A trusted adult"},{"id":"b","text":"Tele-MANAS (14416)"},{"id":"c","text":"A 'just toughen up' message"},{"id":"d","text":"Childline (1098 / 112)"},{"id":"e","text":"A school counsellor"},{"id":"f","text":"Bottling it up alone"}],"bins":[{"id":"helps","label":"Real help","valence":"pos"},{"id":"no","label":"Not help","valence":"neg"}],"key":{"a":"helps","b":"helps","c":"no","d":"helps","e":"helps","f":"no"},"relearn":"Trusted adults and helplines (Tele-MANAS 14416, Childline 1098) are real help.","persona":"any","source":"help routes (India)"},
  {"id":"bn-082","cat":"reach-out","type":"reflect","hook":"Lensy: hard times pass, and asking for help speeds that up. Hold onto that?","prompt":"What do you think?","options":["Yes","Help speeds it up","I'll remember"],"affirm":"Reaching out doesn't just feel better, it helps things get better faster.","relearn":"Hard times pass, and reaching out helps them pass sooner.","persona":"any","source":"hope / help-seeking"},
  {"id":"bn-083","cat":"reach-out","type":"strike-rewrite","hook":"\"Talking to a helpline or counsellor won't actually change anything.\"","myth":{"un":"Talking to a counsellor or helpline won't change anything.","re":"Trained support genuinely helps, with the feeling and the next steps.","why":"That's literally what they're trained and there to do."},"relearn":"Trained support really does help; it's worth reaching out.","persona":"any","source":"help efficacy"},
  {"id":"bn-084","cat":"reach-out","type":"reflect","hook":"Lensy: biggest take-away from Bounce?","prompt":"Pick your motto.","options":["Feel it, then move through it","Setbacks aren't the end","Lean on people","It's okay to ask for help"],"affirm":"That's resilience, real, honest, and never something you do alone.","relearn":"Bounce back by feeling it, reframing, leaning on people, and asking for help.","persona":"any","source":"consolidation"},
  {"id":"bn-900","type":"build","hook":"Build a reset plan after a bad unit test.","prompt":"Build a reset plan after a bad unit test.","pieces":["let the disappointment land","name what tripped you up","pick one topic to redo","ask a friend or teacher about it"],"mode":"sequence","key":["let the disappointment land","name what tripped you up","pick one topic to redo","ask a friend or teacher about it"],"relearn":"After a bad test: feel it, spot the gap, redo one topic, ask for help.","persona":"Riya","source":"study recovery","cat":"bounce-toolkit"},
  {"id":"bn-901","type":"build","hook":"Build a grounding kit for when panic spikes.","prompt":"Build a grounding kit for when panic spikes.","pieces":["name five things you can see","feel your feet on the floor","slow your out-breath","sip some water"],"mode":"assemble","key":["name five things you can see","feel your feet on the floor","slow your out-breath","sip some water"],"relearn":"Grounding pulls you back to now: see, feel, breathe, sip.","persona":"any","source":"grounding / 5 senses","cat":"bounce-toolkit"},
  {"id":"bn-902","type":"build","hook":"Build a steady-start kit for a heavy exam morning.","prompt":"Build a steady-start kit for a heavy exam morning.","pieces":["a proper breakfast","a few slow breaths","one kind line to yourself","a short walk to school"],"mode":"assemble","key":["a proper breakfast","a few slow breaths","one kind line to yourself","a short walk to school"],"relearn":"A steady start kit: food, breath, a kind word, a little movement.","persona":"Riya","source":"routine / regulation","cat":"bounce-toolkit"},
  {"id":"bn-903","type":"build","hook":"Build a comeback plan after losing the trials.","prompt":"Build a comeback plan after losing the trials.","pieces":["let yourself be gutted for a bit","write down what to practise","train one weak skill this week","try again next round"],"mode":"sequence","key":["let yourself be gutted for a bit","write down what to practise","train one weak skill this week","try again next round"],"relearn":"After a loss: grieve it, note the lesson, train one thing, try again.","persona":"Veer","source":"setback recovery","cat":"bounce-toolkit"},
  {"id":"bn-904","type":"build","hook":"Build your 'people I can lean on' kit.","prompt":"Build your 'people I can lean on' kit.","pieces":["a friend who listens","a cousin who gets it","a teacher you trust","a helpline for the hard nights"],"mode":"assemble","key":["a friend who listens","a cousin who gets it","a teacher you trust","a helpline for the hard nights"],"relearn":"Your support kit is a circle of people, not one person carrying it all.","persona":"any","source":"support network","cat":"bounce-toolkit"},
  {"id":"bn-905","type":"build","hook":"Build a plan for a mean comment that stung online.","prompt":"Build a plan for a mean comment that stung online.","pieces":["close the app for now","tell someone how it felt","remember one true thing about you","decide if it even deserves a reply"],"mode":"sequence","key":["close the app for now","tell someone how it felt","remember one true thing about you","decide if it even deserves a reply"],"relearn":"Stung online? Step away, talk it out, hold a truth, then choose.","persona":"Veer","source":"online resilience","cat":"bounce-toolkit"},
  {"id":"bn-906","type":"build","hook":"Build a self-compassion break for a rough moment.","prompt":"Build a self-compassion break for a rough moment.","pieces":["this hurts right now","other people feel this too","may I be kind to myself","I'm doing my best"],"mode":"assemble","key":["this hurts right now","other people feel this too","may I be kind to myself","I'm doing my best"],"relearn":"A self-compassion break: this is hard, I'm not alone, be kind to me.","persona":"any","source":"self-compassion (Neff)","cat":"bounce-toolkit"},
  {"id":"bn-907","type":"build","hook":"Build a plan to unstick when homework feels impossible.","prompt":"Build a plan to unstick when homework feels impossible.","pieces":["set a ten-minute timer","do only the easiest part","take a short stretch break","decide the next tiny step"],"mode":"sequence","key":["set a ten-minute timer","do only the easiest part","take a short stretch break","decide the next tiny step"],"relearn":"Unstick by shrinking it: ten minutes, easiest bit, break, next step.","persona":"any","source":"task initiation","cat":"bounce-toolkit"},
  {"id":"bn-908","type":"build","hook":"Build a wind-down kit for a mind that won't switch off.","prompt":"Build a wind-down kit for a mind that won't switch off.","pieces":["write tomorrow's worries on paper","dim the screens early","breathe out slowly in bed","let the day be over"],"mode":"assemble","key":["write tomorrow's worries on paper","dim the screens early","breathe out slowly in bed","let the day be over"],"relearn":"Wind down by parking worries on paper and letting the day end.","persona":"Riya","source":"sleep hygiene","cat":"bounce-toolkit"},
  {"id":"bn-909","type":"build","hook":"Build a plan after you let a friend down.","prompt":"Build a plan after you let a friend down.","pieces":["own your part honestly","say a real sorry","ask how to make it right","give it a little time"],"mode":"sequence","key":["own your part honestly","say a real sorry","ask how to make it right","give it a little time"],"relearn":"Repair a slip: own it, say sorry, ask how to mend it, allow time.","persona":"any","source":"repair / accountability","cat":"bounce-toolkit"},
  {"id":"bn-910","type":"build","hook":"Build a feelings first-aid kit for a sudden flop.","prompt":"Build a feelings first-aid kit for a sudden flop.","pieces":["pause and breathe","name what you feel","do one comforting thing","reach one person"],"mode":"assemble","key":["pause and breathe","name what you feel","do one comforting thing","reach one person"],"relearn":"First aid for a flop: pause, name it, comfort yourself, reach out.","persona":"any","source":"emotional first aid","cat":"bounce-toolkit"},
  {"id":"bn-911","type":"build","hook":"Build a plan for a results day you're dreading.","prompt":"Build a plan for a results day you're dreading.","pieces":["plan who you'll be with","decide one calming thing to do after","remind yourself marks aren't your worth","line up someone to talk to"],"mode":"sequence","key":["plan who you'll be with","decide one calming thing to do after","remind yourself marks aren't your worth","line up someone to talk to"],"relearn":"Brace for results day with people, a calming plan, and perspective.","persona":"Riya","source":"exam coping","cat":"bounce-toolkit"},
  {"id":"bn-912","type":"build","hook":"Build a 'move the stress out' menu.","prompt":"Build a 'move the stress out' menu.","pieces":["a brisk walk","dancing to one song","skipping or running","stretching it out"],"mode":"assemble","key":["a brisk walk","dancing to one song","skipping or running","stretching it out"],"relearn":"Movement burns off stress chemicals; pick whatever gets you moving.","persona":"any","source":"exercise / regulation","cat":"bounce-toolkit"},
  {"id":"bn-913","type":"build","hook":"Build a plan after you froze giving a class talk.","prompt":"Build a plan after you froze giving a class talk.","pieces":["remind yourself it'll fade fast","name one thing you did okay","practise the tricky bit later","let yourself try again"],"mode":"sequence","key":["remind yourself it'll fade fast","name one thing you did okay","practise the tricky bit later","let yourself try again"],"relearn":"After a public stumble: it fades, find a win, practise, try again.","persona":"any","source":"spotlight recovery","cat":"bounce-toolkit"},
  {"id":"bn-914","type":"build","hook":"Build a comfort kit you can reach for on a low day.","prompt":"Build a comfort kit you can reach for on a low day.","pieces":["a song that lifts you","a photo that makes you smile","a person to message","a warm drink"],"mode":"assemble","key":["a song that lifts you","a photo that makes you smile","a person to message","a warm drink"],"relearn":"A comfort kit holds small things that genuinely soothe you.","persona":"any","source":"self-soothing","cat":"bounce-toolkit"},
  {"id":"bn-915","type":"build","hook":"Build a plan when you feel flat but don't know why.","prompt":"Build a plan when you feel flat but don't know why.","pieces":["notice the flat feeling","check sleep, food and screens","do one small kind thing","tell someone if it lingers"],"mode":"sequence","key":["notice the flat feeling","check sleep, food and screens","do one small kind thing","tell someone if it lingers"],"relearn":"Flat for no reason? Notice it, check basics, act small, tell someone.","persona":"any","source":"mood check / basics","cat":"bounce-toolkit"},
  {"id":"bn-916","type":"build","hook":"Build a relief kit for the night before boards.","prompt":"Build a relief kit for the night before boards.","pieces":["pack your bag tonight","a calming playlist","an early, screen-free sleep","trust the work you've done"],"mode":"assemble","key":["pack your bag tonight","a calming playlist","an early, screen-free sleep","trust the work you've done"],"relearn":"Night-before kit: prep, calm, real sleep, and trust in your effort.","persona":"Riya","source":"exam-eve routine","cat":"bounce-toolkit"},
  {"id":"bn-917","type":"build","hook":"Build a plan to ask a teacher for help you've been avoiding.","prompt":"Build a plan to ask a teacher for help you've been avoiding.","pieces":["write down exactly what's stuck","pick a calm moment after class","ask one clear question","thank them and note the answer"],"mode":"sequence","key":["write down exactly what's stuck","pick a calm moment after class","ask one clear question","thank them and note the answer"],"relearn":"Asking for help works best when it's specific, calm and clear.","persona":"Veer","source":"help-seeking","cat":"bounce-toolkit"},
  {"id":"bn-918","type":"build","hook":"Build an anchor-thoughts kit for when your mind spirals.","prompt":"Build an anchor-thoughts kit for when your mind spirals.","pieces":["this feeling will pass","I've got through hard things before","I don't have to fix it all today","one step is enough"],"mode":"assemble","key":["this feeling will pass","I've got through hard things before","I don't have to fix it all today","one step is enough"],"relearn":"Anchor thoughts steady a spiral: it passes, I've coped, one step.","persona":"any","source":"cognitive anchoring","cat":"bounce-toolkit"},
  {"id":"bn-919","type":"build","hook":"Build a plan after a fight with your best friend.","prompt":"Build a plan after a fight with your best friend.","pieces":["cool down before texting","figure out your real feeling","share it without blaming","listen to their side too"],"mode":"sequence","key":["cool down before texting","figure out your real feeling","share it without blaming","listen to their side too"],"relearn":"After a fight: cool down, find your feeling, speak it, then listen.","persona":"any","source":"conflict recovery","cat":"bounce-toolkit"},
  {"id":"bn-920","type":"build","hook":"Build a tiny-wins kit to rebuild momentum.","prompt":"Build a tiny-wins kit to rebuild momentum.","pieces":["finish one small task","tick it off where you can see","notice you did it","stack the next small one"],"mode":"assemble","key":["finish one small task","tick it off where you can see","notice you did it","stack the next small one"],"relearn":"Tiny wins, seen and stacked, rebuild momentum after a slump.","persona":"any","source":"behavioural activation","cat":"bounce-toolkit"},
  {"id":"bn-921","type":"build","hook":"Build a plan to catch and turn harsh self-talk.","prompt":"Build a plan to catch and turn harsh self-talk.","pieces":["catch the mean thought","ask if you'd say it to a friend","swap it for a fairer line","carry on gentler"],"mode":"sequence","key":["catch the mean thought","ask if you'd say it to a friend","swap it for a fairer line","carry on gentler"],"relearn":"Turn harsh self-talk by checking it and choosing a fairer line.","persona":"any","source":"cognitive reframing","cat":"bounce-toolkit"},
  {"id":"bn-922","type":"build","hook":"Build a steadiness kit for a long stretch of pressure.","prompt":"Build a steadiness kit for a long stretch of pressure.","pieces":["small breaks that you keep","one person who checks in","sleep you protect","one fun thing each week"],"mode":"assemble","key":["small breaks that you keep","one person who checks in","sleep you protect","one fun thing each week"],"relearn":"Surviving a long stretch needs breaks, people, sleep and a little joy.","persona":"Veer","source":"sustained coping","cat":"bounce-toolkit"},
  {"id":"bn-923","type":"branch","hook":"After a flop, you keep replaying it on loop at 2am.","options":[{"text":"Write the worry down and plan to look at it tomorrow","consequence":"The page holds it so your mind can rest.","outcome":"parked","best":true},{"text":"Lie there replaying it for hours","consequence":"Replaying alone at night grows it; park it on paper instead."}],"debrief":"The page holds it so your mind can rest.","relearn":"The page holds it so your mind can rest.","persona":"Riya","source":"rumination","cat":"bounce-toolkit"},
  {"id":"bn-924","type":"branch","hook":"You bombed a presentation and want to skip school tomorrow.","options":[{"text":"Go in, tell one friend it was rough, and let it fade","consequence":"Facing it shrinks the dread; people forget fast.","outcome":"faced","best":true},{"text":"Stay home to dodge the embarrassment","consequence":"Hiding makes it loom larger; the stumble fades faster than you fear."}],"debrief":"Facing it shrinks the dread; people forget fast.","relearn":"Facing it shrinks the dread; people forget fast.","persona":"Veer","source":"avoidance","cat":"bounce-toolkit"},
  {"id":"bn-925","type":"branch","hook":"Stress is so loud you can't even start studying.","options":[{"text":"Step away, breathe for two minutes, then open one chapter","consequence":"A calmer body can actually begin.","outcome":"reset","best":true},{"text":"Force yourself to grind through the panic","consequence":"A panicked mind can't learn; settle the body first, then start."}],"debrief":"A calmer body can actually begin.","relearn":"A calmer body can actually begin.","persona":"any","source":"regulate-first","cat":"bounce-toolkit"},
  {"id":"bn-926","type":"branch","hook":"You slipped back to old habits after a good streak.","options":[{"text":"Treat it as one slip, not a failure, and restart today","consequence":"One slip doesn't erase the streak; you just begin again.","outcome":"restarted","best":true},{"text":"Decide the whole effort was pointless","consequence":"A single slip isn't a collapse; restarting is the real skill."}],"debrief":"One slip doesn't erase the streak; you just begin again.","relearn":"One slip doesn't erase the streak; you just begin again.","persona":"any","source":"relapse-reframe","cat":"bounce-toolkit"},
  {"id":"bn-927","type":"branch","hook":"A friend's grades shot past yours and it stings.","options":[{"text":"Notice the sting, then refocus on your own next step","consequence":"Your race is yours; their win isn't your loss.","outcome":"refocused","best":true},{"text":"Spiral into 'I'll never be good enough'","consequence":"Comparison steals your steam; your only fair race is with yourself."}],"debrief":"Your race is yours; their win isn't your loss.","relearn":"Your race is yours; their win isn't your loss.","persona":"Riya","source":"comparison","cat":"bounce-toolkit"},
  {"id":"bn-928","type":"branch","hook":"You're exhausted but feel guilty taking any rest.","options":[{"text":"Take the rest; remind yourself recovery is part of the work","consequence":"Rested, you come back sharper.","outcome":"rested","best":true},{"text":"Push through on empty to prove you're tough","consequence":"Running on empty isn't strength; rest is how resilience refuels."}],"debrief":"Rested, you come back sharper.","relearn":"Rested, you come back sharper.","persona":"Veer","source":"rest-guilt","cat":"bounce-toolkit"},
  {"id":"bn-929","type":"branch","hook":"One small mistake makes you want to scrap the whole project.","options":[{"text":"Fix the one part and keep the rest you built","consequence":"One flaw doesn't ruin the whole thing.","outcome":"kept","best":true},{"text":"Bin the entire project","consequence":"Trashing it all over one error wastes everything good you made."}],"debrief":"One flaw doesn't ruin the whole thing.","relearn":"One flaw doesn't ruin the whole thing.","persona":"any","source":"all-or-nothing","cat":"bounce-toolkit"},
  {"id":"bn-930","type":"branch","hook":"You feel low and your first urge is to numb it with your phone.","options":[{"text":"Let yourself feel it for a bit, then do one real comfort","consequence":"Feeling it and then comforting actually helps it pass.","outcome":"processed","best":true},{"text":"Scroll for three hours to not feel it","consequence":"Numbing just delays the feeling; it's still there when you stop."}],"debrief":"Feeling it and then comforting actually helps it pass.","relearn":"Feeling it and then comforting actually helps it pass.","persona":"any","source":"numbing-vs-coping","cat":"bounce-toolkit"},
  {"id":"bn-931","type":"branch","hook":"You're stuck and too proud to ask for help.","options":[{"text":"Ask one person a clear question about what's stuck","consequence":"Asking gets you unstuck and isn't weakness.","outcome":"unstuck","best":true},{"text":"Struggle alone so nobody sees you fail","consequence":"Going it alone here just keeps you stuck; asking is a strength."}],"debrief":"Asking gets you unstuck and isn't weakness.","relearn":"Asking gets you unstuck and isn't weakness.","persona":"Veer","source":"help-seeking","cat":"bounce-toolkit"},
  {"id":"bn-932","type":"branch","hook":"A setback has you snapping at everyone at home.","options":[{"text":"Name that you're stressed and take a short cool-off","consequence":"Naming it stops it landing on people you love.","outcome":"named","best":true},{"text":"Keep snapping and bottling the real reason","consequence":"The stress isn't really at them; name it and cool off first."}],"debrief":"Naming it stops it landing on people you love.","relearn":"Naming it stops it landing on people you love.","persona":"any","source":"displaced-stress","cat":"bounce-toolkit"},
  {"id":"bn-933","type":"branch","hook":"You want a comeback but the goal feels huge and frozen.","options":[{"text":"Break it down and do just the first tiny piece today","consequence":"One tiny piece breaks the freeze and builds momentum.","outcome":"started","best":true},{"text":"Wait until you feel motivated enough","consequence":"Motivation usually follows action; start tiny instead of waiting."}],"debrief":"One tiny piece breaks the freeze and builds momentum.","relearn":"One tiny piece breaks the freeze and builds momentum.","persona":"any","source":"shrink-the-goal","cat":"bounce-toolkit"},
  {"id":"bn-934","type":"branch","hook":"After a hard week you've dropped everything that helps you.","options":[{"text":"Restart one basic: a walk, real sleep, or one good meal","consequence":"One restored basic steadies the rest.","outcome":"steadied","best":true},{"text":"Keep skipping sleep, food and fresh air","consequence":"Dropping the basics deepens the dip; restore one to steady yourself."}],"debrief":"One restored basic steadies the rest.","relearn":"One restored basic steadies the rest.","persona":"any","source":"basics","cat":"bounce-toolkit"},
  {"id":"bn-935","type":"branch","hook":"You messed up and your brain says 'everyone saw, it's ruined'.","options":[{"text":"Remind yourself people are busy with their own day","consequence":"Most barely noticed; the spotlight is mostly in your head.","outcome":"eased","best":true},{"text":"Assume everyone is judging you all day","consequence":"People are too wrapped up in themselves to dwell on your slip."}],"debrief":"Most barely noticed; the spotlight is mostly in your head.","relearn":"Most barely noticed; the spotlight is mostly in your head.","persona":"Riya","source":"spotlight","cat":"bounce-toolkit"},
  {"id":"bn-936","type":"branch","hook":"You're carrying a setback and someone asks 'you okay?'","options":[{"text":"Be honest: 'Not really, it's been a rough one'","consequence":"Honesty lets them actually support you.","outcome":"supported","best":true},{"text":"Say 'I'm fine' and change the subject","consequence":"Brushing it off shuts the door on help you could use right now."}],"debrief":"Honesty lets them actually support you.","relearn":"Honesty lets them actually support you.","persona":"Veer","source":"opening-up","cat":"bounce-toolkit"},
  {"id":"bn-937","type":"sort","hook":"Sort: does it build you up, or beat you down, after a slip?","items":[{"id":"a","text":"\"I'll try a different way\""},{"id":"b","text":"\"I'm such a failure\""},{"id":"c","text":"\"This is one bad day\""},{"id":"d","text":"\"Everyone hates me now\""},{"id":"e","text":"\"I can ask for help\""},{"id":"f","text":"\"I'll never get this\""}],"bins":[{"id":"kind","label":"Builds you up","valence":"pos"},{"id":"harsh","label":"Beats you down","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"Kind, fair self-talk rebuilds you; harsh self-talk just digs the hole.","persona":"any","source":"self-talk","cat":"bounce-toolkit"},
  {"id":"bn-938","type":"sort","hook":"Sort: a tool that helps now, or one for later calm?","items":[{"id":"a","text":"Slow breathing"},{"id":"b","text":"A long-term sleep routine"},{"id":"c","text":"Grounding your senses"},{"id":"d","text":"Building a support circle"},{"id":"e","text":"A two-minute walk"},{"id":"f","text":"A weekly fun ritual"}],"bins":[{"id":"now","label":"Calm right now","valence":"pos"},{"id":"later","label":"Steadies over time","valence":"neutral"}],"key":{"a":"now","b":"later","c":"now","d":"later","e":"now","f":"later"},"relearn":"Some tools calm you in the moment; others build steadiness over weeks.","persona":"any","source":"toolkit-timing","cat":"bounce-toolkit"},
  {"id":"bn-939","type":"sort","hook":"Sort: real self-care, or just avoiding the feeling?","items":[{"id":"a","text":"Resting because you're tired"},{"id":"b","text":"Skipping everything for a week"},{"id":"c","text":"Talking to a friend"},{"id":"d","text":"Gaming all night to forget"},{"id":"e","text":"A planned break"},{"id":"f","text":"Ghosting everyone who cares"}],"bins":[{"id":"care","label":"Real self-care","valence":"pos"},{"id":"avoid","label":"Avoiding it","valence":"neg"}],"key":{"a":"care","b":"avoid","c":"care","d":"avoid","e":"care","f":"avoid"},"relearn":"Real self-care restores you; avoidance just hides from the feeling.","persona":"Veer","source":"self-care-vs-avoid","cat":"bounce-toolkit"},
  {"id":"bn-940","type":"sort","hook":"Sort: helps you bounce back, or makes it heavier?","items":[{"id":"a","text":"Naming the feeling"},{"id":"b","text":"Pretending you're fine"},{"id":"c","text":"One small next step"},{"id":"d","text":"Comparing to everyone"},{"id":"e","text":"Reaching out"},{"id":"f","text":"Replaying it on loop"}],"bins":[{"id":"helps","label":"Helps you bounce","valence":"pos"},{"id":"heavy","label":"Makes it heavier","valence":"neg"}],"key":{"a":"helps","b":"heavy","c":"helps","d":"heavy","e":"helps","f":"heavy"},"relearn":"Naming, stepping and reaching out lighten a setback; the rest pile it on.","persona":"any","source":"helps-vs-heavier","cat":"bounce-toolkit"},
  {"id":"bn-941","type":"sort","hook":"Sort: which goes in your calm-the-storm kit?","items":[{"id":"a","text":"Slow out-breaths"},{"id":"b","text":"Three more energy drinks"},{"id":"c","text":"A short walk"},{"id":"d","text":"Snapping at people"},{"id":"e","text":"Writing it down"},{"id":"f","text":"Holding it all in"}],"bins":[{"id":"kit","label":"Goes in the kit","valence":"pos"},{"id":"not","label":"Leave it out","valence":"neg"}],"key":{"a":"kit","b":"not","c":"kit","d":"not","e":"kit","f":"not"},"relearn":"Breath, movement and writing belong in your kit; the rest just add heat.","persona":"any","source":"regulation-kit","cat":"bounce-toolkit"},
  {"id":"bn-942","type":"sort","hook":"Sort: a fair expectation, or pressure you can drop?","items":[{"id":"a","text":"\"I can improve with practice\""},{"id":"b","text":"\"I must top every test\""},{"id":"c","text":"\"Doing my best is enough\""},{"id":"d","text":"\"I can never make a mistake\""},{"id":"e","text":"\"Rest helps me do well\""},{"id":"f","text":"\"I must please everyone\""}],"bins":[{"id":"fair","label":"Fair to keep","valence":"pos"},{"id":"drop","label":"Pressure to drop","valence":"uhoh"}],"key":{"a":"fair","b":"drop","c":"fair","d":"drop","e":"fair","f":"drop"},"relearn":"Keep fair expectations; drop the impossible ones that just crush you.","persona":"Riya","source":"expectations","cat":"bounce-toolkit"},
  {"id":"bn-943","type":"sort","hook":"Sort: speak it out, or let it sit and grow?","items":[{"id":"a","text":"Tell a friend you're low"},{"id":"b","text":"Hide it behind 'I'm fine'"},{"id":"c","text":"Ask a teacher for help"},{"id":"d","text":"Bottle it till you snap"},{"id":"e","text":"Message someone who cares"},{"id":"f","text":"Carry it all alone"}],"bins":[{"id":"speak","label":"Speak it out","valence":"tell"},{"id":"sit","label":"Let it sit","valence":"neg"}],"key":{"a":"speak","b":"sit","c":"speak","d":"sit","e":"speak","f":"sit"},"relearn":"Speaking it out shares the weight; sitting on it only lets it grow.","persona":"Veer","source":"speak-vs-sit","cat":"bounce-toolkit"},
  {"id":"bn-944","type":"reflect","hook":"Lensy: think of a time you got through something hard. What helped?","prompt":"What helped you?","options":["A person","A small step","Time","Just not giving up"],"affirm":"You've already got through hard things; that strength is still yours.","relearn":"You've already got through hard things; that strength is still yours.","persona":"any","source":"past-resilience recall","cat":"bounce-toolkit"},
  {"id":"bn-945","type":"reflect","hook":"Lensy: which comfort thing actually works for you on a low day?","prompt":"Pick your comfort.","options":["Music","A walk","Talking to someone","A nap"],"affirm":"Knowing what truly comforts you means you can reach for it sooner.","relearn":"Knowing what truly comforts you means you can reach for it sooner.","persona":"any","source":"self-soothing","cat":"bounce-toolkit"},
  {"id":"bn-946","type":"reflect","hook":"Lensy: who is one person you could message on a rough night?","prompt":"Who comes to mind?","options":["A friend","A cousin","A teacher","A helpline"],"affirm":"Having a person in mind before you need them makes reaching out easier.","relearn":"Having a person in mind before you need them makes reaching out easier.","persona":"any","source":"support readiness","cat":"bounce-toolkit"},
  {"id":"bn-947","type":"reflect","hook":"Lensy: when stress hits, which body-calmer fits you best?","prompt":"Pick yours.","options":["Slow breathing","Moving around","Writing it out","Stepping outside"],"affirm":"Your go-to body-calmer is a real tool you can use any time stress spikes.","relearn":"Your go-to body-calmer is a real tool you can use any time stress spikes.","persona":"any","source":"regulation choice","cat":"bounce-toolkit"},
  {"id":"bn-948","type":"reflect","hook":"Lensy: what's one kind thing you could say to yourself after a flop?","prompt":"Choose a line.","options":["\"This is hard\"","\"I'm still learning\"","\"I did my best\"","\"It's okay\""],"affirm":"Speaking to yourself like a friend is a tool, not softness.","relearn":"Speaking to yourself like a friend is a tool, not softness.","persona":"any","source":"self-compassion","cat":"bounce-toolkit"},
  {"id":"bn-949","type":"reflect","hook":"Lensy: a setback doesn't decide your whole future. Sit with that?","prompt":"What do you feel?","options":["I believe it","I'm trying to","One day at a time","There are many paths"],"affirm":"One result is one moment; many paths forward stay open to you.","relearn":"One result is one moment; many paths forward stay open to you.","persona":"Riya","source":"perspective","cat":"bounce-toolkit"},
  {"id":"bn-950","type":"reflect","hook":"Lensy: which tiny first step could you take on a stuck day?","prompt":"Pick a tiny start.","options":["Open the book","Send one text","Tidy one thing","Drink some water"],"affirm":"A tiny first step beats waiting to feel ready; it gets you moving.","relearn":"A tiny first step beats waiting to feel ready; it gets you moving.","persona":"any","source":"task initiation","cat":"bounce-toolkit"},
  {"id":"bn-951","type":"reflect","hook":"Lensy: what helps your mind settle before sleep?","prompt":"Pick a wind-down.","options":["Screens off early","Worries on paper","Slow breathing","A calm song"],"affirm":"A wind-down you trust helps a racing mind let the day finally end.","relearn":"A wind-down you trust helps a racing mind let the day finally end.","persona":"Riya","source":"sleep wind-down","cat":"bounce-toolkit"},
  {"id":"bn-952","type":"reflect","hook":"Lensy: needing help with this isn't weakness. Can you let that in?","prompt":"How does that sit?","options":["Yes","I want to","I'm working on it","Help is strength"],"affirm":"Reaching out is one of the strongest, bravest moves you can make.","relearn":"Reaching out is one of the strongest, bravest moves you can make.","persona":"Veer","source":"help-seeking","cat":"bounce-toolkit"},
  {"id":"bn-953","type":"match","hook":"Match the bounce-back tool to what it gives you.","pairs":[{"left":"Slow breathing","right":"A calmer body"},{"left":"Talking it out","right":"Shared weight"},{"left":"One small step","right":"Momentum back"},{"left":"Zooming out","right":"A wider view"},{"left":"Self-compassion","right":"A kinder voice"}],"relearn":"Each tool does a real job: calm, connection, momentum, view, kindness.","persona":"any","source":"toolkit map","cat":"bounce-toolkit"},
  {"id":"bn-954","type":"match","hook":"Match the setback to a first small step that helps.","pairs":[{"left":"Bad test result","right":"Redo one topic"},{"left":"Fight with a friend","right":"Cool down first"},{"left":"Big goal feels huge","right":"Do the first tiny part"},{"left":"Can't sleep","right":"Park worries on paper"},{"left":"Feeling low for days","right":"Tell a trusted adult"}],"relearn":"Every setback has a doable first step that gets you moving again.","persona":"Riya","source":"first steps","cat":"bounce-toolkit"},
  {"id":"bn-955","type":"match","hook":"Match the harsh thought to a fairer reply.","pairs":[{"left":"\"I'm a total failure\"","right":"\"I had one bad day\""},{"left":"\"I can't do this\"","right":"\"I can't do this yet\""},{"left":"\"Everyone saw\"","right":"\"It'll fade fast\""},{"left":"\"I should cope alone\"","right":"\"Asking for help is strength\""},{"left":"\"I must be perfect\"","right":"\"My best is enough\""}],"relearn":"Each harsh thought has a fairer, truer reply you can practise.","persona":"any","source":"reframing","cat":"bounce-toolkit"},
  {"id":"bn-956","type":"match","hook":"Match the stress signal to a calming move.","pairs":[{"left":"Racing heart","right":"Slow your out-breath"},{"left":"Restless legs","right":"Go for a short walk"},{"left":"Spinning thoughts","right":"Write them down"},{"left":"Tight chest","right":"Sip some water slowly"},{"left":"Feeling alone","right":"Message someone you trust"}],"relearn":"Notice the signal, then pick the move that settles that exact thing.","persona":"any","source":"regulation","cat":"bounce-toolkit"},
  {"id":"bn-957","type":"match","hook":"Match the resilience basic to why it matters.","pairs":[{"left":"Sleep","right":"Refuels your brain"},{"left":"Movement","right":"Burns off stress"},{"left":"A caring person","right":"Reminds you you're not alone"},{"left":"Real food","right":"Steadies your mood"},{"left":"A small break","right":"Stops the burnout"}],"relearn":"The basics aren't extras; each one quietly powers your bounce-back.","persona":"Veer","source":"resilience basics","cat":"bounce-toolkit"},
  {"id":"bn-958","type":"match","hook":"Match the avoidant habit to the real tool it's hiding from.","pairs":[{"left":"Doomscrolling","right":"Naming the feeling"},{"left":"\"I'm fine\"","right":"Telling someone the truth"},{"left":"Grinding on empty","right":"Taking real rest"},{"left":"Snapping at people","right":"A short cool-off"},{"left":"Replaying it all night","right":"Parking it on paper"}],"relearn":"Each numbing habit has a real tool underneath that actually helps.","persona":"any","source":"swap-the-habit","cat":"bounce-toolkit"},
  {"id":"bn-959","type":"match","hook":"Match the moment to the kit you'd reach for.","pairs":[{"left":"Panic before an exam","right":"A grounding kit"},{"left":"A racing mind at night","right":"A wind-down kit"},{"left":"A sudden flop","right":"A first-aid kit"},{"left":"A low, flat day","right":"A comfort kit"},{"left":"A long pressured stretch","right":"A steadiness kit"}],"relearn":"Different moments call for different kits; build the ones you need.","persona":"any","source":"kit timing","cat":"bounce-toolkit"},
  {"id":"bn-960","type":"match","hook":"Match the self-compassion step to its line.","pairs":[{"left":"Notice it hurts","right":"\"This is really hard\""},{"left":"Remember you're human","right":"\"Others feel this too\""},{"left":"Offer yourself kindness","right":"\"May I be gentle with me\""},{"left":"Hold your effort","right":"\"I'm doing my best\""},{"left":"Allow the feeling","right":"\"It's okay to find this tough\""}],"relearn":"Self-compassion is a few honest, kind lines you can say to yourself.","persona":"any","source":"self-compassion","cat":"bounce-toolkit"},
  {"id":"bn-961","type":"strike-rewrite","hook":"\"Coping tools are just soft stuff that doesn't really work.\"","myth":{"un":"Coping tools are soft stuff that doesn't really work.","re":"Breath, movement and reaching out are proven ways to settle stress.","why":"They calm the body and clear the mind so you can actually cope."},"relearn":"Breath, movement and reaching out are proven ways to settle stress.","persona":"Veer","source":"tools-work","cat":"bounce-toolkit"},
  {"id":"bn-962","type":"strike-rewrite","hook":"\"If you need a coping kit, you're weak.\"","myth":{"un":"Needing a coping kit means you're weak.","re":"Having tools ready is a skill strong, steady people build on purpose.","why":"Nobody white-knuckles forever; planned tools are how you last."},"relearn":"Having tools ready is a skill strong, steady people build on purpose.","persona":"Veer","source":"kit-not-weak","cat":"bounce-toolkit"},
  {"id":"bn-963","type":"strike-rewrite","hook":"\"You should be able to fix a bad mood instantly.\"","myth":{"un":"You should be able to fix a bad mood instantly.","re":"Moods shift slowly; tools help it pass, they don't flick a switch.","why":"Feelings move at their own pace; rushing them just adds frustration."},"relearn":"Moods shift slowly; tools help it pass, they don't flick a switch.","persona":"any","source":"not-instant","cat":"bounce-toolkit"},
  {"id":"bn-964","type":"strike-rewrite","hook":"\"Self-compassion is just making excuses for yourself.\"","myth":{"un":"Self-compassion is just making excuses for yourself.","re":"It means being fair and kind to yourself while you still try again.","why":"People are actually braver and try harder when they're not self-attacking."},"relearn":"It means being fair and kind to yourself while you still try again.","persona":"Riya","source":"compassion-not-excuse","cat":"bounce-toolkit"},
  {"id":"bn-965","type":"strike-rewrite","hook":"\"Taking a break means you're lazy and falling behind.\"","myth":{"un":"Taking a break means you're lazy and falling behind.","re":"Short breaks restore focus, so you get more done, not less.","why":"A rested brain learns and remembers far better than an exhausted one."},"relearn":"Short breaks restore focus, so you get more done, not less.","persona":"Riya","source":"break-not-lazy","cat":"bounce-toolkit"},
  {"id":"bn-966","type":"strike-rewrite","hook":"\"Real coping means handling it all by yourself.\"","myth":{"un":"Real coping means handling it all by yourself.","re":"Tools work best with people; reaching out is part of coping, not a fail.","why":"Connection is one of the strongest tools there is, not a last resort."},"relearn":"Tools work best with people; reaching out is part of coping, not a fail.","persona":"Veer","source":"not-alone","cat":"bounce-toolkit"},
  {"id":"bn-967","type":"strike-rewrite","hook":"\"One tiny step is pointless when the problem is huge.\"","myth":{"un":"One tiny step is pointless when the problem is huge.","re":"One small step breaks the freeze and builds the momentum to keep going.","why":"Big comebacks are just small steps stacked up; you can't skip to the end."},"relearn":"One small step breaks the freeze and builds the momentum to keep going.","persona":"any","source":"tiny-steps-count","cat":"bounce-toolkit"},
  {"id":"bn-968","type":"strike-rewrite","hook":"\"Writing your feelings down is pointless venting.\"","myth":{"un":"Writing your feelings down is just pointless venting.","re":"Putting feelings into words on paper helps your brain settle them.","why":"Naming a feeling on the page lowers its grip and clears your head."},"relearn":"Putting feelings into words on paper helps your brain settle them.","persona":"any","source":"journaling-works","cat":"bounce-toolkit"},
  {"id":"bn-969","type":"role-play","hook":"You flopped a test and a friend asks how it went.","setup":"Tell the truth. Say:","yourLine":[{"text":"\"Honestly, it went badly and I'm pretty gutted.\"","best":true},{"text":"\"Yeah, fine, whatever.\""}],"relearn":"Saying it out loud to a friend lightens the load you're carrying.","persona":"Veer","source":"honesty","cat":"bounce-toolkit"},
  {"id":"bn-970","type":"role-play","hook":"Your inner voice is calling you a failure after a slip.","setup":"Answer the harsh voice fairly. Say:","yourLine":[{"text":"\"That's harsh. I had one bad day, and I'm still learning.\"","best":true},{"text":"\"You're right, I always ruin everything.\""}],"relearn":"Answering harsh self-talk with a fair line is a real coping skill.","persona":"any","source":"self-talk","cat":"bounce-toolkit"},
  {"id":"bn-971","type":"role-play","hook":"You're overwhelmed and a parent asks if you need anything.","setup":"Let them in a little. Say:","yourLine":[{"text":"\"Actually, could you just sit with me for a bit?\"","best":true},{"text":"\"Nothing, I'm fine, leave me alone.\""}],"relearn":"Letting a parent in, even a little, eases the weight you're carrying.","persona":"Riya","source":"asking-home","cat":"bounce-toolkit"},
  {"id":"bn-972","type":"role-play","hook":"You need help on a topic but feel embarrassed to ask.","setup":"Ask clearly. Say:","yourLine":[{"text":"\"I'm stuck on this part, can you walk me through it?\"","best":true},{"text":"\"Nah, I'll figure it out\" (then stay stuck)."}],"relearn":"A clear, calm ask gets you unstuck; it isn't weakness, it's smart.","persona":"Veer","source":"help-seeking","cat":"bounce-toolkit"},
  {"id":"bn-973","type":"role-play","hook":"You want to take a rest but feel guilty about it.","setup":"Give yourself permission. Say:","yourLine":[{"text":"\"I've worked hard; resting now will help me come back sharper.\"","best":true},{"text":"\"I can't stop, stopping means I'm lazy.\""}],"relearn":"Giving yourself permission to rest is part of how resilience works.","persona":"Veer","source":"rest","cat":"bounce-toolkit"},
  {"id":"bn-974","type":"role-play","hook":"A small mistake has you wanting to quit the whole thing.","setup":"Keep perspective out loud. Say:","yourLine":[{"text":"\"One mistake isn't the end. I'll fix it and keep going.\"","best":true},{"text":"\"It's all ruined, there's no point now.\""}],"relearn":"Talking yourself off the ledge of all-or-nothing keeps you in the game.","persona":"any","source":"perspective","cat":"bounce-toolkit"},
  {"id":"bn-975","type":"role-play","hook":"You're spiralling and decide to ground yourself out loud.","setup":"Ground yourself out loud. Say:","yourLine":[{"text":"\"Feet on the floor, slow breath out. This feeling will pass.\"","best":true},{"text":"\"I just have to keep panicking until it stops.\""}],"relearn":"Talking yourself through grounding pulls you back to the present.","persona":"any","source":"grounding","cat":"bounce-toolkit"},
  {"id":"bn-976","type":"role-play","hook":"Low feelings have lasted a while and a teacher checks in.","setup":"Be honest with the adult. Say:","yourLine":[{"text":"\"It's been low for weeks, honestly. I think I need help.\"","best":true},{"text":"\"I'm okay, just tired\" (when you're really not)."}],"relearn":"If low feelings last weeks, telling a trusted adult is the brave move.","persona":"Counsellor","source":"reach-out","cat":"bounce-toolkit"},
  {"id":"bn-990","type":"branch","hook":"It's the night before boards and your mind is racing; you can't sleep.","options":[{"text":"Stop revising, breathe slowly and rest a bit","consequence":"A rested brain recalls more than a panicked one.","best":true},{"text":"Cram all night and skip sleep entirely","consequence":"No-sleep cramming wrecks recall; rest helps you perform."}],"debrief":"Sleep before a board exam helps more than one more all-nighter.","relearn":"Rest before an exam helps recall more than panic-cramming.","persona":"Riya","source":"exam stress / sleep (India)","cat":"exam-pressure"},
  {"id":"bn-991","type":"branch","hook":"You blanked on a question in the board exam and lost time panicking.","options":[{"text":"Take a breath, skip it, and come back later","consequence":"Calm and moving on saves the rest of the paper.","best":true},{"text":"Freeze and stare at it for twenty minutes","consequence":"Freezing on one question can sink the whole paper."}],"debrief":"Blanking happens; breathe, skip ahead, return with a clearer head.","relearn":"If you blank, breathe and move on; panic isn't the only option.","persona":"any","source":"exam panic / strategy","cat":"exam-pressure"},
  {"id":"bn-992","type":"branch","hook":"Tuition friends keep sharing predicted ranks in the group chat.","options":[{"text":"Mute the chat this season and run your own race","consequence":"Less comparison noise, steadier focus on your prep.","best":true},{"text":"Refresh the chat and compare yourself all day","consequence":"Constant rank-comparison feeds anxiety, not progress."}],"debrief":"Stepping out of rank chatter protects your focus and calm.","relearn":"Muting comparison noise frees you to focus on your progress.","persona":"Riya","source":"comparison / exam stress","cat":"exam-pressure"},
  {"id":"bn-993","type":"branch","hook":"A relative asks at every visit, 'How much will you score?'","options":[{"text":"Say you're working hard and change the subject","consequence":"You set a boundary without a fight, and breathe easier.","best":true},{"text":"Let the question crush you each time in silence","consequence":"Carrying every 'how much?' alone just feeds the dread."}],"debrief":"You can be polite and still guard against score-pressure talk.","relearn":"You can deflect score-pressure questions without them ruling your mood.","persona":"Veer","source":"family pressure (India)","cat":"exam-pressure"},
  {"id":"bn-994","type":"branch","hook":"You've studied for hours but feel you've learned nothing.","options":[{"text":"Stop and rest; learning isn't always visible","consequence":"You recover energy, and tomorrow's study lands better.","best":true},{"text":"Force three more hours while exhausted and foggy","consequence":"Studying past exhaustion teaches little and burns you out."}],"debrief":"A fried brain stores little; rest is part of study, not failure.","relearn":"When study stops landing, rest; a tired brain can't absorb more.","persona":"any","source":"study / rest","cat":"exam-pressure"},
  {"id":"bn-995","type":"branch","hook":"A coaching teacher posts a 'toppers only' list and you're not on it.","options":[{"text":"Notice the sting, then refocus on your own next chapter","consequence":"The hurt passes and you keep your momentum.","best":true},{"text":"Decide you're hopeless and stop trying","consequence":"One list isn't a verdict on you; quitting helps no one."}],"debrief":"A toppers list ranks one moment, not your worth or your future.","relearn":"A ranking list is one snapshot, not a verdict on who you are.","persona":"Riya","source":"comparison / coaching (India)","cat":"exam-pressure"},
  {"id":"bn-996","type":"branch","hook":"Your model-test marks dropped; you want to give up before boards.","options":[{"text":"Treat the low mock as data and adjust your plan","consequence":"You find the weak topics and improve before it counts.","best":true},{"text":"Take the mock as proof you'll fail the real exam","consequence":"A mock is practice, not a prophecy of the board result."}],"debrief":"Mocks are for finding gaps in time, not for predicting doom.","relearn":"A low mock is practice data to learn from, not a verdict.","persona":"Veer","source":"mock tests / growth","cat":"exam-pressure"},
  {"id":"bn-997","type":"branch","hook":"You want to study a stream your parents call a 'waste'.","options":[{"text":"Hear them, then calmly share why the path fits you","consequence":"They see your reasoning, and the door stays open.","best":true},{"text":"Give up on your interest to avoid the argument","consequence":"Silencing your interest now stores up regret later."}],"debrief":"Many honest paths exist; your interest is worth a calm conversation.","relearn":"There are many good paths; your interest deserves a real conversation.","persona":"any","source":"career paths / family","cat":"exam-pressure"},
  {"id":"bn-998","type":"branch","hook":"Results are out tomorrow and the waiting is unbearable.","options":[{"text":"Plan a calm tomorrow and line up someone to talk to","consequence":"Whatever the number, you won't face it alone.","best":true},{"text":"Spiral all night imagining the worst outcome","consequence":"Imagining disaster all night changes nothing but your sleep."}],"debrief":"You can't control the result, but you can plan support around it.","relearn":"Before a result, line up support; you won't face the number alone.","persona":"Counsellor","source":"results day / support","cat":"exam-pressure"},
  {"id":"bn-999","type":"branch","hook":"You scored far below your hopes and feel you've let everyone down.","options":[{"text":"Tell a trusted adult and ask about other paths","consequence":"You learn one result opens, not closes, the road ahead.","best":true},{"text":"Hide the result and carry the shame alone","consequence":"Hiding it blocks the other paths an adult could show."}],"debrief":"A low result is survivable; a trusted adult can show the next path.","relearn":"A poor result isn't the end; talk it through, find another path.","persona":"Counsellor","source":"results / help-seeking","cat":"exam-pressure"},
  {"id":"bn-1000","type":"branch","hook":"A senior says one entrance exam is your 'only shot' in life.","options":[{"text":"Hear them, but remember many roads lead forward","consequence":"You keep perspective and lower the all-or-nothing stakes.","best":true},{"text":"Believe it fully and let the dread take over","consequence":"No single exam is the one gate; that belief just crushes you."}],"debrief":"One entrance exam is one route; good lives are built many ways.","relearn":"No single exam is your only shot; many paths lead forward.","persona":"any","source":"exam pressure / paths","cat":"exam-pressure"},
  {"id":"bn-1001","type":"branch","hook":"You keep procrastinating because the syllabus feels impossibly huge.","options":[{"text":"Pick one small chapter and start it for ten minutes","consequence":"Starting small breaks the freeze and builds momentum.","best":true},{"text":"Wait until you 'feel ready' to begin","consequence":"Waiting to feel ready keeps the whole syllabus stuck."}],"debrief":"A huge syllabus shrinks when you start with one small piece.","relearn":"One small chapter beats waiting to feel ready before you start.","persona":"any","source":"procrastination / small steps","cat":"exam-pressure"},
  {"id":"bn-1002","type":"branch","hook":"Your hands shake and chest tightens as the exam doors open.","options":[{"text":"Breathe out slowly, feel your feet, and walk in","consequence":"The body settles enough to read the first question.","best":true},{"text":"Tell yourself the panic means you'll definitely fail","consequence":"Exam nerves are normal, not a sign you'll fail the paper."}],"debrief":"Exam-hall nerves are normal; slow breathing helps you start.","relearn":"Exam nerves are normal; a slow breath steadies you to begin.","persona":"any","source":"exam anxiety / regulation","cat":"exam-pressure"},
  {"id":"bn-1003","type":"branch","hook":"You failed one subject; friends all passed and you feel humiliated.","options":[{"text":"Let the shame be there, then ask how to clear it","consequence":"You find a re-exam or retake path and move forward.","best":true},{"text":"Avoid friends and brand yourself the class failure","consequence":"Failing one subject is an event, not who you are."}],"debrief":"Failing a subject is one event with a next step, not your identity.","relearn":"Failing one subject is an event with a next step, not your identity.","persona":"Veer","source":"failure / reframe (India)","cat":"exam-pressure"},
  {"id":"bn-1004","type":"branch","hook":"A parent compares you to a cousin who 'always tops'.","options":[{"text":"Stay calm and focus on your own steady progress","consequence":"The comparison loses its grip and you keep going.","best":true},{"text":"Carry the comparison as proof you're not good enough","consequence":"Their cousin's marks aren't a measure of your worth."}],"debrief":"Comparison is the thief of calm; your own progress is the real race.","relearn":"A cousin's marks don't measure you; run your own race.","persona":"Riya","source":"comparison / family (India)","cat":"exam-pressure"},
  {"id":"bn-1005","type":"branch","hook":"You've crammed for days and now feel numb and can't focus at all.","options":[{"text":"Take a real break: walk, eat, sleep, then return","consequence":"Your focus comes back after you actually rest.","best":true},{"text":"Drink more chai and push through the fog","consequence":"Pushing through burnout makes the fog worse, not better."}],"debrief":"Burnout fog means stop and recharge, not caffeinate and grind.","relearn":"Burnout fog is a signal to rest, not to push harder on caffeine.","persona":"any","source":"burnout / rest","cat":"exam-pressure"},
  {"id":"bn-1006","type":"branch","hook":"You're tempted to copy in the exam because you feel under-prepared.","options":[{"text":"Do your honest best with what you know","consequence":"You keep your integrity and answer what you can.","best":true},{"text":"Risk cheating to chase a few extra marks","consequence":"A few risky marks aren't worth your integrity or the danger."}],"debrief":"Your honest best protects you; a setback is recoverable, shame less so.","relearn":"Your honest best is enough; chasing marks by cheating isn't worth it.","persona":"any","source":"integrity / exam","cat":"exam-pressure"},
  {"id":"bn-1007","type":"branch","hook":"A friend in your study group keeps panicking and it's rubbing off on you.","options":[{"text":"Step away gently and steady yourself before the exam","consequence":"You protect your calm and can support them later.","best":true},{"text":"Absorb their panic and spiral together","consequence":"Catching their panic helps neither of you walk in steady."}],"debrief":"You can care for a panicking friend without catching their panic.","relearn":"You can support a panicking friend without absorbing their panic.","persona":"any","source":"peer stress / boundaries","cat":"exam-pressure"},
  {"id":"bn-1008","type":"branch","hook":"You're stuck choosing subjects and afraid of 'picking wrong'.","options":[{"text":"Talk it through with a teacher or counsellor","consequence":"You get real guidance and the choice feels less final.","best":true},{"text":"Decide alone in panic that one wrong pick ruins it","consequence":"No single subject choice locks or ruins your future."}],"debrief":"Subject choices can be revisited; a trusted adult makes them clearer.","relearn":"A subject choice isn't a life sentence; a trusted adult can help.","persona":"Counsellor","source":"subject choice / guidance","cat":"exam-pressure"},
  {"id":"bn-1009","type":"branch","hook":"Exam stress has hit your sleep and appetite for weeks now.","options":[{"text":"Tell a trusted adult or call Tele-MANAS 14416","consequence":"You get real help instead of grinding through alone.","best":true},{"text":"Push through alone and hope it just passes","consequence":"Weeks of stress hitting sleep and eating deserve support."}],"debrief":"Stress that disrupts sleep and eating for weeks means reach out.","relearn":"Lasting exam stress deserves a trusted adult or Tele-MANAS 14416.","persona":"Counsellor","source":"help-seeking / Tele-MANAS","cat":"exam-pressure"},
  {"id":"bn-1010","type":"branch","hook":"You dropped a year for prep and feel ashamed when people ask.","options":[{"text":"Own it calmly: a different timeline, not a failure","consequence":"You meet the question with steadiness, not shame.","best":true},{"text":"Let shame convince you you've fallen behind in life","consequence":"A drop year is a different pace, not a verdict on you."}],"debrief":"A drop year is a timeline choice, not a measure of your worth.","relearn":"A drop year is a different timeline, not a sign you've failed.","persona":"Veer","source":"drop year / reframe (India)","cat":"exam-pressure"},
  {"id":"bn-1011","type":"strike-rewrite","hook":"\"If I'm not the topper, I've failed.\"","myth":{"un":"If I don't top the class, I've failed.","re":"Doing your honest best is success, whatever the rank.","why":"Effort you control; a rank depends on everyone else too."},"relearn":"Your honest best is success; the rank isn't all on you.","persona":"Riya","source":"perfectionism (India)","cat":"exam-pressure"},
  {"id":"bn-1012","type":"strike-rewrite","hook":"\"My board percentage decides my entire life.\"","myth":{"un":"My board percentage will define my whole life.","re":"Boards open one door; life keeps opening many more.","why":"People build good lives through many routes after boards."},"relearn":"Your board percentage opens one door, not your whole life.","persona":"Veer","source":"boards / paths (India)","cat":"exam-pressure"},
  {"id":"bn-1013","type":"strike-rewrite","hook":"\"Being nervous before exams means I'm weak.\"","myth":{"un":"Feeling anxious before an exam means I'm weak.","re":"Exam nerves are normal and even sharpen your focus.","why":"A little stress is your body gearing up, not a flaw."},"relearn":"Exam nerves are normal; they don't mean you're weak.","persona":"any","source":"anxiety (India)","cat":"exam-pressure"},
  {"id":"bn-1014","type":"strike-rewrite","hook":"\"Resting at all during exams means falling behind.\"","myth":{"un":"I have to study every waking hour or I'll fall behind.","re":"Rest and breaks are what let study actually stick.","why":"A rested brain stores memory; an exhausted one can't."},"relearn":"Breaks and rest help study stick; non-stop grinding doesn't.","persona":"any","source":"study / rest","cat":"exam-pressure"},
  {"id":"bn-1015","type":"strike-rewrite","hook":"\"Asking the teacher for help makes me look stupid.\"","myth":{"un":"If I ask the teacher for help, I'll look stupid.","re":"Asking when stuck is smart and gets you unstuck faster.","why":"The best students ask questions; it speeds up learning."},"relearn":"Asking for help is smart, not stupid; it gets you unstuck.","persona":"Riya","source":"help-seeking (India)","cat":"exam-pressure"},
  {"id":"bn-1016","type":"strike-rewrite","hook":"\"A bad mark means my parents won't love me.\"","myth":{"un":"One bad mark and my parents will stop loving me.","re":"Parents may worry about marks, but you are not your marks.","why":"Their worry is about your future, not your worth to them."},"relearn":"Parents' worry about marks isn't them measuring your worth.","persona":"Veer","source":"family / worth (India)","cat":"exam-pressure"},
  {"id":"bn-1017","type":"strike-rewrite","hook":"\"Everyone else is fine; only I'm falling apart.\"","myth":{"un":"Everyone else has it figured out; only I'm struggling.","re":"Most students hide the same stress you're feeling.","why":"Exam pressure is common; calm faces often hide hard days."},"relearn":"You're not the only one struggling; many hide the same stress.","persona":"Riya","source":"comparison (India)","cat":"exam-pressure"},
  {"id":"bn-1018","type":"strike-rewrite","hook":"\"If I miss this seat, my future is finished.\"","myth":{"un":"If I don't get this seat, my future is over.","re":"Missing one seat is a detour, not the end of the road.","why":"There are many colleges, intakes and second chances."},"relearn":"Missing one seat is a detour; many roads still lie ahead.","persona":"any","source":"admissions / paths (India)","cat":"exam-pressure"},
  {"id":"bn-1019","type":"strike-rewrite","hook":"\"If I cry about the stress, I can't cope.\"","myth":{"un":"Crying about exam stress means I can't handle it.","re":"Letting the feeling out helps you steady and carry on.","why":"Feeling it, then moving through, is how resilience works."},"relearn":"Crying isn't failing; feeling it then moving through is resilience.","persona":"Veer","source":"emotions (India)","cat":"exam-pressure"},
  {"id":"bn-1020","type":"strike-rewrite","hook":"\"My worth goes up and down with each score.\"","myth":{"un":"My self-worth rises and falls with each test score.","re":"A score measures one paper; your worth stays steady.","why":"Worth comes from who you are, not a changing number."},"relearn":"Test scores change; your worth isn't tied to the number.","persona":"Riya","source":"self-worth (India)","cat":"exam-pressure"},
  {"id":"bn-1021","type":"strike-rewrite","hook":"\"If I fall behind in prep, it's over.\"","myth":{"un":"Once I fall behind in prep, I can never catch up.","re":"Falling behind is recoverable with a fresh, smaller plan.","why":"A focused restart beats giving up on the time you have."},"relearn":"Falling behind is recoverable; a smaller, fresh plan helps.","persona":"any","source":"prep / recovery","cat":"exam-pressure"},
  {"id":"bn-1022","type":"strike-rewrite","hook":"\"Wanting a break during exams means I'm lazy.\"","myth":{"un":"Asking for a break makes me lazy and undeserving.","re":"Rest is part of doing well, not a reward you must earn.","why":"Your brain needs recovery to learn; that isn't laziness."},"relearn":"Rest is part of performing, not laziness you have to earn.","persona":"any","source":"rest / self-compassion","cat":"exam-pressure"},
  {"id":"bn-1023","type":"sort","hook":"Sort: a calming exam-day habit, or a stress-spiking one?","items":[{"id":"a","text":"Eating breakfast before the exam"},{"id":"b","text":"Refreshing the class group chat"},{"id":"c","text":"Doing a slow breath in the hall"},{"id":"d","text":"Cramming new topics minutes before"},{"id":"e","text":"Reaching the centre with time to spare"},{"id":"f","text":"Arguing about answers right after"}],"bins":[{"id":"calm","label":"Calms you","valence":"pos"},{"id":"spike","label":"Spikes stress","valence":"neg"}],"key":{"a":"calm","b":"spike","c":"calm","d":"spike","e":"calm","f":"spike"},"relearn":"Breakfast, breath and arriving early calm you; cramming and chats spike stress.","persona":"any","source":"exam-day habits (India)","cat":"exam-pressure"},
  {"id":"bn-1024","type":"sort","hook":"Sort: a real coping tool, or 'just think positive' pretending?","items":[{"id":"a","text":"Naming what you actually feel"},{"id":"b","text":"Telling yourself to 'stop being sad'"},{"id":"c","text":"Talking it out with someone you trust"},{"id":"d","text":"Pretending the worry isn't there"},{"id":"e","text":"Taking one small study step"},{"id":"f","text":"Forcing a smile and bottling it up"}],"bins":[{"id":"real","label":"Real coping","valence":"pos"},{"id":"fake","label":"Forced positivity","valence":"neg"}],"key":{"a":"real","b":"fake","c":"real","d":"fake","e":"real","f":"fake"},"relearn":"Naming feelings and small steps cope; bottling up and faking it don't.","persona":"any","source":"coping vs toxic positivity","cat":"exam-pressure"},
  {"id":"bn-1025","type":"sort","hook":"Sort: what an exam result can measure, or what it can't?","items":[{"id":"a","text":"One paper on one day"},{"id":"b","text":"How kind you are"},{"id":"c","text":"A slice of a subject"},{"id":"d","text":"Your curiosity and grit"},{"id":"e","text":"Whether you tried that day"},{"id":"f","text":"How good a friend you are"}],"bins":[{"id":"canmeasure","label":"A result can measure","valence":"neutral"},{"id":"cannot","label":"No result can measure","valence":"pos"}],"key":{"a":"canmeasure","b":"cannot","c":"canmeasure","d":"cannot","e":"canmeasure","f":"cannot"},"relearn":"A result measures one paper; it can't measure your kindness or worth.","persona":"Riya","source":"self-worth (India)","cat":"exam-pressure"},
  {"id":"bn-1026","type":"sort","hook":"Sort: helps your focus while studying, or quietly drains it?","items":[{"id":"a","text":"A quiet phone in another room"},{"id":"b","text":"Short walk between subjects"},{"id":"c","text":"Scrolling reels 'for a minute'"},{"id":"d","text":"A glass of water nearby"},{"id":"e","text":"Comparing your pace to others"},{"id":"f","text":"Studying till 3am every night"}],"bins":[{"id":"helps","label":"Helps focus","valence":"pos"},{"id":"drains","label":"Drains focus","valence":"neg"}],"key":{"a":"helps","b":"helps","c":"drains","d":"helps","e":"drains","f":"drains"},"relearn":"A quiet phone, walks and water help; scrolling and 3am nights drain you.","persona":"any","source":"focus / study habits","cat":"exam-pressure"},
  {"id":"bn-1027","type":"sort","hook":"Sort: a steady thought before results, or a spiral thought?","items":[{"id":"a","text":"\"Whatever it is, I'll have support\""},{"id":"b","text":"\"My life is over if it's low\""},{"id":"c","text":"\"One result isn't my whole story\""},{"id":"d","text":"\"Everyone will judge me forever\""},{"id":"e","text":"\"I can find a next step either way\""},{"id":"f","text":"\"I'll never recover from this\""}],"bins":[{"id":"steady","label":"Steady thought","valence":"pos"},{"id":"spiral","label":"Spiral thought","valence":"neg"}],"key":{"a":"steady","b":"spiral","c":"steady","d":"spiral","e":"steady","f":"spiral"},"relearn":"Steady thoughts hold both: it matters, and there's a way forward.","persona":"Veer","source":"results / reframe (India)","cat":"exam-pressure"},
  {"id":"bn-1028","type":"sort","hook":"Sort: a sign your stress needs a trusted adult, or just normal nerves?","items":[{"id":"a","text":"Sleep gone for weeks"},{"id":"b","text":"Butterflies before the exam"},{"id":"c","text":"Appetite gone for weeks"},{"id":"d","text":"Feeling keyed-up the night before"},{"id":"e","text":"Dark thoughts that scare you"},{"id":"f","text":"A racing heart in the hall"}],"bins":[{"id":"reachout","label":"Reach out for help","valence":"tell"},{"id":"normal","label":"Normal exam nerves","valence":"neutral"}],"key":{"a":"reachout","b":"normal","c":"reachout","d":"normal","e":"reachout","f":"normal"},"relearn":"Weeks of lost sleep or scary thoughts mean reach out; brief nerves are normal.","persona":"Counsellor","source":"help-seeking / Tele-MANAS","cat":"exam-pressure"},
  {"id":"bn-1029","type":"sort","hook":"Sort: a fair thing to say to yourself after a low mark, or unfair?","items":[{"id":"a","text":"\"That stings; let me learn from it\""},{"id":"b","text":"\"I'm just a hopeless failure\""},{"id":"c","text":"\"I'll ask where I went wrong\""},{"id":"d","text":"\"I ruin everything I touch\""},{"id":"e","text":"\"One mark isn't all of me\""},{"id":"f","text":"\"Everyone is right to give up on me\""}],"bins":[{"id":"kind","label":"Fair to yourself","valence":"pos"},{"id":"harsh","label":"Unfair to yourself","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"Treat yourself like a friend: learn from the mark, don't brand yourself.","persona":"any","source":"self-compassion","cat":"exam-pressure"},
  {"id":"bn-1030","type":"sort","hook":"Sort: a healthy way to handle parents' pressure, or one that backfires?","items":[{"id":"a","text":"Calmly sharing how you feel"},{"id":"b","text":"Hiding your stress from them"},{"id":"c","text":"Asking a teacher to explain"},{"id":"d","text":"Snapping and slamming the door"},{"id":"e","text":"Agreeing a study routine"},{"id":"f","text":"Pretending everything is fine"}],"bins":[{"id":"healthy","label":"Healthy response","valence":"pos"},{"id":"backfires","label":"Backfires","valence":"neg"}],"key":{"a":"healthy","b":"backfires","c":"healthy","d":"backfires","e":"healthy","f":"backfires"},"relearn":"Talking calmly and sharing the load beat hiding stress or blowing up.","persona":"Veer","source":"family pressure (India)","cat":"exam-pressure"},
  {"id":"bn-1031","type":"reflect","hook":"Lensy: think of a tough test you got through before. What helped you?","prompt":"What got you through?","options":["A friend","A break","Just starting","Time passing"],"affirm":"You've come through hard things before; that strength is still yours.","relearn":"You've bounced back from hard tests before; you can again.","persona":"any","source":"past resilience","cat":"exam-pressure"},
  {"id":"bn-1032","type":"reflect","hook":"Lensy: if a friend got this same mark, what kind thing would you tell them?","prompt":"What would you say?","options":["It's okay","You'll be fine","Let's plan","I'm here"],"affirm":"You can say that same kind thing to yourself, you deserve it.","relearn":"Speak to yourself as kindly as you'd speak to a struggling friend.","persona":"Riya","source":"self-compassion","cat":"exam-pressure"},
  {"id":"bn-1033","type":"reflect","hook":"Lensy: picture life five years from now. How big will this one exam feel?","prompt":"How big?","options":["Much smaller","A blur","A lesson","Barely there"],"affirm":"Most things that feel huge today soften a great deal with time.","relearn":"Most single exams feel far smaller as the years go by.","persona":"any","source":"perspective","cat":"exam-pressure"},
  {"id":"bn-1034","type":"reflect","hook":"Lensy: name one thing you're proud of that no exam could ever score.","prompt":"Name one.","options":["Helping at home","Making people laugh","Sticking by friends","Being curious"],"affirm":"That's real and it matters in your life, far beyond any mark.","relearn":"You hold real strengths that no exam can ever measure.","persona":"any","source":"self-worth","cat":"exam-pressure"},
  {"id":"bn-1035","type":"reflect","hook":"Lensy: when exam stress peaks, who is one person you could lean on?","prompt":"Who comes to mind?","options":["A parent","A teacher","A friend","A counsellor"],"affirm":"Having even one safe person in mind already lightens the load.","relearn":"Naming one safe person makes the heavy days easier to carry.","persona":"any","source":"support / reach-out","cat":"exam-pressure"},
  {"id":"bn-1036","type":"reflect","hook":"Lensy: what's one small thing that helps you reset after a hard study day?","prompt":"What resets you?","options":["A walk","Music","Sleep","Talking"],"affirm":"That little reset is a real tool, keep it close this season.","relearn":"Small resets like a walk or music are real tools, not luxuries.","persona":"any","source":"bounce-toolkit","cat":"exam-pressure"},
  {"id":"bn-1037","type":"reflect","hook":"Lensy: think of a subject that scares you. What's one tiny step into it?","prompt":"One tiny step?","options":["Read one page","Ask a doubt","Watch a video","Try one sum"],"affirm":"One tiny step is enough to start; the rest follows from there.","relearn":"One tiny step into a scary subject beats waiting to feel ready.","persona":"any","source":"small steps","cat":"exam-pressure"},
  {"id":"bn-1038","type":"reflect","hook":"Lensy: besides marks, what do you want to be remembered for at school?","prompt":"What matters to you?","options":["Being kind","Being honest","Being fun","Being a good friend"],"affirm":"That's a worth no result sheet could ever print, and it's yours.","relearn":"Who you are to people outlasts any number on a result sheet.","persona":"Riya","source":"self-worth","cat":"exam-pressure"},
  {"id":"bn-1039","type":"match","hook":"Match the panicky exam thought to a steadier reply.","pairs":[{"left":"\"I'll forget everything\"","right":"I trust the work I've done"},{"left":"\"I'm so far behind\"","right":"I run my own race"},{"left":"\"One bad paper ruins it\"","right":"One paper is one moment"},{"left":"\"I can't ask for help\"","right":"Asking help is smart"},{"left":"\"I must be perfect\"","right":"My honest best is enough"}],"relearn":"Each panicky thought has a calmer, truer reply.","persona":"Riya","source":"reframing (India)","cat":"exam-pressure"},
  {"id":"bn-1040","type":"match","hook":"Match each exam-stress signal to a healthy response.","pairs":[{"left":"Can't sleep the night before","right":"Slow breaths, then rest"},{"left":"Mind goes blank in the hall","right":"Skip it and come back"},{"left":"Stress lasts for weeks","right":"Tell a trusted adult"},{"left":"Stuck on a hard topic","right":"Ask a teacher for help"},{"left":"Comparing ranks all day","right":"Mute and run your own race"}],"relearn":"Every exam-stress signal has a real, doable response.","persona":"any","source":"coping / help-seeking","cat":"exam-pressure"},
  {"id":"bn-1041","type":"match","hook":"Match each thing to whether it can measure your worth.","pairs":[{"left":"One test score","right":"Measures one paper"},{"left":"How you treat people","right":"Shows your real worth"},{"left":"Your class rank","right":"Just one snapshot"},{"left":"Your effort and curiosity","right":"Part of who you are"},{"left":"A toppers list","right":"One moment, not a verdict"}],"relearn":"Scores and ranks measure moments; your character is your real worth.","persona":"Riya","source":"self-worth (India)","cat":"exam-pressure"},
  {"id":"bn-1042","type":"match","hook":"Match the bounce-back tool to what it helps with.","pairs":[{"left":"Slow breathing","right":"Calms a racing body"},{"left":"One small step","right":"Breaks the freeze"},{"left":"Talking it out","right":"Lightens the load"},{"left":"Naming the feeling","right":"Stops bottling up"},{"left":"Asking for help","right":"Finds another path"}],"relearn":"Each toolkit move helps a real part of exam stress.","persona":"any","source":"bounce-toolkit","cat":"exam-pressure"},
  {"id":"bn-1043","type":"match","hook":"Match the pressure line to the honest reframe.","pairs":[{"left":"\"This exam is everything\"","right":"It's one of many steps"},{"left":"\"Breaks are lazy\"","right":"Rest helps me learn"},{"left":"\"A drop year means I failed\"","right":"It's a different timeline"},{"left":"\"I'm my marks\"","right":"I'm far more than marks"},{"left":"\"I can't recover from this\"","right":"Setbacks aren't permanent"}],"relearn":"Every pressure line meets an honest, kinder truth.","persona":"Veer","source":"reframe (India)","cat":"exam-pressure"},
  {"id":"bn-1044","type":"match","hook":"Match each person to the help they can offer with exam stress.","pairs":[{"left":"A trusted teacher","right":"Explains the tough topics"},{"left":"A parent you trust","right":"Eases the pressure at home"},{"left":"A school counsellor","right":"Helps with the worry"},{"left":"Tele-MANAS 14416","right":"Support for student stress"},{"left":"A good friend","right":"Reminds you you're not alone"}],"relearn":"Many people and helplines can share the weight of exam stress.","persona":"Counsellor","source":"support map (India)","cat":"exam-pressure"},
  {"id":"bn-1045","type":"match","hook":"Match the study trap to a healthier swap.","pairs":[{"left":"All-night cramming","right":"Sleep, then revise"},{"left":"Skipping meals to study","right":"Eat, then focus"},{"left":"Scrolling 'for a minute'","right":"Phone in another room"},{"left":"Studying with no plan","right":"One chapter at a time"},{"left":"Comparing your pace","right":"Track your own progress"}],"relearn":"Each study trap has a kinder, more effective swap.","persona":"any","source":"study habits","cat":"exam-pressure"},
  {"id":"bn-1046","type":"build","hook":"Build a calm exam-morning routine.","prompt":"Order the steps that steady you.","pieces":["eat a proper breakfast","pack everything the night before","do a few slow breaths","reach the centre early"],"mode":"sequence","key":["pack everything the night before","eat a proper breakfast","do a few slow breaths","reach the centre early"],"relearn":"A calm exam morning is planned, fed, breathed and early.","persona":"any","source":"exam-day routine (India)","cat":"exam-pressure"},
  {"id":"bn-1047","type":"build","hook":"Build a study plan that won't burn you out.","prompt":"Order a sustainable study block.","pieces":["pick one topic","study in a focused stretch","take a short break","reward the small win"],"mode":"sequence","key":["pick one topic","study in a focused stretch","take a short break","reward the small win"],"relearn":"Sustainable study: one topic, focus, break, then a small reward.","persona":"Riya","source":"study habits","cat":"exam-pressure"},
  {"id":"bn-1048","type":"build","hook":"Build your 'calm the storm' kit for exam stress.","prompt":"Pick the tools that actually regulate you.","pieces":["slow breathing","a short walk","writing it down","reaching out to someone"],"mode":"assemble","key":["slow breathing","a short walk","writing it down","reaching out to someone"],"relearn":"Calm the storm with breath, movement, writing and reaching out.","persona":"any","source":"regulation kit","cat":"exam-pressure"},
  {"id":"bn-1049","type":"build","hook":"Build the steps to bounce back from a low mark.","prompt":"Order what actually helps.","pieces":["let yourself feel it","talk it over with someone","find one lesson in it","take one next step"],"mode":"sequence","key":["let yourself feel it","talk it over with someone","find one lesson in it","take one next step"],"relearn":"Bounce back from a low mark: feel it, talk, learn, step forward.","persona":"Veer","source":"bounce-back process","cat":"exam-pressure"},
  {"id":"bn-1050","type":"build","hook":"Build a 'zoom out' move when one exam feels like everything.","prompt":"Pick the questions that shrink it.","pieces":["will this matter in five years?","what's still okay right now?","what can I actually control?","who could help me with this?"],"mode":"assemble","key":["will this matter in five years?","what's still okay right now?","what can I actually control?","who could help me with this?"],"relearn":"Zoom out: time, what's okay, what you control, and who can help.","persona":"any","source":"perspective / zoom-out","cat":"exam-pressure"},
  {"id":"bn-1051","type":"build","hook":"Build a kind self-talk kit for after a hard paper.","prompt":"Pick the lines that are fair to you.","pieces":["\"I did what I could today\"","\"One paper isn't all of me\"","\"I can learn from this\"","\"I'm allowed to feel low\""],"mode":"assemble","key":["\"I did what I could today\"","\"One paper isn't all of me\"","\"I can learn from this\"","\"I'm allowed to feel low\""],"relearn":"After a hard paper, talk to yourself like a friend would.","persona":"any","source":"self-compassion","cat":"exam-pressure"},
  {"id":"bn-1052","type":"build","hook":"Build the steps to ask a teacher for help with a topic.","prompt":"Order how to reach out.","pieces":["notice exactly where you're stuck","write down your question","ask the teacher after class","try it again with their tip"],"mode":"sequence","key":["notice exactly where you're stuck","write down your question","ask the teacher after class","try it again with their tip"],"relearn":"Asking for help is a skill: spot the gap, ask, then try again.","persona":"Riya","source":"help-seeking (India)","cat":"exam-pressure"},
  {"id":"bn-1053","type":"build","hook":"Build a comeback plan after falling behind in prep.","prompt":"Order a realistic restart.","pieces":["list what's actually left","cut it into small chunks","start the first chunk today","review your progress weekly"],"mode":"sequence","key":["list what's actually left","cut it into small chunks","start the first chunk today","review your progress weekly"],"relearn":"Falling behind is recoverable with a small, fresh, doable plan.","persona":"any","source":"recovery / small steps","cat":"exam-pressure"},
  {"id":"bn-1054","type":"role-play","hook":"A parent pushes hard about your expected board marks.","setup":"Set a calm boundary. Say:","yourLine":[{"text":"\"I'm working hard. The pressure makes it harder, not easier.\"","best":true},{"text":"\"...\" (say nothing and bottle the stress up)"}],"relearn":"You can name the pressure calmly instead of bottling it up.","persona":"Veer","source":"family pressure (India)","cat":"exam-pressure"},
  {"id":"bn-1055","type":"role-play","hook":"You're stuck on a topic and the exam is close.","setup":"Ask for help out loud. Say:","yourLine":[{"text":"\"Sir, I'm stuck on this part, could you explain it once more?\"","best":true},{"text":"\"It's fine, I'll just figure it out alone.\" (then stay stuck)"}],"relearn":"Asking a teacher when stuck is smart and gets you unstuck.","persona":"Riya","source":"help-seeking (India)","cat":"exam-pressure"},
  {"id":"bn-1056","type":"role-play","hook":"A friend keeps comparing ranks and it's stressing you.","setup":"Protect your calm kindly. Say:","yourLine":[{"text":"\"Let's not compare ranks today, I just want to focus, okay?\"","best":true},{"text":"\"Yeah, tell me everyone's marks again.\" (and spiral)"}],"relearn":"You can step out of rank-comparison without dropping the friend.","persona":"any","source":"comparison / boundaries","cat":"exam-pressure"},
  {"id":"bn-1057","type":"role-play","hook":"You got a low mark and your friend asks how it went.","setup":"Be honest, not ashamed. Say:","yourLine":[{"text":"\"It went badly and I'm low about it, but I'm figuring out next steps.\"","best":true},{"text":"\"It was fine.\" (hide it and carry the shame alone)"}],"relearn":"Naming a low result honestly beats hiding it and carrying shame.","persona":"Veer","source":"failure / honesty (India)","cat":"exam-pressure"},
  {"id":"bn-1058","type":"role-play","hook":"Exam stress has built up for weeks and you need to tell someone.","setup":"Reach out to a trusted adult. Say:","yourLine":[{"text":"\"I've been really struggling with exam stress, can we talk?\"","best":true},{"text":"\"I'm okay.\" (and keep grinding through it alone)"}],"relearn":"Telling a trusted adult about lasting stress is strength, not weakness.","persona":"Counsellor","source":"help-seeking","cat":"exam-pressure"},
  {"id":"bn-1059","type":"role-play","hook":"A relative jokes that your stream is 'for people who can't crack JEE'.","setup":"Stand by your choice. Say:","yourLine":[{"text":"\"It's the path that fits me, and I'm okay with that.\"","best":true},{"text":"\"Maybe you're right, I should just do what you all want.\""}],"relearn":"You can stand by a path that fits you against the comparison.","persona":"any","source":"career paths / family (India)","cat":"exam-pressure"},
  {"id":"bn-1060","type":"role-play","hook":"A friend says they feel hopeless about the exam.","setup":"Listen and stay close. Say:","yourLine":[{"text":"\"That sounds really heavy. I'm here, do you want to talk about it?\"","best":true},{"text":"\"Just relax, it's not even a big deal.\" (and brush it off)"}],"relearn":"Start with listening and presence, not brushing a friend off.","persona":"any","source":"peer support / listening","cat":"exam-pressure"},
  {"id":"bn-1061","type":"role-play","hook":"You need a break but feel guilty even asking for one.","setup":"Give yourself permission. Say:","yourLine":[{"text":"\"I'll rest for a bit so my brain can actually take this in.\"","best":true},{"text":"\"No, resting means I'm lazy.\" (and push past exhaustion)"}],"relearn":"Telling yourself rest is allowed is part of studying well.","persona":"any","source":"self-compassion / rest","cat":"exam-pressure"},
  {"id":"bn-1080","cat":"reach-out","type":"branch","hook":"You've felt flat and empty for weeks; nothing you love feels fun.","options":[{"text":"Tell a trusted adult or call Tele-MANAS (14416)","consequence":"You get support for what isn't lifting on its own.","outcome":"supported","best":true},{"text":"Assume it's a mood and ride it out","consequence":"Weeks of flatness deserve real support; reach out."}],"debrief":"Losing interest in everything for weeks is a sign to reach out.","relearn":"If low feelings last weeks, tell an adult or call Tele-MANAS (14416).","persona":"Counsellor","source":"persistent low mood / help-seeking"},
  {"id":"bn-1081","cat":"reach-out","type":"branch","hook":"At 2am a thought hits: you don't want to be here anymore.","options":[{"text":"Wake a trusted adult, or call Tele-MANAS 14416 / Childline 1098","consequence":"You reach people trained to keep you safe.","outcome":"safe","best":true},{"text":"Wait until morning, tell no one","consequence":"A thought this heavy needs someone now; reach out."}],"debrief":"Any thought of not wanting to be here means reach out right away.","relearn":"Thoughts of not wanting to be here mean reach out now: Tele-MANAS 14416, Childline 1098/112.","persona":"Counsellor","source":"crisis / immediate routing"},
  {"id":"bn-1082","cat":"reach-out","type":"branch","hook":"You feel low but think others have 'real' problems, so you stay quiet.","options":[{"text":"Reach out anyway; you needn't earn the right to help","consequence":"You get support before it grows heavier.","outcome":"supported","best":true},{"text":"Wait until you're 'bad enough'","consequence":"Your pain needn't be the worst to deserve help."}],"debrief":"Help isn't ranked; you needn't be the worst-off to deserve it.","relearn":"You can ask for help any time; your problem doesn't have to be 'big enough'.","persona":"any","source":"help-seeking / minimising"},
  {"id":"bn-1083","cat":"reach-out","type":"branch","hook":"You hinted to a teacher you were struggling; they said 'you'll be fine'.","options":[{"text":"Try another trusted adult, or call a helpline","consequence":"Someone will take it seriously; one miss isn't the end.","outcome":"persistent","best":true},{"text":"Take it as proof no one will help","consequence":"If one adult misses it, another will hear you."}],"debrief":"One brush-off isn't the verdict; the next person may hear you.","relearn":"If brushed off once, tell someone else or call a helpline; keep going.","persona":"any","source":"help-seeking / persistence"},
  {"id":"bn-1084","cat":"reach-out","type":"branch","hook":"Crying spells hit most days for over a month and you can't say why.","options":[{"text":"Tell a parent or call Tele-MANAS (14416) about it","consequence":"You get help understanding and easing it.","outcome":"supported","best":true},{"text":"Hide it and hope it stops","consequence":"A month of near-daily crying is worth telling someone."}],"debrief":"You needn't have a reason ready; how long it's lasted is reason enough.","relearn":"Weeks of low feelings deserve a trusted adult or Tele-MANAS (14416).","persona":"Counsellor","source":"persistent distress / help-seeking"},
  {"id":"bn-1085","cat":"reach-out","type":"branch","hook":"You want to talk to your school counsellor but worry it'll go on a record.","options":[{"text":"Ask how privacy works, then share what feels okay","consequence":"You learn it's safer than you feared and get support.","outcome":"informed","best":true},{"text":"Skip it to avoid the unknown","consequence":"Asking how it works lets you reach out without fear."}],"debrief":"You can ask about privacy first; the unknown shrinks once you ask.","relearn":"Unsure how help works? Ask first, then reach out; you're still in control.","persona":"Counsellor","source":"help-seeking / counsellor"},
  {"id":"bn-1086","cat":"reach-out","type":"branch","hook":"You feel you should fix this yourself before 'bothering' anyone.","options":[{"text":"Reach out now; getting help early is wise, not a bother","consequence":"You're supported before it gets harder.","outcome":"supported","best":true},{"text":"Struggle alone until you've 'tried everything'","consequence":"You're not a bother; reaching out early is the smart move."}],"debrief":"Asking early isn't bothering people; it's what people who care want.","relearn":"Reaching out early, not only at breaking point, is strength.","persona":"Veer","source":"de-stigmatise / help-seeking"},
  {"id":"bn-1087","cat":"reach-out","type":"branch","hook":"Online someone says 'real men handle their own head, never share feelings'.","options":[{"text":"Reject it; reaching out is one of the strongest moves","consequence":"You keep a real way through open for yourself.","outcome":"free","best":true},{"text":"Believe it and bottle it all up","consequence":"That 'tough it alone' line isn't strength; reaching out is."}],"debrief":"'Handle it alone or you're weak' is a myth that keeps people silent.","relearn":"Reaching out is strength, whatever 'be a man' messages say.","persona":"Veer","source":"de-stigmatise / masculinity script"},
  {"id":"bn-1088","cat":"reach-out","type":"branch","hook":"A helpline felt scary so you hung up before anyone answered.","options":[{"text":"Try again; you can say 'I'm nervous, I just need to talk'","consequence":"You connect with someone trained to make it easier.","outcome":"connected","best":true},{"text":"Decide helplines aren't for you","consequence":"Nervous is normal; trying again is okay."}],"debrief":"Hanging up once is fine; call back and name that you're nervous.","relearn":"Nervous to call? Helplines like Tele-MANAS (14416) are exactly for this.","persona":"any","source":"helpline / de-stigmatise"},
  {"id":"bn-1089","cat":"reach-out","type":"branch","hook":"Lately you think everyone would be better off without you.","options":[{"text":"Tell a trusted adult now, or call Tele-MANAS 14416 / Childline 1098","consequence":"You reach people who can help you stay safe.","outcome":"safe","best":true},{"text":"Keep the thought hidden","consequence":"This is a reach-out-now sign; tell someone today."}],"debrief":"'They'd be better off without me' is a thought to share with help.","relearn":"Thoughts you shouldn't be here mean reach out now: Tele-MANAS 14416, Childline 1098/112.","persona":"Counsellor","source":"crisis / routing"},
  {"id":"bn-1090","cat":"reach-out","type":"branch","hook":"Your parents say 'we don't believe in counsellors' and you need help.","options":[{"text":"Reach a trusted teacher, relative, or Tele-MANAS (14416)","consequence":"You find a route to help around the closed door.","outcome":"supported","best":true},{"text":"Give up because they said no","consequence":"One door closed isn't all of them; another adult can help."}],"debrief":"If one adult won't help, a teacher, relative, or helpline still can.","relearn":"If family can't help, a teacher, relative, or Tele-MANAS (14416) can.","persona":"any","source":"help-seeking / barriers (India)"},
  {"id":"bn-1091","cat":"reach-out","type":"branch","hook":"You've been so anxious you can't eat before school for two weeks.","options":[{"text":"Tell a trusted adult; two weeks of this needs support","consequence":"You get help easing the anxiety, not just carrying it.","outcome":"supported","best":true},{"text":"Force it down, say nothing","consequence":"Two weeks too anxious to eat is worth reaching out about."}],"debrief":"When anxiety hits your body for weeks, that's a sign to reach out.","relearn":"Anxiety affecting eating for weeks deserves an adult or Tele-MANAS (14416).","persona":"Riya","source":"persistent anxiety / help-seeking"},
  {"id":"bn-1092","cat":"reach-out","type":"role-play","hook":"You're finally telling your elder sister you've been struggling.","setup":"Say it plainly. Say:","yourLine":[{"text":"\"Didi, I've been really low lately and I think I need help.\"","best":true},{"text":"\"Nothing, I'm okay\" (when you're not)"}],"relearn":"Naming it to someone you trust is brave and it opens the way to help.","persona":"any","source":"help-seeking / family"},
  {"id":"bn-1093","cat":"reach-out","type":"role-play","hook":"You're about to call Tele-MANAS for the first time and freeze.","setup":"Start simple. Say:","yourLine":[{"text":"\"Hi, I'm not sure how to start, but I've been struggling and need to talk.\"","best":true},{"text":"\"Sorry, wrong number\" (and hang up)"}],"relearn":"You don't need the perfect words; 'I've been struggling' is enough to start.","persona":"any","source":"helpline / de-stigmatise"},
  {"id":"bn-1094","cat":"reach-out","type":"role-play","hook":"A teacher asks if everything's alright and you almost say 'fine'.","setup":"Be honest with someone who asked. Say:","yourLine":[{"text":"\"Actually, no. Could I talk to you about something after class?\"","best":true},{"text":"\"Yeah, all fine\" (when it isn't)"}],"relearn":"When a safe adult asks, 'actually, no' is a brave, worth-it answer.","persona":"any","source":"help-seeking / opening up"},
  {"id":"bn-1095","cat":"reach-out","type":"role-play","hook":"You want to ask a friend to come with you to tell an adult.","setup":"Ask for company. Say:","yourLine":[{"text":"\"This is hard to say alone. Would you come with me to tell someone?\"","best":true},{"text":"\"Forget it, I'll just deal with it myself.\""}],"relearn":"Asking someone to come with you makes reaching out far less scary.","persona":"any","source":"help-seeking / support"},
  {"id":"bn-1096","cat":"reach-out","type":"role-play","hook":"Your mind keeps saying 'asking for help means you're broken'.","setup":"Answer that voice. Say:","yourLine":[{"text":"\"Needing help is human, not broken. I'm allowed to reach out.\"","best":true},{"text":"\"I should be able to handle this alone.\""}],"relearn":"Reaching out is human and strong; needing help never means you're broken.","persona":"Veer","source":"de-stigmatise / self-talk"},
  {"id":"bn-1097","cat":"reach-out","type":"role-play","hook":"You messaged a helpline chat and they ask what's going on.","setup":"Tell them honestly. Say:","yourLine":[{"text":"\"I've been feeling low for a while and I don't want to feel this way.\"","best":true},{"text":"\"Never mind, it's not important.\""}],"relearn":"Being honest with a helpline lets them actually help you.","persona":"any","source":"helpline / honesty"},
  {"id":"bn-1098","cat":"reach-out","type":"role-play","hook":"You want to tell your coach you're not okay, not just tired.","setup":"Say the real thing. Say:","yourLine":[{"text":"\"It's not just tiredness, sir. I've been struggling and need some help.\"","best":true},{"text":"\"Just tired, I'll push through.\""}],"relearn":"Naming that it's more than tiredness gets you the right kind of help.","persona":"any","source":"help-seeking / honesty"},
  {"id":"bn-1099","cat":"reach-out","type":"role-play","hook":"You're encouraging yourself to keep trying after one adult didn't listen.","setup":"Steady yourself. Say:","yourLine":[{"text":"\"One person not hearing me doesn't mean no one will. I'll try again.\"","best":true},{"text":"\"No one will ever listen, so why bother.\""}],"relearn":"If one person misses it, you can keep going; someone will hear you.","persona":"any","source":"help-seeking / persistence"},
  {"id":"bn-1100","cat":"reach-out","type":"role-play","hook":"A relative says 'just pray, you don't need any helpline'.","setup":"Hold your ground kindly. Say:","yourLine":[{"text":"\"I'll do that too, but I'd really like to talk to someone trained as well.\"","best":true},{"text":"\"Okay, I won't ask for help then.\""}],"relearn":"You can honour your family and still reach out for real, trained support.","persona":"any","source":"help-seeking / barriers (India)"},
  {"id":"bn-1101","cat":"reach-out","type":"role-play","hook":"You're scared a counsellor will tell your parents everything.","setup":"Ask before you decide. Say:","yourLine":[{"text":"\"Before I share, can you tell me what stays private and what doesn't?\"","best":true},{"text":"Say nothing and walk away"}],"relearn":"You can ask how privacy works first, then reach out feeling safer.","persona":"Counsellor","source":"help-seeking / privacy"},
  {"id":"bn-1102","cat":"reach-out","type":"role-play","hook":"You finally admit out loud that you can't carry this alone.","setup":"Let it be true. Say:","yourLine":[{"text":"\"I can't do this on my own anymore, and that's okay. I need help.\"","best":true},{"text":"\"I have to be strong and figure it out alone.\""}],"relearn":"Admitting you can't carry it alone is honest and the first step to help.","persona":"any","source":"help-seeking / limits"},
  {"id":"bn-1103","cat":"reach-out","type":"role-play","hook":"Your friend reached out and now you're cheering yourself on to do the same.","setup":"Give yourself the push. Say:","yourLine":[{"text":"\"If reaching out was right for them, it's right for me too.\"","best":true},{"text":"\"They're different; my stuff doesn't count.\""}],"relearn":"What you'd call brave in a friend is brave in you too; reach out.","persona":"any","source":"help-seeking / self-compassion"},
  {"id":"bn-1104","cat":"reach-out","type":"strike-rewrite","hook":"\"If I reach out, I'm just dumping my problems on someone else.\"","myth":{"un":"Reaching out means dumping my problems on people.","re":"People who care want to know; sharing isn't a burden.","why":"Carrying it alone is heavier than letting someone help."},"relearn":"Sharing with people who care isn't a burden; it's what they want.","persona":"any","source":"de-stigmatise / burden myth"},
  {"id":"bn-1105","cat":"reach-out","type":"strike-rewrite","hook":"\"Helplines are only for people who are about to do something drastic.\"","myth":{"un":"Helplines are only for people in extreme crisis.","re":"Helplines are for any time you're struggling, not just emergencies.","why":"You don't have to be at the edge to call and be helped."},"relearn":"Helplines are for any struggle, not only emergencies; calling is okay.","persona":"any","source":"help-seeking / de-stigmatise"},
  {"id":"bn-1106","cat":"reach-out","type":"strike-rewrite","hook":"\"If I just wait long enough, this low feeling will fix itself.\"","myth":{"un":"If I wait long enough, it'll fix itself.","re":"Some low feelings lift with time; weeks of them need real support.","why":"Lasting low mood usually eases faster with help, not just waiting."},"relearn":"Weeks of low feelings need support, not just more waiting.","persona":"any","source":"persistent low mood"},
  {"id":"bn-1107","cat":"reach-out","type":"strike-rewrite","hook":"\"Reaching out once and being ignored proves no one cares.\"","myth":{"un":"If one person ignores me, no one cares.","re":"One person missing it isn't everyone; the next may truly hear you.","why":"Plenty of people will care; you just haven't reached the right one yet."},"relearn":"One brush-off isn't proof no one cares; keep reaching out.","persona":"any","source":"help-seeking / persistence"},
  {"id":"bn-1108","cat":"reach-out","type":"strike-rewrite","hook":"\"Strong people deal with mental stuff completely on their own.\"","myth":{"un":"Strong people handle mental struggles entirely alone.","re":"Even the strongest people lean on others; that's how they stay strong.","why":"Reaching out is a sign of strength, not a crack in it."},"relearn":"Strength includes leaning on people; no one is meant to cope alone.","persona":"Veer","source":"de-stigmatise / strength myth"},
  {"id":"bn-1109","cat":"reach-out","type":"strike-rewrite","hook":"\"Talking about dark thoughts will only make them worse.\"","myth":{"un":"Saying dark thoughts out loud makes them worse.","re":"Sharing dark thoughts with help eases them; silence makes them heavier.","why":"Trained people know how to help carry that, so you're not alone with it."},"relearn":"Telling someone about dark thoughts helps; it doesn't make them worse.","persona":"Counsellor","source":"crisis / de-stigmatise"},
  {"id":"bn-1110","cat":"reach-out","type":"strike-rewrite","hook":"\"Asking for help is admitting I failed at handling my life.\"","myth":{"un":"Asking for help means I failed at life.","re":"Everyone needs help sometimes; asking is a normal life skill.","why":"Knowing when to reach out is something capable people do."},"relearn":"Asking for help is a skill, not a failure; everyone needs it sometimes.","persona":"any","source":"de-stigmatise / failure myth"},
  {"id":"bn-1111","cat":"reach-out","type":"strike-rewrite","hook":"\"A counsellor will just judge me for what I'm feeling.\"","myth":{"un":"A counsellor will judge me for my feelings.","re":"Counsellors are trained to listen without judging, whatever you feel.","why":"Their whole role is to help, not to grade your feelings."},"relearn":"Counsellors are there to listen, not judge; it's safe to be real.","persona":"any","source":"help-seeking / de-stigmatise"},
  {"id":"bn-1112","cat":"reach-out","type":"strike-rewrite","hook":"\"Reaching out is pointless because nothing can actually change.\"","myth":{"un":"Reaching out is pointless; nothing changes.","re":"Reaching out really does help, with the feeling and the next steps.","why":"Support is literally what trained people are there to give."},"relearn":"Reaching out genuinely helps; it isn't pointless.","persona":"any","source":"help efficacy / hope"},
  {"id":"bn-1113","cat":"reach-out","type":"reflect","hook":"Lensy: name two adults you could go to if things ever felt too heavy.","prompt":"Think of two.","options":["A parent and a teacher","An aunt and a coach","A sibling and a counsellor","Any two I trust"],"affirm":"Two safe people means if one's away or busy, you still have someone.","relearn":"Knowing more than one safe adult means help is always within reach.","persona":"any","source":"safety planning"},
  {"id":"bn-1114","cat":"reach-out","type":"reflect","hook":"Lensy: 'I need help' is one of the bravest sentences there is. Sit right with you?","prompt":"What do you think?","options":["Yes","It is brave","I can say it"],"affirm":"Saying 'I need help' takes real courage, and it works.","relearn":"Asking for help is brave, not weak.","persona":"any","source":"de-stigmatise"},
  {"id":"bn-1114b","cat":"reach-out","type":"reflect","hook":"Lensy: which way to reach out feels most doable for you right now?","prompt":"Pick what fits you.","options":["Talk to an adult I trust","Message a helpline chat","Call Tele-MANAS 14416","Go with a friend"],"affirm":"Any of these counts; the one you'd actually use is the right one.","relearn":"There are many ways to reach out; pick the one you'd actually use.","persona":"any","source":"help-seeking / readiness"},
  {"id":"bn-1115","cat":"reach-out","type":"reflect","hook":"Lensy: you don't have to wait for a crisis to ask for support. Hold onto that?","prompt":"What do you think?","options":["Yes","I can ask early","Good to know"],"affirm":"Asking early, before things pile up, is wise and allowed.","relearn":"You can reach out any time, not only when things hit crisis.","persona":"any","source":"help-seeking"},
  {"id":"bn-1116","cat":"reach-out","type":"reflect","hook":"Lensy: think of a time telling someone made a heavy thing feel lighter.","prompt":"Recall one.","options":["When I told a friend","When I told family","When a teacher listened"],"affirm":"That lightness is proof that sharing the weight really helps.","relearn":"Telling someone often makes a heavy thing feel lighter.","persona":"any","source":"help efficacy"},
  {"id":"bn-1117","cat":"reach-out","type":"reflect","hook":"Lensy: reaching out doesn't make you a burden; it lets people show they care. Agree?","prompt":"What do you think?","options":["Yes","I'm not a burden","That helps"],"affirm":"Letting people care for you is a gift to them, not a weight.","relearn":"Reaching out isn't a burden; it lets people who care show up for you.","persona":"any","source":"de-stigmatise / burden myth"},
  {"id":"bn-1118","cat":"reach-out","type":"reflect","hook":"Lensy: if a friend felt how you feel, you'd tell them to reach out. Same for you?","prompt":"What do you think?","options":["Yes","I deserve it too","I'll do it"],"affirm":"The care you'd give a friend, you deserve to give yourself.","relearn":"You deserve the same reaching-out you'd urge on a friend.","persona":"any","source":"self-compassion / help-seeking"},
  {"id":"bn-1119","cat":"reach-out","type":"reflect","hook":"Lensy: knowing the Tele-MANAS number means help is always one call away. Reassuring?","prompt":"What do you think?","options":["Yes","One call away","I'll remember 14416"],"affirm":"Tele-MANAS 14416 is always there; that's a steadying thing to carry.","relearn":"Tele-MANAS 14416 is always reachable; help is one call away.","persona":"any","source":"safety planning / Tele-MANAS"},
  {"id":"bn-1120","cat":"reach-out","type":"reflect","hook":"Lensy: resilience has limits, and knowing yours is wisdom, not weakness. True for you?","prompt":"What do you think?","options":["Yes","Limits are okay","Knowing mine is smart"],"affirm":"Knowing when you've hit your limit and reaching out is real wisdom.","relearn":"Resilience has limits; knowing yours and reaching out is wisdom.","persona":"any","source":"limits / self-awareness"},
  {"id":"bn-1121","cat":"reach-out","type":"reflect","hook":"Lensy: what's one small first step toward reaching out you could take this week?","prompt":"Pick one.","options":["Text one trusted person","Save a helpline number","Tell a friend I'm struggling","Book time with a counsellor"],"affirm":"One small step is a real start; you don't have to do it all at once.","relearn":"Reaching out can start with one small step, not a giant leap.","persona":"any","source":"help-seeking / small steps"},
  {"id":"bn-1122","cat":"reach-out","type":"reflect","hook":"Lensy: 'I don't have to be okay all the time' is a relief, not a defeat. Feel that?","prompt":"What do you think?","options":["Yes","It's a relief","I can let go"],"affirm":"Letting yourself not be okay is honest, and it's where help begins.","relearn":"You don't have to be okay all the time; saying so opens the door to help.","persona":"any","source":"normalising"},
  {"id":"bn-1123","cat":"reach-out","type":"sort","hook":"Sort: a 'reach out NOW' sign, or an ordinary rough patch?","items":[{"id":"a","text":"Thoughts of not wanting to be here"},{"id":"b","text":"Nervous before one big match"},{"id":"c","text":"Weeks of not eating or sleeping"},{"id":"d","text":"Bummed about a lost game today"},{"id":"e","text":"Feeling everyone's better off without you"},{"id":"f","text":"A sad evening that lifts by morning"}],"bins":[{"id":"now","label":"Reach out now","valence":"tell"},{"id":"ordinary","label":"Ordinary rough patch","valence":"neutral"}],"key":{"a":"now","b":"ordinary","c":"now","d":"ordinary","e":"now","f":"ordinary"},"relearn":"Dark thoughts or weeks of not eating/sleeping mean reach out now.","persona":"Counsellor","source":"safeguarding / signs"},
  {"id":"bn-1124","cat":"reach-out","type":"sort","hook":"Sort: real help when it's heavy, or not actually help?","items":[{"id":"a","text":"A trusted adult who listens"},{"id":"b","text":"\"Just toughen up, na\""},{"id":"c","text":"Tele-MANAS (14416)"},{"id":"d","text":"Bottling it up to seem strong"},{"id":"e","text":"Childline (1098 / 112)"},{"id":"f","text":"A school counsellor"}],"bins":[{"id":"help","label":"Real help","valence":"pos"},{"id":"no","label":"Not help","valence":"neg"}],"key":{"a":"help","b":"no","c":"help","d":"no","e":"help","f":"help"},"relearn":"Trusted adults, counsellors and helplines (Tele-MANAS 14416, Childline 1098) are real help; 'toughen up' and bottling up are not.","persona":"any","source":"help routes (India)"},
  {"id":"bn-1125","cat":"reach-out","type":"sort","hook":"Sort: reaching out, or staying stuck alone?","items":[{"id":"a","text":"Texting a friend 'I'm not okay'"},{"id":"b","text":"Hiding it behind 'I'm fine'"},{"id":"c","text":"Calling a helpline"},{"id":"d","text":"Isolating in your room for days"},{"id":"e","text":"Telling a teacher you trust"},{"id":"f","text":"Pretending nothing's wrong"}],"bins":[{"id":"out","label":"Reaching out","valence":"tell"},{"id":"stuck","label":"Stuck alone","valence":"uhoh"}],"key":{"a":"out","b":"stuck","c":"out","d":"stuck","e":"out","f":"stuck"},"relearn":"Reaching out means telling someone real; hiding behind 'I'm fine' keeps you stuck.","persona":"any","source":"help-seeking / behaviours"},
  {"id":"bn-1126","cat":"reach-out","type":"sort","hook":"Sort: true about asking for help, or a myth that holds people back?","items":[{"id":"a","text":"Asking for help is strong"},{"id":"b","text":"Needing help means you're broken"},{"id":"c","text":"You can ask before a crisis"},{"id":"d","text":"Helplines are only for emergencies"},{"id":"e","text":"One brush-off, you try again"},{"id":"f","text":"Strong people never need anyone"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Asking for help is strong and not just for crises; 'broken' and 'never need anyone' are myths.","persona":"any","source":"de-stigmatise"},
  {"id":"bn-1127","cat":"reach-out","type":"sort","hook":"Sort: a feeling that usually passes, or one to reach out about?","items":[{"id":"a","text":"Nerves the night before exams"},{"id":"b","text":"Low and empty for a month"},{"id":"c","text":"Sad after a fight, okay next day"},{"id":"d","text":"No joy in anything for weeks"},{"id":"e","text":"Down about one bad mark"},{"id":"f","text":"Wishing you weren't around"}],"bins":[{"id":"passes","label":"Usually passes","valence":"neutral"},{"id":"reach","label":"Reach out about it","valence":"tell"}],"key":{"a":"passes","b":"reach","c":"passes","d":"reach","e":"passes","f":"reach"},"relearn":"Brief nerves and one-day sadness pass; weeks of emptiness or 'wishing I weren't here' mean reach out.","persona":"Counsellor","source":"signs / safeguarding"},
  {"id":"bn-1128","cat":"reach-out","type":"sort","hook":"Sort: who or what is a safe route to help, or not the right place for this?","items":[{"id":"a","text":"A trusted teacher"},{"id":"b","text":"Anonymous strangers online"},{"id":"c","text":"A school counsellor"},{"id":"d","text":"A relative you trust"},{"id":"e","text":"A helpline like Tele-MANAS (14416)"},{"id":"f","text":"Keeping it only in your diary"}],"bins":[{"id":"safe","label":"Safe route to help","valence":"pos"},{"id":"not","label":"Not the right place","valence":"neg"}],"key":{"a":"safe","b":"not","c":"safe","d":"safe","e":"safe","f":"not"},"relearn":"Trusted adults, counsellors and helplines are safe routes; strangers or just a diary aren't enough when it's heavy.","persona":"any","source":"help routes"},
  {"id":"bn-1129","cat":"reach-out","type":"match","hook":"Match the worry about reaching out to the steadier truth.","pairs":[{"left":"\"I'll be a burden\"","right":"People who care want to know"},{"left":"\"I'm not bad enough\"","right":"You don't have to earn help"},{"left":"\"Asking means I'm weak\"","right":"Reaching out is real strength"},{"left":"\"No one will listen\"","right":"Keep going; someone will"},{"left":"\"It can't get better\"","right":"Support genuinely helps"}],"relearn":"Each worry about reaching out has a truer, steadier reply.","persona":"any","source":"de-stigmatise / reframing"},
  {"id":"bn-1130","cat":"reach-out","type":"match","hook":"Match the situation to the right place to reach out.","pairs":[{"left":"Thoughts that scare you now","right":"A trusted adult, right away"},{"left":"Family won't engage","right":"A teacher or counsellor"},{"left":"Want to talk anonymously","right":"Tele-MANAS 14416"},{"left":"Need someone to come along","right":"A friend you trust"},{"left":"Unsure how serious it is","right":"Ask, then reach out anyway"}],"relearn":"Different needs have different good routes to reaching out.","persona":"any","source":"help routing"},
  {"id":"bn-1131","cat":"reach-out","type":"match","hook":"Match the brush-off you might hear to a stronger reply.","pairs":[{"left":"\"You'll be fine\"","right":"\"I'd still like to talk it through\""},{"left":"\"Everyone feels this\"","right":"\"Mine's lasted weeks, though\""},{"left":"\"Don't be dramatic\"","right":"\"This is real for me\""},{"left":"\"We don't do counsellors\"","right":"\"Then can I talk to someone else?\""},{"left":"\"Just be busy\"","right":"\"I've tried; I still need help\""}],"relearn":"When you're brushed off, a calm, clear reply keeps the door to help open.","persona":"any","source":"help-seeking / persistence"},
  {"id":"bn-1132","cat":"reach-out","type":"match","hook":"Match the helpline or person to what they're for.","pairs":[{"left":"Tele-MANAS 14416","right":"Mental-health support line"},{"left":"Childline 1098","right":"Help for children in distress"},{"left":"A school counsellor","right":"Someone at school to talk to"},{"left":"A trusted adult","right":"Day-to-day support and routing"},{"left":"A close friend","right":"Going with you to get help"}],"relearn":"Knowing what each route is for makes reaching out easier.","persona":"any","source":"help routes (India)"},
  {"id":"bn-1133","cat":"reach-out","type":"match","hook":"Match the brave action to why it matters.","pairs":[{"left":"Saying 'I need help'","right":"Lets someone actually help you"},{"left":"Asking early","right":"Catches it before it grows"},{"left":"Trying a second adult","right":"One miss isn't the end"},{"left":"Naming a dark thought","right":"Gets you safe support now"},{"left":"Bringing a friend along","right":"Makes it less scary"}],"relearn":"Each step of reaching out has a real reason it helps.","persona":"any","source":"help-seeking"},
  {"id":"bn-1134","cat":"reach-out","type":"match","hook":"Match the unhelpful self-talk to a kinder, truer line.","pairs":[{"left":"\"I should cope alone\"","right":"\"No one is meant to cope alone\""},{"left":"\"It's too small to mention\"","right":"\"Any struggle is allowed to count\""},{"left":"\"I'll bother them\"","right":"\"People who care want to know\""},{"left":"\"Help won't work\"","right":"\"Trained support really does help\""},{"left":"\"I'm weak for needing this\"","right":"\"Reaching out is strength\""}],"relearn":"Kinder self-talk makes it easier to reach out when you need to.","persona":"any","source":"de-stigmatise / self-talk"},
  {"id":"bn-1135","cat":"reach-out","type":"match","hook":"Match the early sign to the gentle move it calls for.","pairs":[{"left":"Low for several weeks","right":"Tell an adult or Tele-MANAS 14416"},{"left":"Pulling away from everyone","right":"Reach out to one safe person"},{"left":"Thoughts that scare you","right":"Get a trusted adult right now"},{"left":"Can't sleep or eat for weeks","right":"Talk to a trusted adult"},{"left":"Not sure it's 'enough'","right":"Reach out anyway"}],"relearn":"Each early sign has a clear, gentle next move toward help.","persona":"Counsellor","source":"signs / routing"},
  {"id":"bn-1136","cat":"reach-out","type":"match","hook":"Match what reaching out is, to what it isn't.","pairs":[{"left":"A sign of strength","right":"Not a sign of weakness"},{"left":"A normal life skill","right":"Not a personal failure"},{"left":"For any struggle","right":"Not only for emergencies"},{"left":"Letting people care","right":"Not being a burden"},{"left":"The start of getting better","right":"Not the end of coping"}],"relearn":"Reaching out is strength and a life skill, not weakness or a burden.","persona":"any","source":"de-stigmatise"},
  {"id":"bn-1137","cat":"reach-out","type":"build","hook":"Build a simple reach-out plan for when things feel too heavy.","prompt":"Order the steps to actually get help.","pieces":["notice you're not coping","pick one safe person or helpline","say plainly 'I need help'","if not heard, tell someone else"],"mode":"sequence","key":["notice you're not coping","pick one safe person or helpline","say plainly 'I need help'","if not heard, tell someone else"],"relearn":"Reach out by noticing, picking a safe route, saying it plainly, and trying again if needed.","persona":"any","source":"help-seeking / plan"},
  {"id":"bn-1138","cat":"reach-out","type":"build","hook":"Build your personal 'safe people and numbers' list.","prompt":"Assemble who and what you'd reach for.","pieces":["a trusted adult at home","a teacher or counsellor","Tele-MANAS 14416","Childline 1098 / 112"],"mode":"assemble","key":["a trusted adult at home","a teacher or counsellor","Tele-MANAS 14416","Childline 1098 / 112"],"relearn":"A ready list of safe people and helplines means help is always within reach.","persona":"any","source":"safety planning"},
  {"id":"bn-1139","cat":"reach-out","type":"build","hook":"Build a first message to send when you're ready to reach out.","prompt":"Assemble an honest, simple message.","pieces":["\"Hey, can we talk?\"","\"I've been struggling lately\"","\"It's more than a bad day\"","\"I think I need some help\""],"mode":"assemble","key":["\"Hey, can we talk?\"","\"I've been struggling lately\"","\"It's more than a bad day\"","\"I think I need some help\""],"relearn":"A simple, honest message is all it takes to open the door to help.","persona":"any","source":"help-seeking / scripts"},
  {"id":"bn-1140","cat":"reach-out","type":"build","hook":"Build the steps for calling a helpline when you're nervous.","prompt":"Order the steps to make the call easier.","pieces":["find a quiet, private spot","take a few slow breaths","dial Tele-MANAS 14416","say 'I'm nervous, but I need to talk'"],"mode":"sequence","key":["find a quiet, private spot","take a few slow breaths","dial Tele-MANAS 14416","say 'I'm nervous, but I need to talk'"],"relearn":"You can make a helpline call easier with a quiet spot, a breath, and an honest first line.","persona":"any","source":"helpline / steps"},
  {"id":"bn-1141","cat":"reach-out","type":"build","hook":"Build a plan for when the first adult you tell doesn't really hear you.","prompt":"Order what to do next.","pieces":["remind yourself one miss isn't the end","choose a different trusted adult","tell them clearly what's wrong","or call a helpline if you're stuck"],"mode":"sequence","key":["remind yourself one miss isn't the end","choose a different trusted adult","tell them clearly what's wrong","or call a helpline if you're stuck"],"relearn":"If one adult misses it, pick another and keep going; a helpline is always there.","persona":"any","source":"help-seeking / persistence"},
  {"id":"bn-1142","cat":"reach-out","type":"build","hook":"Build a kit of reasons reaching out is worth it, for the doubtful days.","prompt":"Assemble true reasons to reach out.","pieces":["sharing makes the weight lighter","people who care want to know","trained help really does work","I don't have to do this alone"],"mode":"assemble","key":["sharing makes the weight lighter","people who care want to know","trained help really does work","I don't have to do this alone"],"relearn":"Reaching out lightens the weight, and trained help genuinely works; you're not alone.","persona":"any","source":"help efficacy / motivation"},
  {"id":"bn-1143","cat":"reach-out","type":"build","hook":"Build the steps for helping yourself in a scary-thoughts moment.","prompt":"Order the safest steps right now.","pieces":["tell yourself you're not alone in this","reach a trusted adult straight away","or call Tele-MANAS 14416 / Childline 1098","stay with someone until it eases"],"mode":"sequence","key":["tell yourself you're not alone in this","reach a trusted adult straight away","or call Tele-MANAS 14416 / Childline 1098","stay with someone until it eases"],"relearn":"In a scary-thoughts moment: you're not alone; reach an adult or helpline now and stay with someone.","persona":"Counsellor","source":"crisis / steps"},
  {"id":"bn-1144","cat":"reach-out","type":"build","hook":"Build a short script to ask a friend to come with you for support.","prompt":"Assemble a kind, clear ask.","pieces":["\"I've been struggling lately\"","\"I want to tell an adult\"","\"but it's hard to do alone\"","\"would you come with me?\""],"mode":"assemble","key":["\"I've been struggling lately\"","\"I want to tell an adult\"","\"but it's hard to do alone\"","\"would you come with me?\""],"relearn":"Asking a friend to come along can turn a scary step into a doable one.","persona":"any","source":"help-seeking / support"},
  {"id":"bn-1145","cat":"reach-out","type":"reflect","hook":"Lensy: reaching out today is a kindness to the you of next week. Like that thought?","prompt":"What do you think?","options":["Yes","Future-me says thanks","I'll do it for me"],"affirm":"A small reach-out now can save future-you a much heavier week.","relearn":"Reaching out now is a kindness to your future self.","persona":"any","source":"help-seeking / motivation"},
  {"id":"bn-1170","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I scored low, so I'm a weak student.\"","myth":{"un":"A low score means I'm a weak student, full stop.","re":"A low score is one result, not a label on who you are.","why":"A number on a paper can't sum up a whole person."},"relearn":"A low mark is an event, not a verdict on you as a person.","persona":"Riya","source":"failure as event"},
  {"id":"bn-1171","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I couldn't solve those sums, so maths just isn't for me.\"","myth":{"un":"I can't do these sums, so maths isn't for me.","re":"You can't do them yet; the right practice can change that.","why":"'Yet' turns a dead end into a next step."},"relearn":"'Maths isn't for me' becomes 'not yet' with practice.","persona":"any","source":"growth mindset ('not yet')"},
  {"id":"bn-1172","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I froze on stage at the function; everyone will remember it.\"","myth":{"un":"I froze on stage, so everyone will remember it forever.","re":"People are busy with themselves; this fades fast for them.","why":"We notice our own slips far more than others do."},"relearn":"A public stumble fades from others' minds far faster than from yours.","persona":"Riya","source":"spotlight effect"},
  {"id":"bn-1173","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I missed the cut-off for the course I wanted; my future is finished.\"","myth":{"un":"I missed the cut-off, so my future is finished.","re":"One cut-off closes one door; many other paths stay open.","why":"Lives rarely turn on a single admission list."},"relearn":"Missing one cut-off doesn't decide your whole future.","persona":"Veer","source":"reframe / many paths"},
  {"id":"bn-1174","cat":"reframe-setback","type":"strike-rewrite","hook":"\"My re-test went badly too, so I'll never get this.\"","myth":{"un":"My re-test went badly too, so I'll never get this.","re":"Two hard tries is a slow start, not a permanent verdict.","why":"Skills build over many tries, not just two."},"relearn":"A couple of rough attempts is a slow start, not 'never'.","persona":"any","source":"setbacks not permanent"},
  {"id":"bn-1175","cat":"reframe-setback","type":"strike-rewrite","hook":"\"My friend topped and I didn't, so I'm just less capable.\"","myth":{"un":"A friend topped and I didn't, so I'm less capable.","re":"You ran a different race on a different day, not a lesser one.","why":"Comparison hides your own real progress."},"relearn":"Someone else's result isn't a measure of your worth.","persona":"Riya","source":"comparison / reframe"},
  {"id":"bn-1176","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I lost the match for my team, so I let everyone down for good.\"","myth":{"un":"I lost the match, so I've let everyone down for good.","re":"One match is one game; teammates remember the whole season.","why":"No single game defines a player to their team."},"relearn":"One bad game is a moment, not how your team sees you.","persona":"Veer","source":"failure as event"},
  {"id":"bn-1177","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I have to feel fine about it, or I'm not really moving on.\"","myth":{"un":"If I still feel bad, I haven't really moved on.","re":"You can feel the sting and still be moving forward.","why":"Healing isn't the same as suddenly feeling nothing."},"relearn":"Moving on can hold the hurt and the next step at once.","persona":"any","source":"reframing vs denial"},
  {"id":"bn-1178","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I made a silly error in the paper; the whole effort was wasted.\"","myth":{"un":"I made a silly error, so all that effort was wasted.","re":"That error shows exactly what to check next time, not waste.","why":"A clear mistake is the cheapest lesson you'll get."},"relearn":"A mistake points to your next fix; it isn't wasted effort.","persona":"any","source":"failure as learning"},
  {"id":"bn-1179","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I got rejected from the debate team, so I'm just not good enough.\"","myth":{"un":"I got rejected, so I'm just not good enough.","re":"A 'no' this time is feedback, not a final score on you.","why":"Selections turn on fit and timing, not just worth."},"relearn":"A 'no' is feedback for next time, not a verdict on you.","persona":"any","source":"reframe / rejection"},
  {"id":"bn-1180","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I cried after the result; that means I'm weak.\"","myth":{"un":"I cried after the result, so I'm weak.","re":"Feeling it fully is how you process it, not weakness.","why":"Letting the feeling move through is real strength."},"relearn":"Feeling a setback deeply is processing it, not weakness.","persona":"Veer","source":"feel-then-move"},
  {"id":"bn-1181","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I dropped a rank this term, so I'm slipping downhill for good.\"","myth":{"un":"I dropped a rank, so I'm slipping downhill for good.","re":"One dip is a data point on a long, bumpy line.","why":"Progress almost never goes up in a straight line."},"relearn":"One dip in results is a bump, not a downhill slide.","persona":"Riya","source":"setbacks not permanent"},
  {"id":"bn-1182","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I asked a 'dumb' question in class and everyone laughed.\"","myth":{"un":"I asked a dumb question, so I should never speak up again.","re":"That question helped you learn; classmates forget by lunch.","why":"The brief laugh fades; what you understood stays."},"relearn":"A question that got a laugh still helped you learn.","persona":"any","source":"spotlight effect"},
  {"id":"bn-1183","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I had to repeat a year; I'm permanently behind everyone.\"","myth":{"un":"I repeated a year, so I'm permanently behind everyone.","re":"You're on a slightly different timeline, not a worse life.","why":"Timelines vary; the finish line isn't a race against peers."},"relearn":"A different timeline isn't the same as being 'behind for life'.","persona":"any","source":"many paths forward"},
  {"id":"bn-1184","cat":"reframe-setback","type":"strike-rewrite","hook":"\"My science project flopped at the fair, so I'm bad at science.\"","myth":{"un":"My project flopped, so I'm bad at science.","re":"A flopped project tested an idea; that IS doing science.","why":"Science runs on experiments that don't work out."},"relearn":"A flopped experiment is science working, not you failing.","persona":"any","source":"failure as learning"},
  {"id":"bn-1185","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I quit the coaching class halfway; I always give up.\"","myth":{"un":"I quit halfway, so I always give up on everything.","re":"One thing you stopped isn't a rule about all of you.","why":"'Always' and 'never' are traps the spiral tells you."},"relearn":"Stopping one thing isn't proof you 'always give up'.","persona":"any","source":"reframe / all-or-nothing"},
  {"id":"bn-1186","cat":"reframe-setback","type":"strike-rewrite","hook":"\"Reframing is just lying to myself that it's fine.\"","myth":{"un":"Reframing is just telling myself a lie that it's fine.","re":"Honest reframing names the hurt AND the way forward.","why":"It adds a true second half; it doesn't erase the first."},"relearn":"Reframing isn't lying; it holds the hurt and the hope together.","persona":"any","source":"reframing vs denial"},
  {"id":"bn-1187","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I forgot my lines in the play, so I ruined the whole show.\"","myth":{"un":"I forgot my lines, so I ruined the whole show.","re":"One slip is a moment the audience barely clocks.","why":"People watch the story, not hunt for your mistakes."},"relearn":"One slip on stage isn't 'ruining' the whole show.","persona":"Riya","source":"spotlight effect"},
  {"id":"bn-1188","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I failed my first attempt at this, so trying again is pointless.\"","myth":{"un":"I failed my first attempt, so trying again is pointless.","re":"A first-attempt fail is normal; most pass on a later try.","why":"First tries teach you what the next one needs."},"relearn":"Failing a first attempt is common; the next try can change it.","persona":"any","source":"setbacks not permanent"},
  {"id":"bn-1189","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I bombed the interview, so I'm just not interview material.\"","myth":{"un":"I bombed the interview, so I'm not interview material.","re":"One nervous interview is a skill to practise, not your ceiling.","why":"Interviews are a learnable skill, not a fixed trait."},"relearn":"A rough interview is a skill to build, not a verdict on you.","persona":"Veer","source":"growth mindset"},
  {"id":"bn-1190","cat":"reframe-setback","type":"strike-rewrite","hook":"\"Everyone in the group chat saw my low marks; I can't recover.\"","myth":{"un":"Everyone saw my low marks online, so I can't recover.","re":"The chat moves on in hours; your story isn't one screenshot.","why":"Group chats forget yesterday's news fast."},"relearn":"A result that got seen online still fades fast for everyone else.","persona":"Riya","source":"spotlight effect"},
  {"id":"bn-1191","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I changed streams after a bad year; people will think I failed.\"","myth":{"un":"I changed streams, so people will always think I failed.","re":"Changing direction is choosing a better fit, not failing.","why":"A path that fits you beats a 'right' one that doesn't."},"relearn":"Switching to a better-fit path is a choice, not a failure.","persona":"any","source":"many paths forward"},
  {"id":"bn-1192","cat":"reframe-setback","type":"strike-rewrite","hook":"\"I keep practising and still mess up, so practice doesn't work for me.\"","myth":{"un":"I practise and still mess up, so practice doesn't work for me.","re":"Messing up less over time IS practice working, slowly.","why":"Growth shows up as fewer, smaller slips, not zero."},"relearn":"Practice working looks like smaller slips, not instant perfection.","persona":"any","source":"growth mindset"},
  {"id":"bn-1193","cat":"reframe-setback","type":"branch","hook":"You bombed a unit test you studied hard for.","options":[{"text":"Let yourself be gutted, then check which topics tripped you","consequence":"You feel it, learn the gaps, and come back sharper.","outcome":"resilient","best":true},{"text":"Decide you're hopeless and stop revising","consequence":"Feel the sting, then treat the paper as data; you're not hopeless."}],"debrief":"Feel the disappointment, then mine the paper for what to fix.","relearn":"Feel the setback, then turn the test into a study map.","persona":"Veer","source":"bounce-back"},
  {"id":"bn-1194","cat":"reframe-setback","type":"branch","hook":"You didn't get the lead role you auditioned for.","options":[{"text":"Feel the let-down, then ask the teacher what to build on","consequence":"You stay open and get a real next step.","outcome":"open","best":true},{"text":"Swear off auditions forever","consequence":"A 'no' can sharpen you; staying in keeps the door open."}],"debrief":"A role you didn't get can point you to what to grow next.","relearn":"A 'no' can guide your next try; stay in the game.","persona":"Riya","source":"reframe / rejection"},
  {"id":"bn-1195","cat":"reframe-setback","type":"branch","hook":"Your board prelim result was far below what you hoped.","options":[{"text":"Sit with it, then make a topic-by-topic plan for the boards","consequence":"The prelim becomes a map, not a verdict.","outcome":"planning","best":true},{"text":"Conclude the boards are already lost","consequence":"A prelim is practice; let it guide the real exam, not end it."}],"debrief":"A prelim shows where to aim before the real exam, not your fate.","relearn":"A weak prelim is a practice run to learn from, not a final result.","persona":"Riya","source":"exam pressure / reframe"},
  {"id":"bn-1196","cat":"reframe-setback","type":"branch","hook":"You keep replaying one embarrassing moment from assembly.","options":[{"text":"Name what you'd do differently, then shift to something now","consequence":"You break the loop and free your mind.","outcome":"unstuck","best":true},{"text":"Replay it on a loop all evening","consequence":"Pull one lesson, then redirect; looping only stings more."}],"debrief":"Take the lesson once, then deliberately put the replay down.","relearn":"Extract the lesson, then choose to stop the replay.","persona":"any","source":"rumination"},
  {"id":"bn-1197","cat":"reframe-setback","type":"branch","hook":"A relative compares your marks to your cousin's at dinner.","options":[{"text":"Hold your worth, focus on your own progress this term","consequence":"You stay steady instead of spiralling.","outcome":"grounded","best":true},{"text":"Take it as proof you're the family failure","consequence":"Their comparison isn't your verdict; run your own race."}],"debrief":"Comparison stings, but your progress is yours, not theirs.","relearn":"Step out of comparison; your own progress is the real measure.","persona":"Veer","source":"comparison / reframe"},
  {"id":"bn-1198","cat":"reframe-setback","type":"branch","hook":"You failed your part of a group project and feel you sank everyone.","options":[{"text":"Own it honestly, then offer to redo your section","consequence":"You repair it and learn, instead of hiding.","outcome":"repairing","best":true},{"text":"Avoid the group and hope nobody notices","consequence":"Owning a slip and fixing it beats hiding from it."}],"debrief":"A slip you own and repair becomes growth, not shame.","relearn":"Owning a mistake and fixing it turns it into a lesson.","persona":"any","source":"bounce-back / accountability"},
  {"id":"bn-1199","cat":"reframe-setback","type":"branch","hook":"You got cut from the school team in the first round.","options":[{"text":"Feel the disappointment, then ask the coach what to train","consequence":"You turn the cut into a clear training goal.","outcome":"growth","best":true},{"text":"Tell yourself you're just not sporty and quit","consequence":"A cut is feedback to train on, not proof you can't play."}],"debrief":"Being cut can show you exactly what to build for next time.","relearn":"A cut is feedback to train on, not the end of playing.","persona":"Veer","source":"reframe / rejection"},
  {"id":"bn-1200","cat":"reframe-setback","type":"branch","hook":"You posted art online and got a harsh comment.","options":[{"text":"Feel the sting, keep what's useful, drop the cruelty","consequence":"You take the signal, not the venom, and keep creating.","outcome":"steady","best":true},{"text":"Delete everything and never share again","consequence":"One harsh comment isn't the whole verdict; keep what helps."}],"debrief":"You can learn from feedback without letting cruelty define you.","relearn":"Keep useful feedback, drop the cruelty, keep going.","persona":"any","source":"reframe / criticism"},
  {"id":"bn-1201","cat":"reframe-setback","type":"branch","hook":"You lost your phone with weeks of notes before exams.","options":[{"text":"Let yourself be upset, then ask friends to share notes","consequence":"You solve the real problem instead of spiralling.","outcome":"resourceful","best":true},{"text":"Decide the exams are doomed now","consequence":"It's a real setback, but notes can be rebuilt with help."}],"debrief":"A rough setback often has a practical fix once the panic passes.","relearn":"Feel the setback, then look for the practical next step.","persona":"any","source":"bounce-back / problem-solving"},
  {"id":"bn-1202","cat":"reframe-setback","type":"branch","hook":"You fumbled your speech in the inter-school competition.","options":[{"text":"Acknowledge the nerves, then note one thing to practise","consequence":"You keep your confidence and a clear next step.","outcome":"learning","best":true},{"text":"Vow you're terrible at public speaking and stop","consequence":"A fumble is a practice point, not proof you can't speak."}],"debrief":"A fumble names what to rehearse next, not a permanent label.","relearn":"A stumble in front of others is a rehearsal note, not a verdict.","persona":"Riya","source":"spotlight effect / reframe"},
  {"id":"bn-1203","cat":"reframe-setback","type":"branch","hook":"You didn't clear an entrance test you'd pinned everything on.","options":[{"text":"Grieve it properly, then explore the other routes you have","consequence":"You stay open to real, good alternatives.","outcome":"open","best":true},{"text":"Decide there's nothing left for you","consequence":"One test isn't the only route; other good paths exist."}],"debrief":"One closed route doesn't erase the many others still open.","relearn":"One test result isn't your only path; others stay open.","persona":"any","source":"many paths forward"},
  {"id":"bn-1204","cat":"reframe-setback","type":"branch","hook":"You snapped at a friend while stressed and now feel awful.","options":[{"text":"Sit with the regret, then apologise honestly","consequence":"You repair the bond and learn your stress triggers.","outcome":"repairing","best":true},{"text":"Decide you're a bad friend and avoid them","consequence":"One snap isn't your whole self; an honest sorry can repair it."}],"debrief":"A slip with a friend is a moment to repair, not a label on you.","relearn":"One bad moment isn't your identity; repair beats avoiding.","persona":"any","source":"reframe / self-compassion"},
  {"id":"bn-1205","cat":"reframe-setback","type":"branch","hook":"Your marks dropped after you fell ill mid-term.","options":[{"text":"See the context honestly, then plan a steady catch-up","consequence":"You judge yourself fairly and rebuild at your pace.","outcome":"fair","best":true},{"text":"Beat yourself up as if nothing happened","consequence":"Illness is context; be as fair to yourself as you'd be to a friend."}],"debrief":"Setbacks have context; judge yourself as fairly as you'd judge a friend.","relearn":"Read your setback in context, then make a fair catch-up plan.","persona":"any","source":"self-compassion / reframe"},
  {"id":"bn-1206","cat":"reframe-setback","type":"branch","hook":"You missed the deadline for a scholarship form.","options":[{"text":"Feel the frustration, then look for the next opportunity","consequence":"You move forward instead of stewing in one miss.","outcome":"forward","best":true},{"text":"Decide good chances never come your way","consequence":"One missed form isn't the last chance; more will come."}],"debrief":"One missed chance isn't the last; look ahead to the next.","relearn":"A missed opportunity stings, but it's not the final one.","persona":"any","source":"reframe / setbacks not permanent"},
  {"id":"bn-1207","cat":"reframe-setback","type":"branch","hook":"You came last in the class quiz after switching schools.","options":[{"text":"Allow the discomfort, then ask what the new syllabus expects","consequence":"You adjust instead of branding yourself 'the weak one'.","outcome":"adjusting","best":true},{"text":"Conclude you don't belong at this school","consequence":"A new school takes adjusting; one quiz isn't your level."}],"debrief":"A rough start at a new place is adjusting, not your true level.","relearn":"A hard first result somewhere new is adjustment, not your ceiling.","persona":"any","source":"reframe / context"},
  {"id":"bn-1208","cat":"reframe-setback","type":"reflect","hook":"Lensy: what would you say to a friend who'd just got this same result?","prompt":"Picture it.","options":["\"It's one result\"","\"You'll find a way\"","\"I'm proud you tried\""],"affirm":"Now offer yourself those same kind, true words.","relearn":"Speak to yourself after a setback as kindly as you'd speak to a friend.","persona":"any","source":"self-compassion"},
  {"id":"bn-1209","cat":"reframe-setback","type":"reflect","hook":"Lensy: think of a past setback that, looking back, taught you something.","prompt":"Bring one to mind.","options":["A flop that grew me","A loss I learned from","A miss that redirected me"],"affirm":"That's proof setbacks can become lessons; this one can too.","relearn":"Past setbacks often turned into lessons; this one can as well.","persona":"any","source":"reframing"},
  {"id":"bn-1210","cat":"reframe-setback","type":"reflect","hook":"Lensy: add 'yet' to one thing you feel you can't do.","prompt":"Say it with 'yet'.","options":["\"I can't do it yet\"","\"I'm not there yet\"","\"I haven't got it yet\""],"affirm":"That little word keeps the door to growth wide open.","relearn":"Adding 'yet' turns a dead end into a next step.","persona":"any","source":"growth mindset ('not yet')"},
  {"id":"bn-1211","cat":"reframe-setback","type":"reflect","hook":"Lensy: name one thing this setback can't take away from you.","prompt":"Think of one.","options":["My effort","People who care","What I've already learned"],"affirm":"A result is one moment; it can't erase who you are.","relearn":"A setback is one moment; it can't take your worth or your people.","persona":"Riya","source":"reframe / worth"},
  {"id":"bn-1212","cat":"reframe-setback","type":"reflect","hook":"Lensy: what's one small thing you could do tomorrow after this knock?","prompt":"Pick one.","options":["Redo one question","Ask for one tip","Just show up again"],"affirm":"One small step forward is how a comeback really begins.","relearn":"After a setback, one small next step beats waiting to feel 'fixed'.","persona":"any","source":"small steps / reframe"},
  {"id":"bn-1213","cat":"reframe-setback","type":"reflect","hook":"Lensy: when a result hurts, what's a truer thing to tell yourself than 'I'm a failure'?","prompt":"Find your line.","options":["\"I failed this, not at life\"","\"This is hard, not hopeless\"","\"I can try again\""],"affirm":"That honest reframe holds both the hurt and the way forward.","relearn":"'I failed this' is true; 'I am a failure' is not.","persona":"Veer","source":"failure as event"},
  {"id":"bn-1214","cat":"reframe-setback","type":"reflect","hook":"Lensy: who could remind you that one result doesn't define you?","prompt":"Bring them to mind.","options":["A close friend","A teacher I trust","Someone in my family"],"affirm":"Reaching to your people is part of how you reframe and recover.","relearn":"The right person can remind you a setback isn't your identity.","persona":"any","source":"reframe / support"},
  {"id":"bn-1215","cat":"reframe-setback","type":"reflect","hook":"Lensy: what did this mistake actually teach you for next time?","prompt":"Name the lesson.","options":["What to revise more","What to start earlier","What to ask about"],"affirm":"Turning a mistake into a lesson is exactly how data works for you.","relearn":"A mistake turns into useful data the moment you name its lesson.","persona":"any","source":"failure as learning"},
  {"id":"bn-1216","cat":"reframe-setback","type":"sort","hook":"Sort: an honest reframe, or toxic 'good vibes only'?","items":[{"id":"a","text":"\"It hurts, and I can still try again\""},{"id":"b","text":"\"Just smile, it's nothing\""},{"id":"c","text":"\"This is hard, and I'll get help\""},{"id":"d","text":"\"Bad feelings aren't allowed\""},{"id":"e","text":"\"I'm gutted, and there's a next step\""},{"id":"f","text":"\"Stop being sad, only positivity\""}],"bins":[{"id":"honest","label":"Honest reframe","valence":"pos"},{"id":"toxic","label":"Toxic positivity","valence":"neg"}],"key":{"a":"honest","b":"toxic","c":"honest","d":"toxic","e":"honest","f":"toxic"},"relearn":"An honest reframe holds the hurt and the way forward; toxic positivity skips the hurt.","persona":"any","source":"reframing vs toxic positivity"},
  {"id":"bn-1217","cat":"reframe-setback","type":"sort","hook":"Sort: 'I failed at a thing' or 'I am a failure'?","items":[{"id":"a","text":"\"I failed this test\""},{"id":"b","text":"\"I'm a total failure\""},{"id":"c","text":"\"That attempt didn't work\""},{"id":"d","text":"\"I'm worthless\""},{"id":"e","text":"\"I lost this round\""},{"id":"f","text":"\"I'll never be good at anything\""}],"bins":[{"id":"event","label":"It's an event","valence":"pos"},{"id":"identity","label":"It's not your identity","valence":"neg"}],"key":{"a":"event","b":"identity","c":"event","d":"identity","e":"event","f":"identity"},"relearn":"'I failed at a thing' is true; 'I am a failure' is the myth to drop.","persona":"Veer","source":"failure as event"},
  {"id":"bn-1218","cat":"reframe-setback","type":"sort","hook":"Sort: this setback is temporary, or 'forever' thinking?","items":[{"id":"a","text":"\"This term was tough\""},{"id":"b","text":"\"It'll always be this bad\""},{"id":"c","text":"\"I'm stuck right now\""},{"id":"d","text":"\"Nothing will ever change\""},{"id":"e","text":"\"This is a hard patch\""},{"id":"f","text":"\"I'll feel like this forever\""}],"bins":[{"id":"temp","label":"Temporary","valence":"pos"},{"id":"forever","label":"'Forever' trap","valence":"neg"}],"key":{"a":"temp","b":"forever","c":"temp","d":"forever","e":"temp","f":"forever"},"relearn":"Setbacks are temporary; 'always' and 'forever' are spiral traps.","persona":"Riya","source":"setbacks not permanent"},
  {"id":"bn-1219","cat":"reframe-setback","type":"sort","hook":"Sort: useful lesson, or harsh self-attack?","items":[{"id":"a","text":"\"I'll start revising earlier\""},{"id":"b","text":"\"I'm just stupid\""},{"id":"c","text":"\"I need to ask for help sooner\""},{"id":"d","text":"\"I ruin everything\""},{"id":"e","text":"\"I'll check my answers next time\""},{"id":"f","text":"\"I deserve to fail\""}],"bins":[{"id":"lesson","label":"Useful lesson","valence":"pos"},{"id":"attack","label":"Harsh self-attack","valence":"neg"}],"key":{"a":"lesson","b":"attack","c":"lesson","d":"attack","e":"lesson","f":"attack"},"relearn":"Mistakes give useful lessons; self-attacks just keep you down.","persona":"any","source":"failure as learning / self-compassion"},
  {"id":"bn-1220","cat":"reframe-setback","type":"sort","hook":"Sort: a 'yet' thought, or a 'never' thought?","items":[{"id":"a","text":"\"I can't do it yet\""},{"id":"b","text":"\"I'll never get this\""},{"id":"c","text":"\"I'm still learning this\""},{"id":"d","text":"\"It's hopeless for me\""},{"id":"e","text":"\"I'm getting closer\""},{"id":"f","text":"\"There's no point trying\""}],"bins":[{"id":"yet","label":"'Yet' (growth)","valence":"pos"},{"id":"never","label":"'Never' (stuck)","valence":"neg"}],"key":{"a":"yet","b":"never","c":"yet","d":"never","e":"yet","f":"never"},"relearn":"'Yet' keeps growth open; 'never' shuts the door.","persona":"any","source":"growth mindset ('not yet')"},
  {"id":"bn-1221","cat":"reframe-setback","type":"sort","hook":"Sort: keeps you growing after a knock, or shuts you down?","items":[{"id":"a","text":"\"What can I try differently?\""},{"id":"b","text":"\"Everyone saw, I'm done\""},{"id":"c","text":"\"One step at a time\""},{"id":"d","text":"\"There's no coming back\""},{"id":"e","text":"\"This is data for next time\""},{"id":"f","text":"\"I should just give up\""}],"bins":[{"id":"grow","label":"Keeps you growing","valence":"pos"},{"id":"shut","label":"Shuts you down","valence":"neg"}],"key":{"a":"grow","b":"shut","c":"grow","d":"shut","e":"grow","f":"shut"},"relearn":"'What can I try' and 'one step at a time' keep you growing after a knock.","persona":"Veer","source":"cognitive reframing"},
  {"id":"bn-1222","cat":"reframe-setback","type":"match","hook":"Match the setback thought to a steadier, truer reply.","pairs":[{"left":"\"I failed, so I'm a failure\"","right":"I failed at a thing, not at being me"},{"left":"\"I can't do this\"","right":"I can't do this yet"},{"left":"\"This mistake was a waste\"","right":"This mistake shows my next fix"},{"left":"\"Everyone will remember\"","right":"People forget faster than I fear"},{"left":"\"One result ruins everything\"","right":"One result is just one moment"}],"relearn":"Each setback thought has a steadier, truer reply.","persona":"any","source":"reframing"},
  {"id":"bn-1223","cat":"reframe-setback","type":"match","hook":"Match the slip-up to the lesson it offers.","pairs":[{"left":"Ran out of time in the exam","right":"Practise timing on past papers"},{"left":"Misread the question","right":"Underline what's actually asked"},{"left":"Blanked on stage","right":"Rehearse the opening lines more"},{"left":"Forgot a formula","right":"Make a quick recall sheet"},{"left":"Started revising too late","right":"Begin a little earlier next time"}],"relearn":"Every slip-up points to a concrete thing to try next time.","persona":"any","source":"failure as learning"},
  {"id":"bn-1224","cat":"reframe-setback","type":"match","hook":"Match the harsh thought to the kinder, truer one.","pairs":[{"left":"\"I'm stupid\"","right":"I'm still learning this"},{"left":"\"I always mess up\"","right":"I messed up this one time"},{"left":"\"I let everyone down\"","right":"I can own it and make it right"},{"left":"\"I should be perfect\"","right":"My best is genuinely enough"},{"left":"\"I'll never recover\"","right":"This is hard, and it will pass"}],"relearn":"Swap each harsh thought for a kinder, truer one.","persona":"Riya","source":"self-compassion"},
  {"id":"bn-1225","cat":"reframe-setback","type":"match","hook":"Match the setback to one good next step.","pairs":[{"left":"Bombed a test","right":"Map the topics to redo"},{"left":"Got rejected from a team","right":"Ask what to train next"},{"left":"Stuck replaying a mistake","right":"Name the lesson, then shift"},{"left":"Compared yourself to a friend","right":"Track your own progress"},{"left":"Feeling gutted","right":"Let yourself feel it first"}],"relearn":"Every setback has a doable next step once the sting eases.","persona":"any","source":"bounce-back"},
  {"id":"bn-1226","cat":"reframe-setback","type":"match","hook":"Match the myth to the truth that flips it.","pairs":[{"left":"Reframing means faking it","right":"Reframing holds hurt and hope"},{"left":"A setback is permanent","right":"A setback is one moment"},{"left":"Marks measure my worth","right":"Marks measure one exam, not me"},{"left":"I must cope alone","right":"Reaching out is part of bouncing back"},{"left":"Mistakes are wasted","right":"Mistakes are useful data"}],"relearn":"Each reframe myth has a true flip that holds up.","persona":"any","source":"reframing"},
  {"id":"bn-1227","cat":"reframe-setback","type":"match","hook":"Match how it feels now to where it can lead.","pairs":[{"left":"Stung by criticism","right":"Keep what helps, drop the rest"},{"left":"Embarrassed in class","right":"Others forget by tomorrow"},{"left":"Behind after illness","right":"A fair, steady catch-up plan"},{"left":"Cut from a team","right":"A clear thing to train"},{"left":"Lost a close match","right":"One game, not the season"}],"relearn":"A painful moment now can point to a useful step next.","persona":"any","source":"reframe"},
  {"id":"bn-1228","cat":"reframe-setback","type":"match","hook":"Match the doorway that closed to the one still open.","pairs":[{"left":"Missed a course cut-off","right":"Other courses and routes exist"},{"left":"Failed a first attempt","right":"A later attempt can pass"},{"left":"Changed streams","right":"A path that fits you better"},{"left":"Didn't get the role","right":"A different chance to grow"},{"left":"Missed one deadline","right":"The next opportunity ahead"}],"relearn":"When one door closes, others usually stay open.","persona":"any","source":"many paths forward"},
  {"id":"bn-1229","cat":"reframe-setback","type":"build","hook":"Build an honest reframe for a setback (not 'good vibes only').","prompt":"Order the steps so the hurt is named first.","pieces":["name the feeling honestly","state one true thing that helps","add 'yet' or a next step","keep your worth separate from the result"],"mode":"sequence","key":["name the feeling honestly","state one true thing that helps","add 'yet' or a next step","keep your worth separate from the result"],"relearn":"An honest reframe names the hurt first, then the way forward.","persona":"any","source":"reframing vs toxic positivity"},
  {"id":"bn-1230","cat":"reframe-setback","type":"build","hook":"Build the steps to turn a failed test into a study map.","prompt":"Put the steps in order.","pieces":["let the disappointment land","go through which questions you lost","group them into topics to redo","plan one topic to start with"],"mode":"sequence","key":["let the disappointment land","go through which questions you lost","group them into topics to redo","plan one topic to start with"],"relearn":"Feel it, then turn a failed test into a topic-by-topic study map.","persona":"Veer","source":"failure as learning"},
  {"id":"bn-1231","cat":"reframe-setback","type":"build","hook":"Build a 'shrink the comeback' plan after a big slip.","prompt":"Order it from feeling to first action.","pieces":["accept the slip happened","pick the smallest useful step","do that one step today","notice that you started again"],"mode":"sequence","key":["accept the slip happened","pick the smallest useful step","do that one step today","notice that you started again"],"relearn":"Shrink a comeback to one small step you can do today.","persona":"any","source":"small steps"},
  {"id":"bn-1232","cat":"reframe-setback","type":"build","hook":"Build the parts of a reframe that holds BOTH truths.","prompt":"Assemble what an honest reframe includes.","pieces":["the hurt, named honestly","what you can still do","the worth that stays yours","support you can lean on"],"mode":"assemble","key":["the hurt, named honestly","what you can still do","the worth that stays yours","support you can lean on"],"relearn":"A reframe that holds: the hurt, what you can do, your worth, and support.","persona":"any","source":"reframing"},
  {"id":"bn-1233","cat":"reframe-setback","type":"build","hook":"Build the steps to break a 'replaying the mistake' loop.","prompt":"Put them in order.","pieces":["notice you're replaying it","name one lesson from it","do one grounding thing now","gently return if it loops back"],"mode":"sequence","key":["notice you're replaying it","name one lesson from it","do one grounding thing now","gently return if it loops back"],"relearn":"Break a replay loop: notice it, name the lesson, ground, repeat gently.","persona":"any","source":"rumination"},
  {"id":"bn-1234","cat":"reframe-setback","type":"build","hook":"Build a kinder response to your own mistake.","prompt":"Order it from feeling to action.","pieces":["say what you'd tell a friend","drop the 'always/never' words","name one real thing to improve","take one fair next step"],"mode":"sequence","key":["say what you'd tell a friend","drop the 'always/never' words","name one real thing to improve","take one fair next step"],"relearn":"Treat your own mistake the way you'd treat a friend's, then act.","persona":"Riya","source":"self-compassion"},
  {"id":"bn-1235","cat":"reframe-setback","type":"build","hook":"Build what to keep and drop from a harsh comment on your work.","prompt":"Assemble what to actually carry forward.","pieces":["the one useful pointer","your right to keep creating","the people who back you","the part of you that tried"],"mode":"assemble","key":["the one useful pointer","your right to keep creating","the people who back you","the part of you that tried"],"relearn":"From harsh feedback, carry the useful pointer and your right to keep going.","persona":"any","source":"reframe / criticism"},
  {"id":"bn-1236","cat":"reframe-setback","type":"build","hook":"Build the reframe for 'one result ruins my future'.","prompt":"Assemble the truths that flip it.","pieces":["one result is one moment","many paths forward exist","my worth isn't a score","I can ask people for help"],"mode":"assemble","key":["one result is one moment","many paths forward exist","my worth isn't a score","I can ask people for help"],"relearn":"One result is one moment; many paths, your worth, and people remain.","persona":"any","source":"many paths forward"},
  {"id":"bn-1237","cat":"reframe-setback","type":"role-play","hook":"A friend says your low marks 'prove' you're not smart.","setup":"Reframe it out loud, honestly. Say:","yourLine":[{"text":"\"It stings, but one test isn't proof of who I am.\"","best":true},{"text":"\"Yeah, I guess I'm just not smart.\""}],"relearn":"A low result is one event, not proof of who you are.","persona":"Veer","source":"failure as event"},
  {"id":"bn-1238","cat":"reframe-setback","type":"role-play","hook":"You're about to give up on a skill you keep fumbling.","setup":"Add the magic word. Say:","yourLine":[{"text":"\"I can't do this yet, and 'yet' means I keep going.\"","best":true},{"text":"\"I can't do this, so what's the point.\""}],"relearn":"Adding 'yet' keeps growth possible instead of shutting it down.","persona":"any","source":"growth mindset ('not yet')"},
  {"id":"bn-1239","cat":"reframe-setback","type":"role-play","hook":"A classmate teases you about flubbing your turn in assembly.","setup":"Hold your ground, kindly. Say:","yourLine":[{"text":"\"It was awkward, but honestly everyone forgets these by tomorrow.\"","best":true},{"text":"\"You're right, I can never show my face again.\""}],"relearn":"Public stumbles fade from others' minds far faster than you fear.","persona":"Riya","source":"spotlight effect"},
  {"id":"bn-1240","cat":"reframe-setback","type":"role-play","hook":"You're talking yourself down after a mistake on a project.","setup":"Talk to yourself like a friend. Say:","yourLine":[{"text":"\"I'd never call a friend useless for this; I won't say it to me.\"","best":true},{"text":"\"I'm useless and I always wreck things.\""}],"relearn":"Speak to yourself after a slip as kindly as you would to a friend.","persona":"any","source":"self-compassion"},
  {"id":"bn-1241","cat":"reframe-setback","type":"role-play","hook":"A friend is spiralling after one bad result, calling it the end.","setup":"Offer the honest reframe. Say:","yourLine":[{"text":"\"This really hurts, and there's still a way forward from here.\"","best":true},{"text":"\"Yeah, that's it, your future's basically over.\""}],"relearn":"A true reframe holds both: it hurts, AND there's a way forward.","persona":"any","source":"reframing vs denial"},
  {"id":"bn-1242","cat":"reframe-setback","type":"role-play","hook":"You didn't make the shortlist and feel like a write-off.","setup":"Reframe the 'no'. Say:","yourLine":[{"text":"\"A 'no' this time is feedback, not a final score on me.\"","best":true},{"text":"\"I didn't make it, so I'm clearly just not good enough.\""}],"relearn":"A 'no' is feedback to learn from, not a verdict on your worth.","persona":"any","source":"reframe / rejection"},
  {"id":"bn-1243","cat":"reframe-setback","type":"role-play","hook":"You keep saying you 'ruined everything' after one slip.","setup":"Catch the all-or-nothing. Say:","yourLine":[{"text":"\"I slipped on one thing; that's not 'everything' and not 'always'.\"","best":true},{"text":"\"I ruin everything I touch, every time.\""}],"relearn":"'Always' and 'everything' are spiral traps; one slip is one slip.","persona":"any","source":"reframe / all-or-nothing"},
  {"id":"bn-1244","cat":"reframe-setback","type":"role-play","hook":"A relative says your dropped rank means you've 'wasted the year'.","setup":"Reframe it for yourself, calmly. Say:","yourLine":[{"text":"\"One dip isn't a wasted year; I'm learning what to change.\"","best":true},{"text":"\"You're right, the whole year's a write-off now.\""}],"relearn":"One dip in results is a bump to learn from, not a wasted year.","persona":"Riya","source":"setbacks not permanent"},
  {"id":"bn-1260","cat":"support-friend","type":"role-play","persona":"any","source":"peer support / presence","hook":"A friend texts at night that they can't stop crying.","setup":"Be present, not panicked. Reply:","yourLine":[{"text":"\"I'm here. You don't have to explain, just talk to me.\"","best":true},{"text":"\"It's late, can we talk tomorrow?\""}],"relearn":"Showing up in the moment tells a friend they're not alone."},
  {"id":"bn-1261","cat":"support-friend","type":"role-play","persona":"Riya","source":"peer support","hook":"A friend failed their pre-board and won't come to school.","setup":"Reach out without pressure. Say:","yourLine":[{"text":"\"No lecture, I just miss you. Want me to come over?\"","best":true},{"text":"\"You can't hide forever, just come back.\""}],"relearn":"Offering presence beats pushing; let a friend feel safe to return."},
  {"id":"bn-1262","cat":"support-friend","type":"role-play","persona":"any","source":"peer support / reassure","hook":"A friend keeps saying sorry for being 'a burden'.","setup":"Reassure them honestly. Say:","yourLine":[{"text":"\"You're never a burden. I want to be here for you.\"","best":true},{"text":"\"Yeah it is a lot, but it's fine I guess.\""}],"relearn":"Telling a friend they're not a burden keeps the door open."},
  {"id":"bn-1263","cat":"support-friend","type":"role-play","persona":"Veer","source":"what to say","hook":"Your friend's parents compare them to a cousin and they feel worthless.","setup":"Name their worth beyond marks. Say:","yourLine":[{"text":"\"Your marks aren't your worth. You're more than a rank.\"","best":true},{"text":"\"Well, maybe just study harder then.\""}],"relearn":"Reminding a friend they're more than a score steadies them."},
  {"id":"bn-1264","cat":"support-friend","type":"role-play","persona":"any","source":"peer support","hook":"A quiet friend finally opens up but you feel awkward.","setup":"Stay even if it's awkward. Say:","yourLine":[{"text":"\"I'm glad you told me. Take all the time you need.\"","best":true},{"text":"Change the subject to dodge the awkwardness"}],"relearn":"Sitting with discomfort beats escaping it; just stay."},
  {"id":"bn-1265","cat":"support-friend","type":"role-play","persona":"Counsellor","source":"safeguarding / crisis","hook":"A friend says everyone would be better off without them.","setup":"Take it seriously, route up. Say:","yourLine":[{"text":"\"I'm really glad you told me. Let's get a trusted adult right now.\"","best":true},{"text":"\"Don't say that, you're fine, let's just play.\""}],"relearn":"Words about not being here route to a trusted adult immediately."},
  {"id":"bn-1266","cat":"support-friend","type":"role-play","persona":"any","source":"peer support / belonging","hook":"A friend is being left out of the group chat and is hurting.","setup":"Stand with them. Say:","yourLine":[{"text":"\"That's not okay, and I've got your back.\"","best":true},{"text":"\"Just ignore it, they'll get bored.\""}],"relearn":"Standing beside a left-out friend means they aren't alone."},
  {"id":"bn-1267","cat":"support-friend","type":"role-play","persona":"any","source":"peer support","hook":"A friend cried in the washroom and asks you to act normal.","setup":"Honour them and offer more. Say:","yourLine":[{"text":"\"Sure. And whenever you want to talk, I'm right here.\"","best":true},{"text":"\"Okay, forget it happened\" and never check back"}],"relearn":"You can respect a friend's pace and still leave the door open."},
  {"id":"bn-1268","cat":"support-friend","type":"role-play","persona":"Counsellor","source":"safeguarding / secrets","hook":"A friend is hurting themselves and begs you to keep it secret.","setup":"Care more than the secret. Say:","yourLine":[{"text":"\"I care too much to keep this. Let's tell an adult together.\"","best":true},{"text":"\"Okay, I won't tell anyone, ever.\""}],"relearn":"Never keep a safety secret; caring means getting an adult in."},
  {"id":"bn-1269","cat":"support-friend","type":"role-play","persona":"any","source":"grief / presence","hook":"A friend lost a parent and you don't know what to say.","setup":"Presence over perfect words. Say:","yourLine":[{"text":"\"I don't have the right words, but I'm not leaving your side.\"","best":true},{"text":"Avoid them because you might say the wrong thing"}],"relearn":"When words fail, showing up still says everything."},
  {"id":"bn-1270","cat":"support-friend","type":"role-play","persona":"Veer","source":"spot the signs","hook":"A friend keeps making jokes about giving up on everything.","setup":"Check it gently, don't laugh it off. Say:","yourLine":[{"text":"\"That joke worried me a bit. Are you actually okay?\"","best":true},{"text":"Laugh along so it stays light"}],"relearn":"A worrying 'joke' is worth a gentle, direct check-in."},
  {"id":"bn-1271","cat":"support-friend","type":"role-play","persona":"Counsellor","source":"safeguarding / escalate","hook":"A friend tells you their home feels unsafe.","setup":"Believe them and route up. Say:","yourLine":[{"text":"\"Thank you for trusting me. Let's tell a trusted adult who can help.\"","best":true},{"text":"\"Maybe you're imagining it, it'll pass.\""}],"relearn":"Believe a friend on safety and bring in a trusted adult."},
  {"id":"bn-1272","cat":"support-friend","type":"role-play","persona":"any","source":"supporter self-care","hook":"You've been carrying a friend's worries and feel exhausted.","setup":"Set a kind limit. Say:","yourLine":[{"text":"\"I love being here for you, and I need a trusted adult in this too.\"","best":true},{"text":"Keep going alone until you burn out"}],"relearn":"You can care and still bring an adult in; you're not their therapist."},
  {"id":"bn-1273","cat":"support-friend","type":"role-play","persona":"any","source":"help-routing / limits","hook":"A friend says talking to you helps but nothing really changes.","setup":"Point to more support. Say:","yourLine":[{"text":"\"I'm glad I help. Some of this also needs a grown-up who knows more.\"","best":true},{"text":"\"I've got this, you don't need anyone else.\""}],"relearn":"Being a friend is great; some struggles also need a trusted adult."},
  {"id":"bn-1274","cat":"support-friend","type":"role-play","persona":"any","source":"reframe / spotlight","hook":"A friend was dumped publicly and is humiliated.","setup":"Shrink the spotlight kindly. Say:","yourLine":[{"text":"\"This stings now, but people forget fast. I'm here meanwhile.\"","best":true},{"text":"\"Everyone's talking about it, that's rough.\""}],"relearn":"Remind a friend stumbles fade fast, and stay beside them."},
  {"id":"bn-1275","cat":"support-friend","type":"role-play","persona":"any","source":"peer support / noticing","hook":"A friend keeps cancelling and going silent for days.","setup":"Reach out without blame. Say:","yourLine":[{"text":"\"No pressure at all, just checking you're okay. I'm here.\"","best":true},{"text":"\"Fine, if you don't want to talk, forget it.\""}],"relearn":"A no-blame check-in reaches a withdrawn friend best."},
  {"id":"bn-1276","cat":"support-friend","type":"role-play","persona":"Riya","source":"exam pressure","hook":"A friend is panicking the night before boards.","setup":"Calm and steady them. Say:","yourLine":[{"text":"\"Breathe with me. One exam isn't your whole future. I've got you.\"","best":true},{"text":"\"You should've studied more, too late now.\""}],"relearn":"Steady a panicking friend; remind them one exam isn't everything."},
  {"id":"bn-1277","cat":"support-friend","type":"role-play","persona":"Counsellor","source":"safeguarding / cyber","hook":"A friend confides they're being bullied online.","setup":"Take it seriously, plan a next step. Say:","yourLine":[{"text":"\"That's not your fault. Let's save proof and tell a trusted adult.\"","best":true},{"text":"\"Just log off, it's only the internet.\""}],"relearn":"Online bullying is real; keep proof and route to a trusted adult."},
  {"id":"bn-1278","cat":"support-friend","type":"role-play","persona":"Counsellor","source":"reach-out / route","hook":"A friend says they feel numb and empty for weeks now.","setup":"Name it and point to help. Say:","yourLine":[{"text":"\"Weeks of feeling like that matters. Let's tell an adult who can help.\"","best":true},{"text":"\"You'll snap out of it, don't worry.\""}],"relearn":"Lasting low feelings are a reason to tell a trusted adult."},
  {"id":"bn-1279","cat":"support-friend","type":"role-play","persona":"any","source":"self-worth","hook":"A friend brushes off praise and only sees their flaws.","setup":"Reflect their worth back. Say:","yourLine":[{"text":"\"I see how hard you try. You're worth more than one slip.\"","best":true},{"text":"\"Maybe if you did better you'd feel better.\""}],"relearn":"Reflecting a friend's worth back gently counters self-criticism."},
  {"id":"bn-1280","cat":"support-friend","type":"role-play","persona":"Riya","source":"exam pressure / support","hook":"A friend is scared their parents will be furious about their result.","setup":"Offer to be there for the talk. Say:","yourLine":[{"text":"\"That's scary. I can sit with you before you tell them, if it helps.\"","best":true},{"text":"\"Just don't tell them and hope they don't ask.\""}],"relearn":"Standing with a friend through a hard conversation makes it lighter."},
  {"id":"bn-1281","cat":"support-friend","type":"role-play","persona":"any","source":"peer support","hook":"A friend trusts you with something heavy and watches your reaction.","setup":"Stay warm and steady. Say:","yourLine":[{"text":"\"Thank you for trusting me. I'm not going anywhere.\"","best":true},{"text":"React with shock so they regret telling you"}],"relearn":"A calm, warm reaction tells a friend it's safe to keep talking."},
  {"id":"bn-1282","cat":"support-friend","type":"role-play","persona":"any","source":"peer support / noticing","hook":"A friend says they're 'fine' but their eyes say otherwise.","setup":"Open a gentle door. Say:","yourLine":[{"text":"\"You don't have to be fine with me. I'm here whenever.\"","best":true},{"text":"\"Cool, fine works\" and move on"}],"relearn":"Naming that they don't have to be fine invites the real answer."},
  {"id":"bn-1283","cat":"support-friend","type":"role-play","persona":"Veer","source":"reach-out","hook":"Your friend keeps helping everyone and never lets anyone help them.","setup":"Offer them the same care. Say:","yourLine":[{"text":"\"You're always there for us. Let me be there for you now.\"","best":true},{"text":"\"You're strong, you don't need help.\""}],"relearn":"Even the strong-seeming friend deserves support, not pressure."},
  {"id":"bn-1284","cat":"support-friend","type":"role-play","persona":"Counsellor","source":"reach-out / route","hook":"A friend in another city messages that they feel hopeless.","setup":"Bridge them to nearby help. Say:","yourLine":[{"text":"\"I'm with you. Is there an adult near you we can tell tonight?\"","best":true},{"text":"\"Wish I could help but I'm too far away.\""}],"relearn":"Even from afar, you can help a friend reach a nearby trusted adult."},
  {"id":"bn-1285","cat":"support-friend","type":"role-play","persona":"any","source":"peer support","hook":"A friend opened up once, then pulled back, embarrassed.","setup":"Keep the door open, no pressure. Say:","yourLine":[{"text":"\"Nothing's weird between us. I'm still here, whenever you want.\"","best":true},{"text":"\"You got all dramatic earlier, what was that?\""}],"relearn":"After someone opens up, keep things normal and the door open."},
  {"id":"bn-1286","cat":"support-friend","type":"branch","persona":"Counsellor","source":"safeguarding / secrets","hook":"A friend confides a danger but swears you to total secrecy.","options":[{"text":"Tell them you care too much to stay silent, and get a trusted adult","consequence":"You keep your friend safer, even if it's hard.","outcome":"protective","best":true},{"text":"Promise to keep the secret no matter what","consequence":"A safety secret is one you don't keep; care means getting help."}],"debrief":"Never keep a danger secret; caring means bringing in a trusted adult.","relearn":"Don't promise secrecy on safety; route to an adult."},
  {"id":"bn-1287","cat":"support-friend","type":"branch","persona":"Riya","source":"peer support","hook":"A friend stopped replying to the group chat for days and went quiet.","options":[{"text":"Reach out one-to-one and ask how they're really doing","consequence":"They feel remembered and start talking again.","outcome":"caring","best":true},{"text":"Wait for them to come back when they're ready","consequence":"Silence can mean struggle; a gentle nudge shows you care."}],"debrief":"Going quiet can be a quiet cry for company; reach out directly.","relearn":"When a friend goes quiet, reach out one-to-one rather than wait."},
  {"id":"bn-1288","cat":"support-friend","type":"branch","persona":"Counsellor","source":"safeguarding / crisis","hook":"A friend hints at dark thoughts while you walk home.","options":[{"text":"Stay calm, take it seriously, and get a trusted adult now","consequence":"You help keep your friend safe.","outcome":"protective","best":true},{"text":"Tell them to stop being dramatic","consequence":"Dark thoughts are a 'tell an adult now' moment, not drama."}],"debrief":"Dark thoughts are too big to hold alone; bring in a trusted adult at once.","relearn":"If a friend has dark thoughts, get a trusted adult right away."},
  {"id":"bn-1289","cat":"support-friend","type":"branch","persona":"any","source":"supporter self-care","hook":"A friend keeps venting to you late at night and it's hurting your sleep.","options":[{"text":"Set a kind boundary on timing and suggest other support too","consequence":"You stay caring without burning out.","outcome":"balanced","best":true},{"text":"Stay up every night however tired you get","consequence":"Boundaries let you keep helping; one person can't be everything."}],"debrief":"You can care for a friend and still protect your own limits.","relearn":"Set kind boundaries so supporting a friend doesn't drain you."},
  {"id":"bn-1290","cat":"support-friend","type":"branch","persona":"Counsellor","source":"help-routing","hook":"A friend wants help telling a teacher but is terrified.","options":[{"text":"Offer to go with them to the teacher","consequence":"Having you there makes the hard step possible.","outcome":"supportive","best":true},{"text":"Tell them to just do it alone","consequence":"Going with a friend makes reaching help far easier."}],"debrief":"Walking in with a friend turns a scary step into a doable one.","relearn":"Offer to go with a friend to a trusted adult."},
  {"id":"bn-1291","cat":"support-friend","type":"branch","persona":"Veer","source":"peer support","hook":"A friend brushes their own pain off with a laugh.","options":[{"text":"Gently let them know it's safe to be real with you","consequence":"They sense the door is open and may share.","outcome":"caring","best":true},{"text":"Laugh along and move on","consequence":"Brushing it off teaches them to hide; gently invite the truth."}],"debrief":"Letting a friend know it's safe to be real opens the door.","relearn":"Invite a friend to be real instead of laughing pain off."},
  {"id":"bn-1292","cat":"support-friend","type":"branch","persona":"Riya","source":"exam pressure","hook":"A friend keeps comparing their marks to everyone's and spirals.","options":[{"text":"Remind them their worth isn't a rank and listen","consequence":"They feel less alone in the spiral.","outcome":"steadying","best":true},{"text":"Compare your own marks to make a point","consequence":"Comparison fuels the spiral; worth isn't a rank."}],"debrief":"Stepping out of comparison and listening steadies a spiralling friend.","relearn":"Remind a friend worth isn't a rank, and just listen."},
  {"id":"bn-1293","cat":"support-friend","type":"branch","persona":"Counsellor","source":"safeguarding / escalate","hook":"A friend tells you they're being hurt at home.","options":[{"text":"Believe them and help them reach a trusted adult","consequence":"Your friend gets real protection and support.","outcome":"protective","best":true},{"text":"Tell them to keep the peace and stay quiet","consequence":"Harm at home needs a trusted adult, not silence."}],"debrief":"Believe a friend on safety and route to a trusted adult right away.","relearn":"If a friend is being hurt, help them reach a trusted adult."},
  {"id":"bn-1294","cat":"support-friend","type":"branch","persona":"Counsellor","source":"reach-out / route","hook":"A friend says talking helps but their low mood lasts for weeks.","options":[{"text":"Tell them this also needs an adult and offer the helpline","consequence":"They get help beyond what a friend can give.","outcome":"routing","best":true},{"text":"Insist you alone are enough for them","consequence":"Weeks-long low mood needs more than a friend; route up."}],"debrief":"Some struggles outgrow a friend; weeks-long low mood routes to an adult.","relearn":"Lasting low mood needs a trusted adult, not just a friend."},
  {"id":"bn-1295","cat":"support-friend","type":"branch","persona":"any","source":"peer support / belonging","hook":"Your friend is being mocked in a group and looks crushed.","options":[{"text":"Step in beside them and shift the moment","consequence":"They know they aren't alone in it.","outcome":"ally","best":true},{"text":"Stay quiet so you don't become a target","consequence":"Standing beside a friend matters more than staying safe alone."}],"debrief":"Standing beside a mocked friend tells them they're not alone.","relearn":"Stand with a friend who's being mocked, don't stay silent."},
  {"id":"bn-1296","cat":"support-friend","type":"sort","persona":"any","source":"what to say","hook":"Sort: opens a friend up, or shuts them down?","items":[{"id":"a","text":"\"Tell me what's going on\""},{"id":"b","text":"\"You always make it dramatic\""},{"id":"c","text":"\"I'm here, no rush\""},{"id":"d","text":"\"Just be happy already\""},{"id":"e","text":"\"That sounds heavy, I'm listening\""},{"id":"f","text":"\"Other people cope, why can't you?\""}],"bins":[{"id":"open","label":"Opens up","valence":"pos"},{"id":"shut","label":"Shuts down","valence":"neg"}],"key":{"a":"open","b":"shut","c":"open","d":"shut","e":"open","f":"shut"},"relearn":"Curious, patient words open a friend up; comparison and 'be happy' shut them down."},
  {"id":"bn-1297","cat":"support-friend","type":"sort","persona":"Counsellor","source":"safeguarding / signs","hook":"Sort: be a friend through it, or get an adult now?","items":[{"id":"a","text":"Friend nervous about a test"},{"id":"b","text":"Friend talks of not wanting to be here"},{"id":"c","text":"Friend sad after an argument"},{"id":"d","text":"Friend being hurt at home"},{"id":"e","text":"Friend bored on a long weekend"},{"id":"f","text":"Friend hurting themselves"}],"bins":[{"id":"friend","label":"Be a friend","valence":"pos"},{"id":"adult","label":"Tell an adult now","valence":"tell"}],"key":{"a":"friend","b":"adult","c":"friend","d":"adult","e":"friend","f":"adult"},"relearn":"Everyday worries you can sit with; danger or dark thoughts route to a trusted adult now."},
  {"id":"bn-1298","cat":"support-friend","type":"sort","persona":"any","source":"what resilience really is","hook":"Sort: a real support move, or just toxic positivity?","items":[{"id":"a","text":"\"It's okay to not be okay\""},{"id":"b","text":"\"Good vibes only!\""},{"id":"c","text":"Sitting with them quietly"},{"id":"d","text":"\"Just look on the bright side\""},{"id":"e","text":"Helping them reach an adult"},{"id":"f","text":"\"Don't be so negative\""}],"bins":[{"id":"real","label":"Real support","valence":"pos"},{"id":"toxic","label":"Toxic positivity","valence":"neg"}],"key":{"a":"real","b":"toxic","c":"real","d":"toxic","e":"real","f":"toxic"},"relearn":"Real support holds the hard feeling; toxic positivity tells a friend to skip it."},
  {"id":"bn-1299","cat":"support-friend","type":"sort","persona":"any","source":"peer support / boundaries","hook":"Sort: caring for a friend, or crossing a line?","items":[{"id":"a","text":"Keeping what they shared private"},{"id":"b","text":"Posting their secret for laughs"},{"id":"c","text":"Checking in the next day"},{"id":"d","text":"Telling everyone 'for their own good'"},{"id":"e","text":"Asking how you can help"},{"id":"f","text":"Pressuring them to 'just get over it'"}],"bins":[{"id":"care","label":"Caring","valence":"pos"},{"id":"cross","label":"Crosses a line","valence":"neg"}],"key":{"a":"care","b":"cross","c":"care","d":"cross","e":"care","f":"cross"},"relearn":"Privacy and gentle check-ins care for a friend; gossip and pressure cross a line."},
  {"id":"bn-1300","cat":"support-friend","type":"sort","persona":"any","source":"supporter self-care","hook":"Sort: looking after yourself, or running yourself down?","items":[{"id":"a","text":"Resting after a heavy talk"},{"id":"b","text":"Skipping sleep to reply all night"},{"id":"c","text":"Telling an adult so you're not alone in it"},{"id":"d","text":"Pretending you're fine when you're not"},{"id":"e","text":"Asking your own friend for support"},{"id":"f","text":"Feeling you must fix everything yourself"}],"bins":[{"id":"self","label":"Self-care","valence":"pos"},{"id":"run","label":"Running yourself down","valence":"neg"}],"key":{"a":"self","b":"run","c":"self","d":"run","e":"self","f":"run"},"relearn":"Support lasts when you rest, share the load, and don't carry it alone."},
  {"id":"bn-1301","cat":"support-friend","type":"sort","persona":"Counsellor","source":"spot the signs","hook":"Sort: a sign a friend may need help, or just a normal off-day?","items":[{"id":"a","text":"Withdrawing from everyone for weeks"},{"id":"b","text":"Quiet after a tiring day"},{"id":"c","text":"Giving away things they love"},{"id":"d","text":"Skipping a hangout once"},{"id":"e","text":"Saying everything feels pointless"},{"id":"f","text":"Grumpy before lunch"}],"bins":[{"id":"sign","label":"A real sign","valence":"uhoh"},{"id":"normal","label":"Normal off-day","valence":"neutral"}],"key":{"a":"sign","b":"normal","c":"sign","d":"normal","e":"sign","f":"normal"},"relearn":"Lasting withdrawal, giving things away, and 'pointless' are signs to tell a trusted adult."},
  {"id":"bn-1302","cat":"support-friend","type":"match","persona":"any","source":"peer support","hook":"Match the situation to the right support move.","pairs":[{"left":"Friend just needs to vent","right":"Listen, don't jump to fixes"},{"left":"Friend hints at danger","right":"Bring in a trusted adult now"},{"left":"Friend feels invisible","right":"Keep checking in"},{"left":"Friend is scared to ask for help","right":"Offer to go along"},{"left":"Friend hides pain behind jokes","right":"Gently say you noticed"}],"relearn":"Match your move to what your friend actually needs."},
  {"id":"bn-1303","cat":"support-friend","type":"match","persona":"any","source":"what to say","hook":"Match the brush-off to what to say instead.","pairs":[{"left":"\"Toughen up\"","right":"\"It's okay to not be okay\""},{"left":"\"You're fine\"","right":"\"You don't have to be fine with me\""},{"left":"\"Others have it worse\"","right":"\"Your feelings matter too\""},{"left":"\"Just move on\"","right":"\"Take all the time you need\""},{"left":"\"Stop crying\"","right":"\"Let it out, I'm right here\""}],"relearn":"Trade dismissals for words that make space for the feeling."},
  {"id":"bn-1304","cat":"support-friend","type":"match","persona":"Counsellor","source":"spot the signs","hook":"Match each warning sign to the caring response.","pairs":[{"left":"Friend gone quiet for weeks","right":"Reach out and ask how they are"},{"left":"Friend says life feels pointless","right":"Get a trusted adult now"},{"left":"Friend stops eating with you","right":"Check in gently, no judging"},{"left":"Friend gives prized things away","right":"Treat it as serious, tell an adult"},{"left":"Friend jokes about giving up","right":"Ask if they're really okay"}],"relearn":"Notice the signs and respond with care; route danger to an adult."},
  {"id":"bn-1305","cat":"support-friend","type":"match","persona":"Counsellor","source":"help-routing","hook":"Match the worry to who can help with it.","pairs":[{"left":"Everyday stress about a test","right":"You, as a steady friend"},{"left":"Weeks of low, heavy mood","right":"A trusted adult or Tele-MANAS"},{"left":"Friend feels left out","right":"You, by including them"},{"left":"Friend being hurt at home","right":"A trusted adult who can act"},{"left":"Friend nervous about a talk","right":"You, by going along"}],"relearn":"Some worries a friend can hold; danger and lasting low mood need an adult."},
  {"id":"bn-1306","cat":"support-friend","type":"match","persona":"any","source":"supporter self-care","hook":"Match looking-after-yourself to the unhealthy version.","pairs":[{"left":"Resting after a hard talk","right":"Replying all night, no sleep"},{"left":"Sharing the load with an adult","right":"Carrying it all alone"},{"left":"Knowing your limits","right":"Trying to be their therapist"},{"left":"Asking for your own support","right":"Pretending you're fine"},{"left":"Taking a breather","right":"Burning out in silence"}],"relearn":"Healthy support has limits, rest, and shared load, not solo burnout."},
  {"id":"bn-1307","cat":"support-friend","type":"match","persona":"Veer","source":"what to say","hook":"Match the friend's words to a steady reply.","pairs":[{"left":"\"I'm such a failure\"","right":"\"One result isn't who you are\""},{"left":"\"Nobody gets it\"","right":"\"I'm trying to, tell me more\""},{"left":"\"I can't do this\"","right":"\"You can't do it yet, and I'm here\""},{"left":"\"Everyone's ahead of me\"","right":"\"Your path is your own\""},{"left":"\"I don't matter\"","right":"\"You matter, and I mean that\""}],"relearn":"Meet a friend's hardest words with steady, honest reassurance."},
  {"id":"bn-1308","cat":"support-friend","type":"reflect","persona":"any","source":"peer support (evidence)","hook":"Lensy: think of a friend who once just listened when you struggled. How did it feel?","prompt":"What do you remember?","options":["Less alone","Lighter","Safe"],"affirm":"One person who just listens can change a whole hard day; you can be that too.","relearn":"Being the friend who listens genuinely helps someone feel less alone."},
  {"id":"bn-1309","cat":"support-friend","type":"reflect","persona":"Counsellor","source":"help-routing","hook":"Lensy: who in your life would you go to if a friend was in real danger?","prompt":"Who comes to mind?","options":["A parent","A teacher","A counsellor"],"affirm":"Knowing your trusted adult before a crisis makes it easier to reach out fast.","relearn":"Know your trusted adult before a crisis so reaching out is fast."},
  {"id":"bn-1310","cat":"support-friend","type":"reflect","persona":"any","source":"peer support / noticing","hook":"Lensy: when a friend seems off, what's one small way you could check in this week?","prompt":"What feels doable?","options":["A quick message","Sit with them","Just ask"],"affirm":"A small, genuine check-in can be the thing that helps a friend open up.","relearn":"A small, genuine check-in can help a friend open up."},
  {"id":"bn-1311","cat":"support-friend","type":"reflect","persona":"any","source":"what to say","hook":"Lensy: what's one small thing you could say to a friend who's hurting?","prompt":"What feels true to you?","options":["\"I'm here\"","\"Tell me more\"","\"Take your time\""],"affirm":"Small, honest words like 'I'm here' often help a friend more than any fix.","relearn":"Small honest words help a hurting friend more than fixes."},
  {"id":"bn-1312","cat":"support-friend","type":"reflect","persona":"any","source":"supporter self-care","hook":"Lensy: helping a friend can be heavy. How might you refill yourself afterward?","prompt":"What works for you?","options":["Rest","Talk to someone","Time outside"],"affirm":"Refilling yourself isn't selfish; it's how you keep being there for others.","relearn":"Refilling yourself is how you keep showing up for others."},
  {"id":"bn-1313","cat":"support-friend","type":"reflect","persona":"any","source":"peer support","hook":"Lensy: think of a time you wished someone had just stayed instead of fixing things.","prompt":"What do you notice?","options":["Presence helps","Fixing isn't needed","Just stay"],"affirm":"Often a friend doesn't need solutions, just someone who stays.","relearn":"Sometimes a friend just needs you to stay, not to fix it."},
  {"id":"bn-1314","cat":"support-friend","type":"reflect","persona":"any","source":"peer support / trust","hook":"Lensy: what would make it feel safe for a friend to be real with you?","prompt":"What comes up?","options":["No judging","Keeping it private","Patience"],"affirm":"Friends open up where it's safe: no judging, private, patient is the door.","relearn":"No judging, private, and patient is what makes it safe to open up."},
  {"id":"bn-1315","cat":"support-friend","type":"build","persona":"any","source":"peer support / routine","hook":"Build the order for being there when a friend opens up.","prompt":"Build the order for being there when a friend opens up.","pieces":["Listen fully","Validate the feeling","Ask what they need","Offer to reach an adult if needed"],"mode":"sequence","key":["Listen fully","Validate the feeling","Ask what they need","Offer to reach an adult if needed"],"relearn":"Listen, validate, ask what they need, then route to help if it's big."},
  {"id":"bn-1316","cat":"support-friend","type":"build","persona":"any","source":"peer support","hook":"Build a kit of things that actually help a struggling friend.","prompt":"Build a kit of things that actually help a struggling friend.","pieces":["Patient listening","Showing up again","Keeping it private","Mocking them","Spreading their secret"],"mode":"assemble","key":["Patient listening","Showing up again","Keeping it private"],"relearn":"Real support is patient listening, showing up, and keeping it private."},
  {"id":"bn-1317","cat":"support-friend","type":"build","persona":"Counsellor","source":"safeguarding / route","hook":"Build the steps to help a friend in danger reach an adult.","prompt":"Build the steps to help a friend in danger reach an adult.","pieces":["Stay calm","Tell them you care","Go with them to a trusted adult","Don't keep it secret"],"mode":"sequence","key":["Stay calm","Tell them you care","Go with them to a trusted adult","Don't keep it secret"],"relearn":"Stay calm, show you care, go with them, and never keep a safety secret."},
  {"id":"bn-1318","cat":"support-friend","type":"build","persona":"any","source":"what to say","hook":"Build phrases that open a door for a quiet friend.","prompt":"Build phrases that open a door for a quiet friend.","pieces":["\"I noticed you've seemed down\"","\"I'm here if you want to talk\"","\"No rush at all\"","\"Just snap out of it\"","\"Others have it worse\""],"mode":"assemble","key":["\"I noticed you've seemed down\"","\"I'm here if you want to talk\"","\"No rush at all\""],"relearn":"Noticing, offering presence, and no pressure open a door for a quiet friend."},
  {"id":"bn-1319","cat":"support-friend","type":"build","persona":"any","source":"supporter self-care","hook":"Build a supporter self-care plan so you don't burn out.","prompt":"Build a supporter self-care plan so you don't burn out.","pieces":["Rest after heavy talks","Share the load with an adult","Keep your own hobbies","Reply at all hours","Carry it alone"],"mode":"assemble","key":["Rest after heavy talks","Share the load with an adult","Keep your own hobbies"],"relearn":"Rest, shared load, and your own life keep you able to support others."},
  {"id":"bn-1320","cat":"support-friend","type":"build","persona":"any","source":"peer support / noticing","hook":"Build the order for checking in on a withdrawn friend.","prompt":"Build the order for checking in on a withdrawn friend.","pieces":["Reach out gently","Listen without judging","Ask how they're really doing","Offer to bring in help"],"mode":"sequence","key":["Reach out gently","Listen without judging","Ask how they're really doing","Offer to bring in help"],"relearn":"Reach out, listen, ask how they really are, then offer help."},
  {"id":"bn-1321","cat":"support-friend","type":"build","persona":"Counsellor","source":"spot the signs","hook":"Build the signs that mean 'tell a trusted adult now'.","prompt":"Build the signs that mean 'tell a trusted adult now'.","pieces":["Talk of not wanting to be here","Hurting themselves","Giving prized things away","Being a bit quiet","One bad mood"],"mode":"assemble","key":["Talk of not wanting to be here","Hurting themselves","Giving prized things away"],"relearn":"Dark talk, self-harm, and giving things away mean tell a trusted adult now."},
  {"id":"bn-1322","cat":"support-friend","type":"build","persona":"Riya","source":"reframe / support","hook":"Build a reassuring message for a friend ashamed of a bad result.","prompt":"Build a reassuring message for a friend ashamed of a bad result.","pieces":["\"One result isn't your worth\"","\"This feeling will pass\"","\"I'm here either way\"","\"You should be embarrassed\"","\"Everyone's judging you\""],"mode":"assemble","key":["\"One result isn't your worth\"","\"This feeling will pass\"","\"I'm here either way\""],"relearn":"Worth isn't a result, the sting fades, and you stay; that reassures a friend."},
  {"id":"bn-1323","cat":"support-friend","type":"strike-rewrite","persona":"Counsellor","source":"safeguarding / secrets","hook":"If a friend tells you a secret, you must keep it no matter what.","myth":{"un":"If a friend tells you a secret, you must keep it no matter what.","re":"Some 'secrets' about safety must be shared with a trusted adult.","why":"Keeping a danger secret can leave a friend in harm; caring means getting help."},"relearn":"Never keep a safety secret; route to a trusted adult."},
  {"id":"bn-1324","cat":"support-friend","type":"strike-rewrite","persona":"any","source":"peer support","hook":"A good friend always knows the perfect thing to fix the problem.","myth":{"un":"A good friend always knows the perfect thing to fix the problem.","re":"A good friend listens and stays; you don't need the perfect fix.","why":"Presence and listening help more than solutions a teen can't give."},"relearn":"Being present matters more than having the perfect fix."},
  {"id":"bn-1325","cat":"support-friend","type":"strike-rewrite","persona":"any","source":"peer support / limits","hook":"If you can't make your friend happy again, you've failed them.","myth":{"un":"If you can't make your friend happy again, you've failed them.","re":"You can't fix someone's feelings, and being there is still huge.","why":"Feelings take time; showing up steadily is real, valuable support."},"relearn":"You can't fix feelings, but showing up still matters hugely."},
  {"id":"bn-1326","cat":"support-friend","type":"strike-rewrite","persona":"Counsellor","source":"help-routing","hook":"Bringing in an adult means you betrayed your friend's trust.","myth":{"un":"Bringing in an adult means you betrayed your friend's trust.","re":"Getting a trusted adult for a serious thing is caring, not betrayal.","why":"Some struggles are too big for two teens; an adult keeps a friend safe."},"relearn":"Routing to a trusted adult on serious things is care, not betrayal."},
  {"id":"bn-1327","cat":"support-friend","type":"strike-rewrite","persona":"any","source":"what resilience really is","hook":"Telling a sad friend to 'just be positive' will cheer them up.","myth":{"un":"Telling a sad friend to 'just be positive' will cheer them up.","re":"'Just be positive' often makes a friend feel unheard, not better.","why":"Validating the hard feeling helps far more than forced positivity."},"relearn":"Validate the feeling instead of pushing 'just be positive'."},
  {"id":"bn-1328","cat":"support-friend","type":"strike-rewrite","persona":"any","source":"supporter self-care","hook":"A real friend handles all of a struggling mate's pain alone.","myth":{"un":"A real friend handles all of a struggling mate's pain alone.","re":"You're a friend, not a therapist; sharing the load is healthy.","why":"Carrying it all alone burns you out and helps no one long-term."},"relearn":"You're a friend, not a therapist; share the load with an adult."},
  {"id":"bn-1329","cat":"support-friend","type":"strike-rewrite","persona":"Riya","source":"spot the signs","hook":"If a friend hides their pain well, they must be fine.","myth":{"un":"If a friend hides their pain well, they must be fine.","re":"Jokes and happy posts can hide real pain; a gentle check-in helps.","why":"People often mask struggle, so noticing and checking in matters."},"relearn":"Hidden pain is still pain; check in even when a friend 'seems fine'."},
  {"id":"bn-1330","cat":"support-friend","type":"strike-rewrite","persona":"any","source":"supporter self-care","hook":"Helping a friend means you should drop all your own needs.","myth":{"un":"Helping a friend means you should drop all your own needs.","re":"You support a friend best when you also look after yourself.","why":"A rested, supported helper can keep showing up; an empty one can't."},"relearn":"Look after yourself too; that's how you keep supporting others."},
  {"id":"bn-1350","cat":"what-resilience","type":"strike-rewrite","hook":"\"If you cry, you've already lost.\"","myth":{"un":"Crying when something hurts means you've lost or you're weak.","re":"Crying lets the feeling move; you can cry and still keep going.","why":"Naming and releasing a feeling is part of how people recover."},"relearn":"Tears aren't losing; feeling it is how you start to move through.","persona":"Veer","source":"resilience concept"},
  {"id":"bn-1351","cat":"what-resilience","type":"strike-rewrite","hook":"\"A strong person never needs a break.\"","myth":{"un":"Strong people push through without ever stopping to rest.","re":"Rest is part of bouncing back; a break helps you keep going, not quit.","why":"You recover faster with rest than by running on empty."},"relearn":"Resting isn't quitting; it's part of how you bounce back.","persona":"any","source":"resilience concept"},
  {"id":"bn-1352","cat":"what-resilience","type":"strike-rewrite","hook":"\"Be a man, deal with it on your own.\"","myth":{"un":"A real man handles every problem alone and shows nothing.","re":"Real strength includes telling someone; carrying it alone is harder.","why":"People who lean on others get through hard things better."},"relearn":"Handling it alone isn't strength; reaching out is.","persona":"Veer","source":"anti-tough-it-out"},
  {"id":"bn-1353","cat":"what-resilience","type":"strike-rewrite","hook":"\"If it still hurts, you haven't healed.\"","myth":{"un":"You've only recovered once it stops hurting completely.","re":"You can be healing and still feel the ache; both are true at once.","why":"Recovery isn't a clean switch from pain to no pain."},"relearn":"Still hurting doesn't mean failing; healing and ache coexist.","persona":"Riya","source":"resilience concept"},
  {"id":"bn-1354","cat":"what-resilience","type":"strike-rewrite","hook":"\"Other people bounce back, so something's wrong with me.\"","myth":{"un":"Everyone else recovers fast, so my slow recovery means I'm broken.","re":"People hide their struggle; your pace is yours, not a flaw.","why":"You're comparing your inside to their outside."},"relearn":"Your recovery has its own pace; a slow one isn't a broken one.","persona":"Riya","source":"normalising"},
  {"id":"bn-1355","cat":"what-resilience","type":"strike-rewrite","hook":"\"Feeling angry about it makes you a bad person.\"","myth":{"un":"Getting angry about a setback means there's something wrong with you.","re":"Anger is a normal signal; you can feel it without acting badly on it.","why":"Named feelings pass; banned ones tend to leak out sideways."},"relearn":"Anger is allowed; it's a feeling to notice, not a sin.","persona":"any","source":"feelings allowed"},
  {"id":"bn-1356","cat":"what-resilience","type":"strike-rewrite","hook":"\"Resilient people don't get stressed before boards.\"","myth":{"un":"If you were truly resilient, exams wouldn't stress you at all.","re":"Resilient people feel the stress too; they just have ways to cope.","why":"Resilience is handling the pressure, not never feeling it."},"relearn":"Stress before boards is normal; coping with it is the skill.","persona":"Riya","source":"resilience concept"},
  {"id":"bn-1357","cat":"what-resilience","type":"strike-rewrite","hook":"\"Once you break down, you can't come back from it.\"","myth":{"un":"If you break down crying, you're too far gone to recover.","re":"A breakdown is a hard moment, not the end; people come back from it.","why":"One low moment doesn't decide what happens next."},"relearn":"A breakdown is a moment, not a dead end.","persona":"Veer","source":"resilience concept"},
  {"id":"bn-1358","cat":"what-resilience","type":"strike-rewrite","hook":"\"Talking about it just makes it worse.\"","myth":{"un":"Talking about a hard feeling only makes it bigger and worse.","re":"Saying it out loud to a safe person usually shrinks it, not grows it.","why":"A feeling shared with someone you trust feels lighter to carry."},"relearn":"Talking it out tends to ease a feeling, not feed it.","persona":"any","source":"reaching out"},
  {"id":"bn-1359","cat":"what-resilience","type":"strike-rewrite","hook":"\"You should be over it by now.\"","myth":{"un":"There's a deadline; if you're not over it by now, you're failing.","re":"There's no fixed timer; you heal at your own real pace.","why":"Putting healing on a clock just adds pressure to the hurt."},"relearn":"There's no deadline on healing; your pace is valid.","persona":"any","source":"resilience concept"},
  {"id":"bn-1360","cat":"what-resilience","type":"strike-rewrite","hook":"\"Asking for help means you couldn't handle it.\"","myth":{"un":"If you ask for help, it proves you weren't strong enough.","re":"Asking for help is a smart move, not proof you failed.","why":"Knowing when you need backup is its own kind of strength."},"relearn":"Asking for help is a skill, not a failure.","persona":"Veer","source":"reaching out"},
  {"id":"bn-1361","cat":"what-resilience","type":"strike-rewrite","hook":"\"Pretending you're fine is the same as being fine.\"","myth":{"un":"If you act fine on the outside, that counts as actually being fine.","re":"A mask isn't healing; the feeling waits until you face it honestly.","why":"Hiding a feeling doesn't process it, it just postpones it."},"relearn":"Acting okay isn't the same as being okay; honesty is.","persona":"any","source":"anti-toxic-positivity"},
  {"id":"bn-1362","cat":"what-resilience","type":"strike-rewrite","hook":"\"Resilience means nothing ever gets to you.\"","myth":{"un":"Being resilient means hard things just don't affect you.","re":"Things get to resilient people too; they feel it AND find a way on.","why":"Feeling nothing is numbness, not resilience."},"relearn":"Resilience isn't feeling nothing; it's feeling it and moving on.","persona":"any","source":"resilience concept"},
  {"id":"bn-1363","cat":"what-resilience","type":"strike-rewrite","hook":"\"You have to figure your problems out by yourself.\"","myth":{"un":"Real resilience means solving every problem on your own.","re":"Resilience is powered by people; you're not meant to do it solo.","why":"At least one person in your corner is a top protective factor."},"relearn":"You're not meant to cope alone; support is part of resilience.","persona":"Veer","source":"supportive relationships"},
  {"id":"bn-1364","cat":"what-resilience","type":"strike-rewrite","hook":"\"Bad days mean you're going backwards.\"","myth":{"un":"A bad day after a good one means all your progress is gone.","re":"Recovery zig-zags; one rough day doesn't erase the progress.","why":"Healing goes up and down, not in a straight line."},"relearn":"A bad day is part of the zig-zag, not a reset.","persona":"Riya","source":"resilience concept"},
  {"id":"bn-1365","cat":"what-resilience","type":"strike-rewrite","hook":"\"Sensitive people can't be resilient.\"","myth":{"un":"If you feel things deeply, you can't really be resilient.","re":"Feeling deeply and recovering can go together; sensitivity isn't weakness.","why":"Resilience is what you do with feelings, not how few you have."},"relearn":"Feeling deeply and being resilient can both be true of you.","persona":"any","source":"resilience concept"},
  {"id":"bn-1366","cat":"what-resilience","type":"strike-rewrite","hook":"\"If you needed help once, you'll always be weak.\"","myth":{"un":"Reaching out one time marks you as weak forever.","re":"Asking once doesn't define you; it's just a wise move in a hard moment.","why":"Needing support sometimes is human, not a permanent label."},"relearn":"One ask for help doesn't brand you; it's just being human.","persona":"Veer","source":"reaching out"},
  {"id":"bn-1367","cat":"what-resilience","type":"strike-rewrite","hook":"\"You're either born tough or you're not.\"","myth":{"un":"Toughness is fixed at birth; you can't change how you cope.","re":"Coping skills are learned and practised; you can grow them at any age.","why":"Brains and habits keep changing through your teen years."},"relearn":"Coping is learned, not fixed at birth.","persona":"any","source":"resilience is learnable"},
  {"id":"bn-1368","cat":"what-resilience","type":"strike-rewrite","hook":"\"Distracting yourself forever counts as coping.\"","myth":{"un":"If you keep busy enough, you never have to deal with the feeling.","re":"A short break helps, but at some point feeling it is what frees you.","why":"Endless distraction parks the feeling, it doesn't move it through."},"relearn":"A break helps; facing the feeling is what frees it.","persona":"any","source":"bounce-back"},
  {"id":"bn-1369","cat":"what-resilience","type":"strike-rewrite","hook":"\"Worrying about looking weak is just being mature.\"","myth":{"un":"Hiding your struggle to look strong is the grown-up thing to do.","re":"Being real about a struggle is more grown-up than hiding it.","why":"Honesty about hard things builds trust and real strength."},"relearn":"Being honest about struggling is mature, not weak.","persona":"Veer","source":"anti-tough-it-out"},
  {"id":"bn-1370","cat":"what-resilience","type":"strike-rewrite","hook":"\"If you let yourself feel sad, you'll never stop.\"","myth":{"un":"If you let the sadness in, it'll swallow you and never leave.","re":"Feelings rise and fall; let in, a wave of sadness peaks and passes.","why":"Blocked feelings linger; felt ones tend to move through."},"relearn":"Sadness felt is a wave that passes, not a flood you drown in.","persona":"any","source":"feelings allowed"},
  {"id":"bn-1371","cat":"what-resilience","type":"strike-rewrite","hook":"\"Resilient teens don't have problems at home.\"","myth":{"un":"You can only be resilient if your home life is easy.","re":"Resilience grows even in hard homes, often through one caring person.","why":"What protects you most is connection, not a perfect situation."},"relearn":"You can build resilience even when home is hard.","persona":"any","source":"supportive relationships"},
  {"id":"bn-1372","cat":"what-resilience","type":"strike-rewrite","hook":"\"You have to stay positive for everyone else.\"","myth":{"un":"It's your job to seem upbeat so you don't burden anyone.","re":"You're allowed to not be okay; you don't owe anyone a fake smile.","why":"Forcing a happy face for others quietly drains you."},"relearn":"You don't owe anyone forced positivity; honesty is allowed.","persona":"Riya","source":"anti-toxic-positivity"},
  {"id":"bn-1373","cat":"what-resilience","type":"reflect","hook":"Lensy: name one small thing that helps when you feel low. It counts, even if it's tiny.","prompt":"What do you think?","options":["Music helps me","A walk outside","Talking to one person"],"affirm":"You already know things that help you; that's real coping.","relearn":"Noticing what helps you is a coping skill you already have.","persona":"any","source":"self-efficacy"},
  {"id":"bn-1374","cat":"what-resilience","type":"reflect","hook":"Lensy: think of one person you'd tell if a day got really heavy. Got someone in mind?","prompt":"What do you think?","options":["Yes, I do","A friend","A family member"],"affirm":"Having even one safe person is a real source of strength.","relearn":"One safe person to tell is a real protective factor.","persona":"any","source":"supportive relationships"},
  {"id":"bn-1375","cat":"what-resilience","type":"reflect","hook":"Lensy: it's okay to not be okay today. You don't have to fix the feeling right now. Sit with that?","prompt":"What do you think?","options":["Okay","That's a relief","I can just feel it"],"affirm":"Letting yourself not be okay is honest, and it's allowed.","relearn":"It's okay to not be okay; you don't have to fix it instantly.","persona":"any","source":"feelings allowed"},
  {"id":"bn-1376","cat":"what-resilience","type":"reflect","hook":"Lensy: remember a time you were sure you couldn't handle something, but you did. Feel that?","prompt":"What do you think?","options":["Yes","I surprised myself","I got through it"],"affirm":"You've handled harder than you expected before; that's proof.","relearn":"Past bounce-backs are evidence you can cope again.","persona":"Veer","source":"self-efficacy"},
  {"id":"bn-1377","cat":"what-resilience","type":"reflect","hook":"Lensy: your worth isn't your marks, your wins, or your worst day. You're more than a result. Feel it?","prompt":"What do you think?","options":["Yes","I'm more than a score","Hard but true"],"affirm":"You're a whole person, never just one number or one day.","relearn":"Your worth is more than any score or setback.","persona":"Riya","source":"worth beyond marks"},
  {"id":"bn-1378","cat":"what-resilience","type":"reflect","hook":"Lensy: bouncing back can be slow, and slow is still bouncing back. Can you give yourself that time?","prompt":"What do you think?","options":["Yes","I can be patient","Slow is okay"],"affirm":"Going slow is still going forward; your pace is valid.","relearn":"Recovery takes time; slow is still real progress.","persona":"Riya","source":"resilience concept"},
  {"id":"bn-1379","cat":"what-resilience","type":"reflect","hook":"Lensy: feeling it AND finding a way through can both be true. You don't have to pick one. Like that?","prompt":"What do you think?","options":["Yes","Both at once","That helps"],"affirm":"It hurts AND there's a way forward; holding both is real resilience.","relearn":"Resilience holds both: it hurts, and there's a way through.","persona":"any","source":"resilience concept"},
  {"id":"bn-1380","cat":"what-resilience","type":"reflect","hook":"Lensy: think of one tiny step you could take tomorrow, even on a low day. Got one?","prompt":"What do you think?","options":["Yes","Just one small thing","I can manage that"],"affirm":"One small step beats waiting to feel fully fixed first.","relearn":"One small step is enough; you don't have to feel fixed first.","persona":"any","source":"bounce-back"},
  {"id":"bn-1381","cat":"what-resilience","type":"reflect","hook":"Lensy: you'd be kind to a friend who failed. Could you say that same kind thing to yourself?","prompt":"What do you think?","options":["I can try","Yes","Be my own friend"],"affirm":"Talking to yourself like a friend is a real, strong tool.","relearn":"Self-compassion, treating yourself like a friend, is real coping.","persona":"any","source":"self-compassion"},
  {"id":"bn-1382","cat":"what-resilience","type":"reflect","hook":"Lensy: needing help isn't weakness. The strong move is sometimes saying 'I can't do this alone.' Agree?","prompt":"What do you think?","options":["Yes","That's strength too","Good to hear"],"affirm":"Reaching out is one of the strongest things you can do.","relearn":"Reaching out is strength, not weakness.","persona":"Veer","source":"reaching out"},
  {"id":"bn-1383","cat":"what-resilience","type":"reflect","hook":"Lensy: hard feelings are allowed here, all of them. Sad, angry, scared. None of them mean you've failed. Okay?","prompt":"What do you think?","options":["Okay","All feelings allowed","That's a relief"],"affirm":"Every feeling is allowed; none of them is a failure.","relearn":"Hard feelings are allowed and named, never a failure.","persona":"any","source":"feelings allowed"},
  {"id":"bn-1384","cat":"what-resilience","type":"reflect","hook":"Lensy: coping that's real fits your actual life, not a poster slogan. What's one real thing for you?","prompt":"What do you think?","options":["Sleep helps","Talking it out","Time to myself"],"affirm":"Real coping is yours and doable, never a poster slogan.","relearn":"Real resilience is honest and doable, not a slogan.","persona":"any","source":"authenticity"},
  {"id":"bn-1385","cat":"what-resilience","type":"reflect","hook":"Lensy: a setback is one chapter, not the whole story you're writing. Can you hold that today?","prompt":"What do you think?","options":["Yes","One chapter only","My story continues"],"affirm":"A setback is one chapter; your story keeps going.","relearn":"A setback is one moment, not your whole story.","persona":"any","source":"normalising"},
  {"id":"bn-1386","cat":"what-resilience","type":"reflect","hook":"Lensy: you don't have to earn rest by suffering first. Rest is allowed just because you're tired. Okay?","prompt":"What do you think?","options":["Okay","Rest is allowed","I needed that"],"affirm":"Rest is part of recovery; you don't have to earn it.","relearn":"Rest is part of bouncing back, not a reward you must earn.","persona":"any","source":"resilience concept"},
  {"id":"bn-1387","cat":"what-resilience","type":"sort","hook":"Sort: real resilience, or toxic positivity?","items":[{"id":"a","text":"\"This hurts, and I'll find a way through it\""},{"id":"b","text":"\"Just smile, don't think about it\""},{"id":"c","text":"\"I'll feel this first, then make a plan\""},{"id":"d","text":"\"Good vibes only, no sad allowed\""},{"id":"e","text":"\"I can ask someone for help with this\""},{"id":"f","text":"\"Strong people never feel down\""}],"bins":[{"id":"real","label":"Real resilience","valence":"pos"},{"id":"toxic","label":"Toxic positivity","valence":"neg"}],"key":{"a":"real","b":"toxic","c":"real","d":"toxic","e":"real","f":"toxic"},"relearn":"Real resilience allows hard feelings and help; toxic positivity bans them.","persona":"any","source":"anti-toxic-positivity"},
  {"id":"bn-1388","cat":"what-resilience","type":"sort","hook":"Sort: builds resilience, or chips at it?","items":[{"id":"a","text":"A caring person to talk to"},{"id":"b","text":"Bottling everything up inside"},{"id":"c","text":"Reframing a failure as a lesson"},{"id":"d","text":"Harsh self-blame all day"},{"id":"e","text":"Taking one small step forward"},{"id":"f","text":"Telling yourself you're hopeless"}],"bins":[{"id":"builds","label":"Builds it","valence":"pos"},{"id":"chips","label":"Chips at it","valence":"neg"}],"key":{"a":"builds","b":"chips","c":"builds","d":"chips","e":"builds","f":"chips"},"relearn":"Support, reframing and small steps build resilience; bottling and self-blame erode it.","persona":"any","source":"resilience factors"},
  {"id":"bn-1389","cat":"what-resilience","type":"sort","hook":"Sort: a setback you can grow from, or a false harsh story?","items":[{"id":"a","text":"A failed test"},{"id":"b","text":"\"So I'm worthless\""},{"id":"c","text":"A rejection from a team"},{"id":"d","text":"\"I'll never be good enough\""},{"id":"e","text":"A lost match"},{"id":"f","text":"\"Everyone is better than me\""}],"bins":[{"id":"grow","label":"Setback to grow from","valence":"pos"},{"id":"false","label":"False, harsh story","valence":"neg"}],"key":{"a":"grow","b":"false","c":"grow","d":"false","e":"grow","f":"false"},"relearn":"A setback is just an event; 'I'm worthless' is a false story.","persona":"Riya","source":"cognitive"},
  {"id":"bn-1390","cat":"what-resilience","type":"sort","hook":"Sort: real coping, or a way to avoid the feeling?","items":[{"id":"a","text":"Writing down how you feel"},{"id":"b","text":"Scrolling for hours to numb out"},{"id":"c","text":"Telling a friend what's wrong"},{"id":"d","text":"Pretending nothing happened"},{"id":"e","text":"Going for a walk to settle"},{"id":"f","text":"Snapping at people instead"}],"bins":[{"id":"cope","label":"Real coping","valence":"pos"},{"id":"avoid","label":"Avoiding it","valence":"neg"}],"key":{"a":"cope","b":"avoid","c":"cope","d":"avoid","e":"cope","f":"avoid"},"relearn":"Real coping faces the feeling; avoiding just parks it for later.","persona":"any","source":"bounce-back"},
  {"id":"bn-1391","cat":"what-resilience","type":"sort","hook":"Sort: a feeling you're allowed to have, or a false story about you?","items":[{"id":"a","text":"\"I feel really disappointed\""},{"id":"b","text":"\"I'm a total failure\""},{"id":"c","text":"\"I feel angry this happened\""},{"id":"d","text":"\"I ruin everything I touch\""},{"id":"e","text":"\"I feel scared about boards\""},{"id":"f","text":"\"Nobody could ever like me\""}],"bins":[{"id":"feeling","label":"A real feeling","valence":"pos"},{"id":"story","label":"A false story","valence":"neg"}],"key":{"a":"feeling","b":"story","c":"feeling","d":"story","e":"feeling","f":"story"},"relearn":"Feelings are allowed and true; harsh global labels are false stories.","persona":"Riya","source":"cognitive"},
  {"id":"bn-1392","cat":"what-resilience","type":"sort","hook":"Sort: a true thing about resilience, or a myth?","items":[{"id":"a","text":"It's a skill you can build"},{"id":"b","text":"You're born with it or not"},{"id":"c","text":"It's powered by people"},{"id":"d","text":"Real ones never feel pain"},{"id":"e","text":"Recovery takes its own time"},{"id":"f","text":"Bouncing back is instant"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Resilience is a learnable, people-powered skill that takes time.","persona":"any","source":"resilience concept"},
  {"id":"bn-1393","cat":"what-resilience","type":"sort","hook":"Sort: a kind thing to tell yourself, or a harsh one?","items":[{"id":"a","text":"\"That was hard; I did my best\""},{"id":"b","text":"\"I'm so stupid for failing\""},{"id":"c","text":"\"I can try again tomorrow\""},{"id":"d","text":"\"I always mess everything up\""},{"id":"e","text":"\"One bad day isn't the end\""},{"id":"f","text":"\"I don't deserve good things\""}],"bins":[{"id":"kind","label":"Kind to yourself","valence":"pos"},{"id":"harsh","label":"Harsh self-talk","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"Self-compassion sounds like a friend; harsh self-talk tears you down.","persona":"any","source":"self-compassion"},
  {"id":"bn-1394","cat":"what-resilience","type":"match","hook":"Match the resilience ingredient to what it gives you.","pairs":[{"left":"A growth mindset","right":"Room to try again after a flop"},{"left":"A caring person","right":"The sense you're not alone"},{"left":"Small steps","right":"A doable way forward"},{"left":"Self-compassion","right":"A break from harsh self-blame"},{"left":"Honest feeling","right":"Space to actually heal"}],"relearn":"Resilience is built from mindset, support, steps, kindness and honesty.","persona":"any","source":"resilience factors"},
  {"id":"bn-1395","cat":"what-resilience","type":"match","hook":"Match the hard moment to the honest reframe.","pairs":[{"left":"\"I failed the test\"","right":"\"This test went badly, not my whole life\""},{"left":"\"I can't do this\"","right":"\"I can't do this yet\""},{"left":"\"Everyone saw me mess up\"","right":"\"People forget faster than I fear\""},{"left":"\"I'm so behind\"","right":"\"I can take one small step now\""},{"left":"\"I'm all alone in this\"","right":"\"I can tell one person I trust\""}],"relearn":"Honest reframes hold the hurt and a way forward at the same time.","persona":"any","source":"reframing"},
  {"id":"bn-1396","cat":"what-resilience","type":"match","hook":"Match the myth to the truth that flips it.","pairs":[{"left":"Resilient people feel nothing","right":"They feel it, then find a way on"},{"left":"You bounce back instantly","right":"Recovery takes its own time"},{"left":"You must cope alone","right":"Support is a core part of it"},{"left":"It's fixed at birth","right":"It's a skill you can build"},{"left":"Crying means you lost","right":"Feeling it helps you move through"}],"relearn":"Each resilience myth has an honest truth that flips it.","persona":"any","source":"resilience concept"},
  {"id":"bn-1397","cat":"what-resilience","type":"match","hook":"Match what a friend feels to a real way to cope with it.","pairs":[{"left":"Overwhelmed by everything","right":"Pick one tiny step to start"},{"left":"Alone with the feeling","right":"Tell one person you trust"},{"left":"Restless and tense","right":"Move your body or take a walk"},{"left":"Stuck in a thought-spiral","right":"Write the worry down to slow it"},{"left":"Hard on yourself","right":"Talk to you like a good friend"}],"relearn":"Each hard feeling has a small, real tool that meets it.","persona":"any","source":"bounce-toolkit"},
  {"id":"bn-1398","cat":"what-resilience","type":"build","hook":"Build a true picture of what resilience is.","prompt":"Pick the pieces that make up real resilience.","pieces":["feeling the hurt honestly","finding a way through","leaning on people","never feeling anything","faking constant positivity","toughing it out alone"],"mode":"assemble","key":["feeling the hurt honestly","finding a way through","leaning on people"],"relearn":"Resilience is feeling it, finding a way through, and leaning on people.","persona":"any","source":"resilience concept"},
  {"id":"bn-1399","cat":"what-resilience","type":"build","hook":"Build your low-day coping kit from what's real.","prompt":"Pick the tools that actually help on a low day.","pieces":["name the feeling","tell a safe person","take one small step","bottle it all up","force a fake smile","blame yourself harshly"],"mode":"assemble","key":["name the feeling","tell a safe person","take one small step"],"relearn":"A real coping kit: name it, tell someone, take one small step.","persona":"any","source":"bounce-toolkit"},
  {"id":"bn-1400","cat":"what-resilience","type":"build","hook":"Build the order of how a feeling actually moves through you.","prompt":"Put the honest steps in order.","pieces":["notice the feeling","let yourself feel it","name what it is","let it pass and breathe"],"mode":"sequence","key":["notice the feeling","let yourself feel it","name what it is","let it pass and breathe"],"relearn":"Feelings move through: notice, feel, name, let pass.","persona":"any","source":"feelings allowed"},
  {"id":"bn-1401","cat":"what-resilience","type":"build","hook":"Build the things that make resilience grow over time.","prompt":"Pick what genuinely builds resilience.","pieces":["practice coping skills","a person in your corner","rest when you need it","comparing to everyone","hiding every feeling","never asking for help"],"mode":"assemble","key":["practice coping skills","a person in your corner","rest when you need it"],"relearn":"Resilience grows with practice, people and rest.","persona":"any","source":"resilience is learnable"},
  {"id":"bn-1402","cat":"what-resilience","type":"build","hook":"Build the steps to turn a knock into a lesson.","prompt":"Order the steps that move you forward.","pieces":["feel the disappointment","ask what it shows you","pick one thing to change","try the next small step"],"mode":"sequence","key":["feel the disappointment","ask what it shows you","pick one thing to change","try the next small step"],"relearn":"Feel it, find the lesson, change one thing, take the next step.","persona":"Veer","source":"bounce-back"},
  {"id":"bn-1403","cat":"what-resilience","type":"build","hook":"Build a kind self-talk line for after a setback.","prompt":"Pick the pieces that sound like a good friend.","pieces":["this was genuinely hard","I did what I could","I can try again","I'm worthless for failing","I ruin everything","nobody could like me"],"mode":"assemble","key":["this was genuinely hard","I did what I could","I can try again"],"relearn":"Kind self-talk names the hard, your effort, and the next try.","persona":"any","source":"self-compassion"},
  {"id":"bn-1404","cat":"what-resilience","type":"build","hook":"Build what real strength looks like for Veer.","prompt":"Pick the pieces that are actually strong.","pieces":["letting yourself feel it","telling a trusted person","asking for help when stuck","hiding every emotion","handling it all alone","pretending you're fine"],"mode":"assemble","key":["letting yourself feel it","telling a trusted person","asking for help when stuck"],"relearn":"Real strength is feeling it, telling someone, and asking for help.","persona":"Veer","source":"anti-tough-it-out"},
  {"id":"bn-1405","cat":"what-resilience","type":"build","hook":"Build the parts of a realistic comeback.","prompt":"Pick what a real comeback is made of.","pieces":["small steps over time","letting feelings be there","one supportive person","an instant perfect fix","never a single setback","doing it all alone"],"mode":"assemble","key":["small steps over time","letting feelings be there","one supportive person"],"relearn":"Comebacks are small steps, allowed feelings, and one supportive person.","persona":"any","source":"bounce-back"},
  {"id":"bn-1406","cat":"what-resilience","type":"branch","hook":"You failed a test you'd actually studied hard for.","options":[{"text":"Let yourself feel gutted, then look at what to change","consequence":"You feel it, learn from it, and move on a bit stronger.","outcome":"resilient","best":true},{"text":"Decide you're hopeless and stop trying","consequence":"Feel it, yes, then treat it as data; you're not hopeless."}],"debrief":"Feel the disappointment first, then mine it for what to do differently.","relearn":"Feel the setback, then turn it into a lesson.","persona":"Veer","source":"bounce-back"},
  {"id":"bn-1407","cat":"what-resilience","type":"branch","hook":"You've felt low for days and a friend asks if you're okay.","options":[{"text":"Say honestly that you're not great right now","consequence":"Saying it out loud lightens it and your friend stays close.","outcome":"honest","best":true},{"text":"Say 'I'm fine' and change the subject","consequence":"Hiding it leaves you alone with it; being real is allowed."}],"debrief":"Telling a safe person the truth shrinks the weight you carry.","relearn":"It's okay to not be okay; being honest with a safe person helps.","persona":"any","source":"reaching out"},
  {"id":"bn-1408","cat":"what-resilience","type":"branch","hook":"You bombed a presentation in front of the whole class.","options":[{"text":"Cringe, then remember people forget fast and move on","consequence":"You feel it, and the spotlight fades faster than you feared.","outcome":"reframe","best":true},{"text":"Replay it on loop and decide everyone hates you","consequence":"It stings, but people barely remember; you can let it ease."}],"debrief":"Public stumbles fade fast; feel the cringe, then let it go.","relearn":"A public stumble fades; people forget faster than you fear.","persona":"any","source":"spotlight effect"},
  {"id":"bn-1409","cat":"what-resilience","type":"branch","hook":"A coach told you to 'man up' after you got upset at a loss.","options":[{"text":"Let yourself feel it, then talk to someone you trust","consequence":"You honour the feeling and get support; that's real strength.","outcome":"resilient","best":true},{"text":"Bottle it up to look tough","consequence":"Toughing it out alone is harder; feeling it is the stronger move."}],"debrief":"'Man up' is a myth; feeling it and reaching out is the strong way.","relearn":"Real strength is feeling it and reaching out, not toughing it alone.","persona":"Veer","source":"anti-tough-it-out"},
  {"id":"bn-1410","cat":"what-resilience","type":"branch","hook":"You've been stuck in a sad mood and can't shake it today.","options":[{"text":"Do one tiny kind thing for yourself, even if it's small","consequence":"One small step helps more than waiting to feel fully fixed.","outcome":"toolkit","best":true},{"text":"Wait until you feel completely better to do anything","consequence":"Waiting to feel fixed keeps you stuck; one step beats it."}],"debrief":"One small step beats waiting to feel 'fixed' before you act.","relearn":"Take one small step; you don't have to feel fixed first.","persona":"any","source":"bounce-toolkit"},
  {"id":"bn-1411","cat":"what-resilience","type":"branch","hook":"Everyone online seems to be bouncing back faster than you.","options":[{"text":"Remember they post highlights, and go at your own pace","consequence":"You stop comparing and let your own recovery take its time.","outcome":"reframe","best":true},{"text":"Decide something's wrong with you for being slow","consequence":"You see their outside, not their struggle; your pace is fine."}],"debrief":"You're comparing your inside to their highlight reel; go at your pace.","relearn":"Your recovery has its own pace; slow isn't broken.","persona":"Riya","source":"normalising"},
  {"id":"bn-1412","cat":"what-resilience","type":"branch","hook":"A friend says 'just stay positive' when you're really struggling.","options":[{"text":"Tell them you need to feel it first, not skip it","consequence":"You honour the real feeling instead of papering over it.","outcome":"honest","best":true},{"text":"Force a smile and pretend you're fine","consequence":"Forced positivity buries it; feeling it honestly works better."}],"debrief":"Honest coping beats forced positivity; you don't have to fake it.","relearn":"Honest coping beats forced positivity; feel it, don't skip it.","persona":"any","source":"anti-toxic-positivity"},
  {"id":"bn-1413","cat":"what-resilience","type":"branch","hook":"You snapped at your family after a rough day and feel awful.","options":[{"text":"Notice the feeling under it, then apologise and reset","consequence":"You name what's really going on and repair things calmly.","outcome":"toolkit","best":true},{"text":"Decide you're just a bad person and spiral","consequence":"A bad moment isn't a bad person; name it and make it right."}],"debrief":"A hard feeling can leak out sideways; name it and repair.","relearn":"Name the feeling under a slip; you're not a bad person for one moment.","persona":"any","source":"feelings allowed"},
  {"id":"bn-1414","cat":"what-resilience","type":"role-play","hook":"A classmate says you must be 'so chill' since nothing seems to bother you.","setup":"Be honest about what resilience really is. Say:","yourLine":[{"text":"\"Stuff does bother me; I just feel it and find a way through.\"","best":true},{"text":"\"Yeah, nothing ever gets to me.\""}],"relearn":"Resilience isn't feeling nothing; it's feeling it and moving through.","persona":"any","source":"resilience concept"},
  {"id":"bn-1415","cat":"what-resilience","type":"role-play","hook":"Your friend mocks another boy for crying after a loss.","setup":"Push back on the 'crying is weak' myth. Say:","yourLine":[{"text":"\"Crying's not weak; letting it out is how you move on.\"","best":true},{"text":"\"Yeah, real guys don't cry.\""}],"relearn":"Crying isn't weakness; feeling it is how you move through.","persona":"Veer","source":"anti-tough-it-out"},
  {"id":"bn-1416","cat":"what-resilience","type":"role-play","hook":"A friend says they feel weak for needing to talk to someone.","setup":"Reframe reaching out as strength. Say:","yourLine":[{"text":"\"Reaching out isn't weak; it's one of the strongest moves there is.\"","best":true},{"text":"\"Yeah, you should probably just deal with it yourself.\""}],"relearn":"Reaching out is strength, not weakness.","persona":"any","source":"reaching out"},
  {"id":"bn-1417","cat":"what-resilience","type":"role-play","hook":"A friend says 'I should be over this by now' about a hard breakup.","setup":"Take the deadline off their healing. Say:","yourLine":[{"text":"\"There's no timer on this; you heal at your own pace.\"","best":true},{"text":"\"Yeah, you really should be over it already.\""}],"relearn":"There's no deadline on healing; everyone's pace is valid.","persona":"any","source":"resilience concept"},
  {"id":"bn-1418","cat":"what-resilience","type":"role-play","hook":"A friend insists 'positive people just never let things get to them.'","setup":"Tell the honest version. Say:","yourLine":[{"text":"\"Even positive people feel low; they just don't fake it away.\"","best":true},{"text":"\"True, I guess sad people are just doing it wrong.\""}],"relearn":"Honest coping beats faking positivity; everyone feels low sometimes.","persona":"any","source":"anti-toxic-positivity"},
  {"id":"bn-1419","cat":"what-resilience","type":"role-play","hook":"Your sibling says resilience is something 'you've either got or you don't.'","setup":"Tell them it can be built. Say:","yourLine":[{"text":"\"It's a skill, not a birth thing; you can build it with practice.\"","best":true},{"text":"\"Yeah, some people are just born with it.\""}],"relearn":"Resilience is a learnable skill, not a fixed trait.","persona":"any","source":"resilience is learnable"},
  {"id":"bn-1420","cat":"what-resilience","type":"role-play","hook":"A friend says they feel pathetic for being sad about a small thing.","setup":"Make space for the feeling. Say:","yourLine":[{"text":"\"It's not pathetic; if it hurts you, it counts. Want to talk?\"","best":true},{"text":"\"Yeah, that's pretty small to be upset about.\""}],"relearn":"If it hurts you it counts; feelings don't need to be 'big enough.'","persona":"any","source":"feelings allowed"},
  {"id":"bn-1421","cat":"what-resilience","type":"role-play","hook":"A friend brags that they handled a hard year 'totally alone.'","setup":"Gently reframe what real strength is. Say:","yourLine":[{"text":"\"You got through it, but you'd never have to do it alone, you know.\"","best":true},{"text":"\"Respect, doing it solo is the only real way.\""}],"relearn":"Leaning on people is part of resilience, not a weakness.","persona":"Veer","source":"supportive relationships"},
];

